                                                                       class="citation-mark"><sup>4</sup></a>
            все они были наделены посвящением (<em>абхишекой</em>)<a href="#citation-5" id="ref-5"
                                                                     class="citation-mark"><sup>5</sup></a>
            от всех Будд; глубоко постигали (<em>париджняна</em>),<a href="#citation-6" id="ref-6"
