            (<em>svacitta-dṛśya-gocara</em>);<a href="#citation-7" id="ref-7" class="citation-mark"><sup>7</sup></a>
            умели принимать разнообразные формы (<em>рупа</em>),<a href="#citation-8" id="ref-8"
                                                                   class="citation-mark"><sup>8</sup></a>
            наставления (<em>найя</em>)<a href="#citation-9" id="ref-9"
                                          class="citation-mark"><sup>9</sup></a> и воспитательные
