                                                                     class="citation-mark"><sup>16</sup></a>
        </p>
        <p>В то время Бхагаван вышел из дворца Царя Нагов Великого Океана, где пробыл семь дней,<a
                href="#citation-17" id="ref-17" class="citation-mark"><sup>17</sup></a> и был
            встречен бесчисленными (существами, в том числе) Индрой, Брахмой и дочерьми царей нагов.<a
                href="#citation-18" id="ref-18" class="citation-mark"><sup>18</sup></a> Взглянув на
            Ланку на горе Малайя, Бхагаван улыбнулся<a href="#citation-19" id="ref-19"
                                                       class="citation-mark"><sup>19</sup></a> и
            произнёс:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            Эту Дхарму — постигнутую в личном опыте благородной мудростью,<a
                href="#citation-20" id="ref-20" class="citation-mark"><sup>20</sup></a> но
