                                                                              id="ref-21"
                                                                              class="citation-mark"><sup>21</sup></a>
            взгляды иноверцев, а также [путь] шраваков и пратьекабудд, — проявили<a
                href="#citation-22" id="ref-22" class="citation-mark"><sup>22</sup></a> здесь, в
            этом городе Ланка на вершине горы Малайя, прежние Татхагаты, Архаты, Совершенно
            Пробуждённые. И ныне Я, ради Раваны,<a href="#citation-23" id="ref-23"
                                                   class="citation-mark"><sup>23</sup></a> Владыки
            якшей, изложу именно эту Дхарму.
        </blockquote>
<p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6
    mb-6">Подглава 2. Прибытие Раваны и его гимн</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Равана, владыка ракшасов, силой благословения Татхагат<a href="#citation-24" id="ref-24"
                                                                    class="citation-mark"><sup>24</sup></a>
            услышал о Бхагаване и подумал: «Бхагаван вышел из дворца Царя Нагов Великого Океана и
            стоит теперь у самого моря, окружённый бесчисленными Сакрами, Брахмами и девами-нагами.
            Он взирает на волны океана и на умы тех, кто собрался вокруг — умы, движимые ветром
            сознания, поднимающим волны в океане алайя-виджняны.<a href="#citation-25" id="ref-25"
                                                                    class="citation-mark"><sup>25</sup></a>
            Что если мне отправиться к Бхагавану и пригласить Его посетить Ланку? Это принесёт
            долгую пользу, благо и счастье богам и людям».</p>
        <p>После этого Равана, владыка ракшасов, вместе со своей свитой взошёл на колесницу
            Пушпака<a href="#citation-26" id="ref-26" class="citation-mark"><sup>26</sup></a> и
            направился к Бхагавану. Прибыв, он сошёл с колесницы, и вся его свита последовала за
            ним. Трижды обошёл он Бхагавана справа и преклонился перед Ним. Под звуки духовых и
            ударных инструментов он взял в руки вину<a href="#citation-27" id="ref-27"
                                                       class="citation-mark"><sup>27</sup></a> с
            грифом из индранелы<a href="#citation-28" id="ref-28"
                                  class="citation-mark"><sup>28</sup></a> и инкрустированную
            вайдурьей<a href="#citation-29" id="ref-29" class="citation-mark"><sup>29</sup></a> и
            перламутром и прижал её к бедру мягкой тканью, белой, как цветы приянги.<a
                href="#citation-30" id="ref-30" class="citation-mark"><sup>30</sup></a> Следуя ладам
            — шадджа, ришабха, гандхара, дхаивата, нишада, мадхьяма и кайшика,— он умело повёл мелодию
            через грамы, мурчханы и другие музыкальные приёмы.<a href="#citation-31" id="ref-31"
                                                                 class="citation-mark"><sup>31</sup></a>
            Грациозно играя на вине, он пропел гатхи (стихи):</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-lg">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>1. О Владыка, изложи здесь путь Дхармы —</li>
                <li>учение о <strong>только-уме</strong>, о порядке и методе Дхармы;</li>
                <li>о чистом, изначальном отсутствии «я», свободном от всякого устойчивого
                    ошибочного воззрения;<a href="#citation-32" id="ref-32" class="citation-mark"><sup>32</sup></a>
                </li>
                <li>о пути, постигаемом лично.<a href="#citation-33" id="ref-33"
                                                 class="citation-mark"><sup>33</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>2. О Мудрый, настал час направиться в Ланку.</li>
                <li>Ты — Сугата, чьё тело собрано из благих дхарм;</li>
                <li>Ты являешь нирманы и нирмиты<a href="#citation-34" id="ref-34"
                                                   class="citation-mark"><sup>34</sup></a> —
                    деятельность проявления и проявленные формы;
                </li>
                <li>Ты пребываешь в радости, когда Дхарму постигают лично.<a href="#citation-35"
                                                                             id="ref-35"
                                                                             class="citation-mark"><sup>35</sup></a>
                </li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>3. Эта Ланка некогда была обителью прежних Победителей</li>
                <li>и их сыновей — существ, способных принимать бесчисленные формы.</li>
                <li>О Господь, изложи здесь высочайшую Дхарму:</li>
                <li>её услышат якши, владеющие множеством обликов.<a href="#citation-36" id="ref-36"
                                                                     class="citation-mark"><sup>36</sup></a>
                </li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6
    mb-6">Подглава 3. Равана поёт в ритме Тотака</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

        <p>Затем Равана, владыка Ланки, снова запел гатхи, следуя размеру то́така.<a
                href="#citation-37" id="ref-37" class="citation-mark"><sup>37</sup></a></p>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>4. Из чертогов Владыки Океана выйдя,</li>
                <li>Он стоит теперь на берегу.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>5. Как только Будда стал на берегу,</li>
                <li>Равана явился к Нему с апсарами,</li>
                <li>С якшами всех видов</li>
                <li>И с мудрыми попугаями и майнами.<a href="#citation-38" id="ref-38"
                                                       class="citation-mark"><sup>38</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>6. Силой сверхъестественной способности достигнув того места,</li>
                <li>Где стоит Владыка,</li>
                <li>Он сошёл с небесной колесницы Пушпака,</li>
                <li>Поклонился и почтил Татхагату,</li>
                <li>Обратился к Нему, благословлённый силой Владыки Победителей:</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>7. «Я — Равана, Десятиглавый,</li>
                <li>Владыка ракшасов, пришёл сюда.</li>
                <li>Окажи милость моей Ланке</li>
                <li>И всем, кто в этом городе живёт».</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>8. Ведь здесь, на вершине, украшенной драгоценными камнями,</li>
                <li>В центре города</li>
                <li>Прежние Совершенно Пробуждённые</li>
                <li>Открыто провозгласили Дхарму,</li>
                <li>Доступную лишь личному постижению.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>9. И Благословенный на той же вершине,</li>
                <li>Украшенной драгоценными камнями,</li>
                <li>Да изложит чистую, безупречную Дхарму,</li>
                <li>Окружённый сынами Победителя.</li>
                <li>Мы, ныне живущие в Ланке,</li>
                <li>Желаем её услышать.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>10. Это — Сутра Входа в Ланку,</li>
                <li>Воспетая прежними Буддами,</li>
                <li>Превосходящая все способы изложения,</li>
                <li>Лежащая в сфере личного постижения.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>11. Я помню:</li>
                <li>Прежние Будды, окружённые сыновьями Победителя,</li>
                <li>Излагали эту Сутру.</li>
                <li>Пусть и ныне Благословенный провозгласит её.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>12. В будущем времени</li>
                <li>Будды и сыны Будд</li>
                <li>На этой же вершине, украшенной драгоценными камнями,</li>
