                <li>Изложат это же божественное наставление.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>13. Ведь город Ланка — божественный, прекрасный,</li>
                <li>Убранный разнообразными драгоценностями,</li>
                <li>Овеваемый прохладными ветрами с востока,</li>
                <li>Увенчанный сетями драгоценных камней.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>14. Здесь, Владыка, обитают якши,</li>
                <li>Очищенные от привязанности и гнева,</li>
                <li>Погружённые в размышление о пути, постигаемом лично,</li>
                <li>Достигшие цели благодаря прежним Буддам,</li>
                <li>Укоренённые в вере в путь Махаяны,</li>
                <li>Взаимно поддерживающие друг друга.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>15. Есть здесь и якшини, и сыновья якшей,</li>
                <li>Жаждущие услышать Махаяну.</li>
                <li>Приди же, Учитель,</li>
                <li>На гору Малайя в Ланке.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>16. И ракшасы, возглавляемые Кумбхакарной,<a href="#citation-39" id="ref-39"
                    class="citation-mark"><sup>39</sup></a></li>
                <li>Жители этого города,</li>
                <li>Устремлённые к Махаяне,</li>
                <li>Жаждут услышать путь, постигаемый лично.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>17. Они служили Буддам в прошлом</li>
                <li>И ныне готовы свершить то же.</li>
                <li>Из сострадания ко мне, Владыка,</li>
                <li>Приди в Ланку вместе со своими сыновьями.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>18. Прими, великий Мудрец,</li>
                <li>Дворец мой и общество апсар,</li>
                <li>Разнообразные ожерелья</li>
                <li>И прекрасные рощи ашоки.<a href="#citation-40" id="ref-40"
                                               class="citation-mark"><sup>40</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>19. Я — слуга Будд и сыновей Победителя.</li>
                <li>Нет ничего, чем я не пожертвовал бы.</li>
                <li>Окажи милость, великий Мудрец!</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6
    mb-6">Подглава 4. Ответ Бхагавана на просьбу Раваны</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

        <p>Услышав его слова, сказал Владыка трёх миров:</p>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>20. О владыка якшей,</li>
                <li>На этой горе, украшенной драгоценными камнями,</li>
                <li>Прежние Владыки излагали Дхарму, постигаемую лично.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>21. И к тебе они проявили сострадание.</li>
                <li>Будды будущего времени</li>
                <li>Также изложат её на этой горе,</li>
                <li>Украшенной драгоценными камнями.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>22. Эта гора — обитель йогинов,</li>
                <li>Пребывающих в Дхарме здесь и сейчас.</li>
                <li>Ты достоин сострадания,</li>
                <li>О владыка якшей,</li>
                <li>И (иных) Совершенно Пробуждённых, и Моего.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6
    mb-6">Подглава 5. Бхагаван со свитой прибывает в город</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>23/ Одобрив (так его просьбу), Благословенный пребывал в безмолвии,</li>
            <li>Умом утверждённый в покое.</li>
            <li>Затем Он взошёл на колесницу Пушпака,</li>
            <li>Предложенную Раваной.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>24. Равана и другие,</li>
            <li>Вместе с мудрыми сыновьями Победителя,</li>
            <li>Сопровождаемые апсарами,</li>
            <li>Исполняющими радостные танцы и песни,</li>
            <li>Направились в город.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>25. Прибыв в прекрасный город,</li>
            <li>Он вновь получил подношения:</li>
            <li>Его почтили Равана и собрание якшей,</li>
            <li>Якшини, сыновья и дочери якшей,</li>
            <li>Украсив Его ажурными накидками из драгоценных камней.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>26. Равана возложил на шею и грудь</li>
            <li>Благословенного и сыновей Победителя</li>
            <li>Ожерелья, украшенные драгоценными камнями.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>27. Приняв подношения вместе с мудрыми сыновьями Победителя,</li>
            <li>Благословенный явил Дхарму,<a href="#citation-41" id="ref-41"
                                              class="citation-mark"><sup>41</sup></a></li>
            <li>Лежащую в сфере личного постижения.</li>
        </ul>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6
    mb-6">Подглава 6. Просьба к Махамати о вопрошании</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>28. Почитая Махамати как наилучшего из говорящих,</li>
            <li>Равана и собрание якшей</li>
            <li>Вновь и вновь просили его:</li>
        </ul>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Ты — вопрошающий всех Будд</li>
                <li>О Дхарме, лежащей в сфере личного постижения.<a href="#citation-42" id="ref-42"
                                                                    class="citation-mark"><sup>42</sup></a>
                </li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>29. Я, якши и сыновья Победителя,</li>
                <li>Здесь собравшиеся, желаем это услышать.</li>
                <li>Мы, якши и мудрые сыновья Победителя,</li>
                <li>Умоляем тебя: спроси!</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>30. Ты — великий оратор среди тех, кто говорит,</li>
                <li>И предводитель йогинов среди практикующих.</li>
                <li>С верой умоляю тебя, искусный:</li>
                <li>Задай вопрос об этом пути!</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>31. О Дхарме, полностью свободной от пороков</li>
                <li>Тиртхиков, пратьекабудд и шраваков,</li>
                <li>О чистой природе, постигаемой лично,</li>
                <li>Раскрываемой на ступени Будды.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6
    mb-6">Подглава 7. Видение Раваны</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>32. А затем там Благословенный явил горы,</li>
            <li>Украшенные драгоценными камнями,</li>
            <li>И иные божественные вершины,</li>
            <li>Убранные десятками миллионов драгоценностей.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>33. На вершине каждой великой горы</li>
            <li>Он являл Своё собственное присутствие.</li>
            <li>И на каждой из них</li>
            <li>Также пребывал якша Равана.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>34. Всё собрание там было видимо</li>
            <li>На вершине каждой горы,</li>
            <li>И все земли Будд (<em>буддхакшетры</em>) —</li>
            <li>И в каждой — её Владыка.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>35. Там был и владыка ракшасов,</li>
            <li>И все обитатели Ланки.</li>
            <li>Ланка, явленная Победителем,</li>
            <li>Была неотличима от подлинной.</li>
            <li>Там же — рощи ашоки</li>
            <li>И вся красота лесов.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>36. На вершине каждой горы,</li>
            <li>По побуждению Махамати,</li>
            <li>Владыка изложил якшам Дхарму,</li>
            <li>Указующую путь, постигаемый лично.</li>
            <li>На той горе Он полностью изложил</li>
            <li>Сутру в сто тысяч шлок.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>37. Затем Учитель и сыновья Победителя</li>
            <li>Ступили в невидимость.</li>
            <li>И увидел якша Равана</li>
            <li>Себя самого, стоящего во дворце.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>38. Он размышлял:</li>
        </ul>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Что это было? Кто это был?</li>
                <li>Кто изложил? Кто слушал?</li>
                <li>Что видел я? Кто видел?</li>
                <li>Где город? Где Сугата?</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>39. Где те земли? Где Будды, сияющие драгоценностями? Где Сугаты?</li>
                <li>Не сон ли это? Или мираж?</li>
                <li>Не город ли гандхарвов?</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>40. Не обман ли зрения? Не мираж ли в пустыне?</li>
                <li>Не сон ли о родах у бесплодной?</li>
                <li>Не огненное ли колесо от вращающейся головни —</li>
                <li>Всё то, что я здесь видел?<a href="#citation-43" id="ref-43"
                                                 class="citation-mark"><sup>43</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>41. Или же такова природа всех дхарм —</li>
                <li>Она пребывает в сфере ума.</li>
                <li>Но невежды не постигают этого,</li>
                <li>Ослеплённые воображаемыми формами.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>42. Нет ни видящего, ни видимого,</li>
                <li>Ни говорящего, ни речи.</li>
                <li>Ведь всё это — лишь различение (<em>vikalpa</em>).</li>
                <li>Истинная природа Будды и дхарм —</li>
                <li>Недвойственна.</li>
                <li>Те, кто видит лишь явленное,</li>
                <li>Не видят Владыку.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>43. Когда различение прекращается,</li>
                <li>[Ум] не видит Будду.</li>
                <li>Но когда само становление прекращается,</li>
                <li>Тогда воистину видит Совершенно Пробуждённого.<a href="#citation-44"
                                                                     id="ref-44"
                                                                     class="citation-mark"><sup>44</sup></a>
                </li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 8. Преображение Раваны</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Когда Равана, владыка Ланки, пробудился непосредственно,<a href="#citation-45"
                                                                           id="ref-45"
                                                                           class="citation-mark"><sup>45</sup></a>
            </li>
            <li>когда его основа преобразилась (<em>parāvṛttāśraya</em>),<a href="#citation-46"
                                                                            id="ref-46"
                                                                            class="citation-mark"><sup>46</sup></a>
            </li>
            <li>и он узрел, что всё видимое — лишь воспринимаемое собственным умом (<em>svacitta-dṛśya-mātra</em>),<a
                    href="#citation-47" id="ref-47" class="citation-mark"><sup>47</sup></a></li>
            <li>когда он утвердился в сфере безмолвия, где прекратилось движение,<a
                    href="#citation-48" id="ref-48" class="citation-mark"><sup>48</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>тогда, побуждаемый корнями благого, взращёнными в прошлом,<a href="#citation-49"
                                                                             id="ref-49"
                                                                             class="citation-mark"><sup>49</sup></a>
            </li>
            <li>сведущий во всех шастрах [и обладающий] закалённым разумом,<a
                    href="#citation-50" id="ref-50" class="citation-mark"><sup>50</sup></a></li>
            <li>видящий вещи такими, каковы они есть,<a href="#citation-51" id="ref-51"
                                                        class="citation-mark"><sup>51</sup></a></li>
            <li>не нуждающийся в чужом руководстве,<a href="#citation-52" id="ref-52"
                                                      class="citation-mark"><sup>52</sup></a></li>
            <li>искусный в исследовании собственного ума,<a href="#citation-53" id="ref-53"
                                                            class="citation-mark"><sup>53</sup></a>
            </li>
            <li>свободный от рассудочных воззрений,<a href="#citation-54" id="ref-54"
                                                      class="citation-mark"><sup>54</sup></a></li>
            <li>великий йогин, принимающий вселенскую форму,<a href="#citation-55" id="ref-55"
                                                               class="citation-mark"><sup>55</sup></a>
            </li>
            <li>умелый в искусных средствах,<a href="#citation-56" id="ref-56"
                                               class="citation-mark"><sup>56</sup></a></li>
            <li>способный последовательно постигать особенности высших ступеней,<a
                    href="#citation-57" id="ref-57" class="citation-mark"><sup>57</sup></a></li>
            <li>радующийся различению природы ума, интеллекта и различающего сознания,<a href="#citation-58"
                                                                        id="ref-58"
                                                                        class="citation-mark"><sup>58</sup></a>
            </li>
            <li>прекративший тройственную непрерывность видимого,<a href="#citation-59"
                                                                    id="ref-59"
                                                                    class="citation-mark"><sup>59</sup></a>
            </li>
            <li>свободный от всех причинных воззрений тиртхиков,<a href="#citation-60"
                                                                   id="ref-60"
                                                                   class="citation-mark"><sup>60</sup></a>
            </li>
            <li>вошедший во внутреннюю сферу Татхагатагарбхи и ступени Будды,<a
                    href="#citation-61" id="ref-61" class="citation-mark"><sup>61</sup></a></li>
            <li>утвердившийся в мудрости Будды,<a href="#citation-62" id="ref-62"
                                                  class="citation-mark"><sup>62</sup></a> —
            </li>
            <li>он услышал звук, доступный только внутреннему постижению, словно<br>раздающийся
                из пространства:<a href="#citation-63" id="ref-63"
                                   class="citation-mark"><sup>63</sup></a></li>
        </ul>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 9. Наставление Раване</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Прекрасно, прекрасно, владыка Ланки!</li>
                <li>Воистину прекрасно, владыка Ланки!</li>
                <li>Так должен йогин учиться — как ты учишься.</li>
                <li>Так должно созерцать Татхагат и Дхармы — как ты их узрел.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Если же Дхарму видеть иначе, возникнет опора на воззрение полного прекращения.<a
                        href="#citation-64" id="ref-64" class="citation-mark"><sup>64</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Все дхармы следует постигать лично, не привязанным к внешним объектам,</li>
                <li>оставив ум, разум и различающее сознание.<a href="#citation-65" id="ref-65"
                                                                class="citation-mark"><sup>65</sup></a>
                </li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Тебе не следует пребывать в созерцании, падшем в сферу шраваков, пратьекабудд
                    и тиртхиков;<a href="#citation-66" id="ref-66"
                                   class="citation-mark"><sup>66</sup></a></li>
                <li>не следует быть поглощённым историями и преданиями;<a href="#citation-67"
                                                                          id="ref-67"
                                                                          class="citation-mark"><sup>67</sup></a>
                </li>
                <li>не следует держаться воззрения о независимой собственной природе;<a href="#citation-68"
                                                                           id="ref-68"
                                                                           class="citation-mark"><sup>68</sup></a>
                </li>
                <li>не следует упиваться властью и положением;<a href="#citation-69" id="ref-69"
                                                                 class="citation-mark"><sup>69</sup></a>
                </li>
                <li>не следует ограничиваться медитацией шести <em>дхьян</em>.<a href="#citation-70"
                                                                                 id="ref-70"
                                                                                 class="citation-mark"><sup>70</sup></a>
                </li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Таков, владыка Ланки, подлинный путь великого йогина:</li>
                <li>— сокрушающего ложные доктрины,</li>
                <li>— разбивающего ошибочные воззрения,</li>
                <li>— искусного в устранении представления о «я»,</li>
                <li>— искусного в тончайшем повороте сознания.<a
                        href="#citation-71" id="ref-71" class="citation-mark"><sup>71</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Таков путь сыновей Победителя, идущих путём Махаяны.</li>
                <li>Чтобы войти в сферу внутреннего постижения Татхагаты,</li>
                <li>тебе надлежит совершать эту йогу.</li>
                <li>Если этот путь осуществлять так, как ты его осуществляешь, владыка Ланки,</li>
                <li>он будет всё глубже очищаться — ступень за ступенью.</li>
            </ul>

            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Тем путём, что ты принял благодаря мастерству в самадхи,</li>
                <li>не идут шраваки, пратьекабудды и тиртхики —</li>
                <li>незрелые йогины внешних учений лишь воображают его:</li>
                <li>они цепляются за «я» и признаки видимого,<a href="#citation-72" id="ref-72"
                                                                class="citation-mark"><sup>72</sup></a>
                </li>
                <li>следуют за элементами, их качествами и веществами,<a href="#citation-73"
                                                                           id="ref-73"
                                                                           class="citation-mark"><sup>73</sup></a>
                </li>
                <li>укоренены в воззрениях, порождённых неведением,<a href="#citation-74"
                                                                      id="ref-74"
                                                                      class="citation-mark"><sup>74</sup></a>
                </li>
                <li>рассеяны представлением, что шуньята «возникает»,<a href="#citation-75"
                                                                        id="ref-75"
                                                                        class="citation-mark"><sup>75</sup></a>
                </li>
                <li>погружены в различения<a href="#citation-76" id="ref-76"
                                             class="citation-mark"><sup>76</sup></a></li>
                <li>и упали в двойственность обозначаемого и признака.<a href="#citation-77"
                                                                         id="ref-77"
                                                                         class="citation-mark"><sup>77</sup></a>
                </li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Этот путь, владыка Ланки,</li>
                <li>ведёт к обретению вселенской формы,<a
                        href="#citation-78" id="ref-78" class="citation-mark"><sup>78</sup></a></li>
                <li>пробуждает непосредственное постижение собственного
                    пути,<a href="#citation-79" id="ref-79" class="citation-mark"><sup>79</sup></a>
                </li>
                <li>является достижением Махаяны,</li>
                <li>ведёт к обретению высших ступеней (<em>bhūmi</em>),<a
                        href="#citation-80" id="ref-80" class="citation-mark"><sup>80</sup></a></li>
                <li>устраняет завесы (<em>āvaraṇa</em>),</li>
                <li>прекращает волны различных <em>виджнян</em>.<a href="#citation-81" id="ref-81"
                                                                   class="citation-mark"><sup>81</sup></a>
                </li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Таков вход в йогу Махаяны, владыка Ланки,</li>
                <li>а не падение в йогу тиртхиков.</li>
                <li>Ибо йога тиртхиков возникает из привязанности к «я»,</li>
                <li>из двойственного воззрения на природу сознания,</li>
                <li>и потому не приводит к умиротворению.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Поэтому, владыка Ланки, этот смысл должен быть тобой осмыслен —</li>
                <li>так, как ты размышлял, узрев Татхагату.</li>
                <li>Ибо таково — подлинное видение Татхагаты».</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>


    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 10. (Стремление Раваны увидеть Благословенного)</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>И в тот миг у Раваны возникло стремление:</li>
        </ul>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>О, если бы я вновь узрел Благословенного —</li>
                <li>Того, кто владычествует над всеми йогами,</li>
                <li>кто отвращает от ложных путей тиртхиков,</li>
                <li>кто открывает внутреннюю область личного постижения,<a
                        href="#citation-82" id="ref-82" class="citation-mark"><sup>82</sup></a></li>
                <li>чьё знание свободно от сотворённого и чудесных проявлений.<a href="#citation-83"
                                                                                 id="ref-83"
                                                                                 class="citation-mark"><sup>83</sup></a>
                </li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Того, чья мудрость постигается йогинами</li>
                <li>в момент прямого йогического постижения,</li>
                <li>при вхождении во врата самадхи, —</li>
                <li>благодаря такому постижению они и именуются «йогинами».<a href="#citation-84"
                                                                              id="ref-84"
                                                                              class="citation-mark"><sup>84</sup></a>
                </li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Пусть я узрю Того Сострадательного,</li>
                <li>кто иссушает топливо омрачений и прекращает построения ума,</li>
                <li>кто окружён сыновьями Победителя,</li>
                <li>кто проникает в намерения всех существ,</li>
                <li>вездесущего, всеведущего, свободного от признаков действия!<a
                        href="#citation-85" id="ref-85" class="citation-mark"><sup>85</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Пусть, узрев Его, я достигну того, что ещё не достигнуто;</li>
                <li>а достигнутое — моё пребывание в недвойственном блаженном самадхи —</li>
                <li>пусть возрастёт, приближая меня к ступени Татхагаты.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 11. (Будда вновь является Раване)</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>И тогда Благословенный увидел, что Владыка Ланки</li>
            <li>не колеблется в нерождённости дхарм,<a href="#citation-86" id="ref-86"
                                                       class="citation-mark"><sup>86</sup></a></li>
            <li>из сострадания к Десятиглавому вновь явил Себя на вершине,</li>
            <li>убранной множеством драгоценных камней и оплетённой сетью самоцветов.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>И узрел Десятиглавый, Владыка Ланки, то же великолепие,</li>
            <li>что видел и переживал прежде:</li>
            <li>на вершине — Татхагату, Архата, Совершенно Пробуждённого,</li>
            <li>тело Которого украшено тридцатью двумя признаками великого человека.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>И увидел он также свой собственный образ</li>
            <li>перед Татхагатами, Совершенно Пробуждёнными,</li>
            <li>вместе с Махамати ведущим беседу о сфере личного постижения Татхагаты,</li>
            <li>окружённого якшами и излагающего это наставление Дхармы.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>И те чистые земли были со своими Наставниками.</li>
        </ul>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 12. (Великий смех Татхагаты)</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>И тогда Благословенный, вновь окинув собрание взором мудрости,<a href="#citation-87"
                                                                                 id="ref-87"
                                                                                 class="citation-mark"><sup>87</sup></a>
            </li>
            <li>а не плотскими очами, подобно царю львов расправился и издал великий смех.<a
                    href="#citation-88" id="ref-88" class="citation-mark"><sup>88</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Из завитка между бровями, из боков, бёдер, поясницы,</li>
            <li>из знака Шриватса и из всех пор Его тела вырвались лучи света,<a href="#citation-89"
                                                                                 id="ref-89"
                                                                                 class="citation-mark"><sup>89</sup></a>
            </li>
            <li>пылая, словно огонь конца кальпы.</li>
            <li>Его ореол сиял, подобный радуге, луку Индры и восходящему солнцу.</li>
            <li>На Него взирали Шакра, Брахма и хранители миров, стоящие в небесах.</li>
            <li>Восседая на вершине, соперничающей с пиком Сумеру,</li>
            <li>Он вновь разразился великим смехом.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>И тогда у собрания бодхисаттв,</li>
            <li>а также у Шакры, Брахмы и прочих возникла мысль:</li>
        </ul>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Какова причина, каково условие того,</li>
                <li>что Благословенный — Владыка всех дхарм —</li>
                <li>улыбается и смеётся великим смехом,</li>
                <li>испуская лучи света из Своего тела?</li>
            </ul>
        </blockquote>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Испустив лучи, Он погрузился в молчание,</li>
            <li>пребывая во вратах самадхи,</li>
            <li>являющего сферу собственного внутреннего благородного знания,<a href="#citation-90"
                                                                                id="ref-90"
                                                                                class="citation-mark"><sup>90</sup></a>
            </li>
            <li>без изумления, без колебания.</li>
            <li>Львиным взором окинув все стороны света,</li>
            <li>Он размышлял<a href="#citation-91" id="ref-91"
                               class="citation-mark"><sup>91</sup></a> о ходе йогического пути
                самого Раваны.
            </li>
        </ul>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 13. (Вопрос, возникающий из сострадания)</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>И тогда бодхисаттва-махасаттва Махамати, побуждаемый состраданием к Раване,</li>
            <li>постигнув умонастроение собрания бодхисаттв и взирая на грядущие поколения,</li>
            <li>увидел: у тех, кто находит удовольствие в наставлениях как в словах,</li>
            <li>возникнет смятение ума<a href="#citation-92" id="ref-92" class="citation-mark"><sup>92</sup></a>
                —
            </li>
            <li>особенно у тех, кто цепляется за буквальный смысл<a href="#citation-93" id="ref-93"
                                                                    class="citation-mark"><sup>93</sup></a>
            </li>
            <li>и полагается на йогу шраваков, пратьекабудд и тиртхиков.</li>
            <li>Они спросят: «Неужели и Татхагаты, чьё сознание вышло за пределы сферы объектов,
            </li>
            <li>проявляют великий смех?»</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Чтобы развеять их недоумение, он обратился к Благословенному:</li>
            <li>«Какова причина, каково условие этого смеха?»</li>
        </ul>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Прекрасно, прекрасно, Махамати!</li>
                <li>Воистину прекрасно, что ты, взирая на природу мира</li>
                <li>и ради пробуждения умов трёх времён,<a href="#citation-94" id="ref-94"
                                                           class="citation-mark"><sup>94</sup></a>
                    павших в ложные воззрения,
                </li>
                <li>решился спросить Меня об этом.</li>
                <li>Так должны вопрошать мудрецы — ради блага себя, других и обоих.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Знай, Махамати: этот Равана, Владыка Ланки,</li>
                <li>уже задавал прежним Татхагатам два вопроса.<a href="#citation-95" id="ref-95"
                                                                  class="citation-mark"><sup>95</sup></a>
                </li>
                <li>И ныне он желает задать их Мне —</li>
                <li>вопросы, недоступные йогинам шраваков, пратьекабудд и тиртхиков,</li>
                <li>ибо раскрывают различие путей и признаков.</li>
                <li>И эти же вопросы Десятиглавый задаст будущим Победителям».</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 14. (Открытие лотосового пребывания)</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>И тогда Благословенный, зная это, обратился к Владыке Ланки:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Спрашивай, Владыка Ланки!</li>
                <li>Татхагата дарует тебе дозволение.</li>
                <li>Спрашивай без промедления, склонивший главу с короной в почтении.</li>
                <li>О чём бы ты ни возжелал узнать,</li>
                <li>Я удовлетворю твой ум ответом на этот вопрос.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Поскольку ты</li>
                <li>— преобразивший опору различающего мышления,<a href="#citation-96" id="ref-96"
                                                                   class="citation-mark"><sup>96</sup></a>
                </li>
                <li>— исследующий проницательной мудростью различения,<a href="#citation-97"
                                                                         id="ref-97"
                                                                         class="citation-mark"><sup>97</sup></a>
                </li>
                <li>— искусно преодолевающий препятствия ступеней,</li>
                <li>— пребывающий в блаженстве самадхи, основанного на пути личного постижения,</li>
                <li>— поддерживаемый Буддами, пребывающими в самадхи,</li>
                <li>— устойчивый в покое шаматхи,</li>
                <li>— превзошедший все виды самадхи шраваков и пратьекабудд,</li>
                <li>— утверждённый на ступенях Ачала, Садхумати и Дхармамегха,<a href="#citation-98"
                                                                                 id="ref-98"
                                                                                 class="citation-mark"><sup>98</sup></a>
                </li>
                <li>— искусный в таковости отсутствия собственнойсущности дхарм,</li>
                <li>тебе откроется посвящение Победителей в самадхи (samādhi-jina-abhiṣeka)</li>
                <li>в великом драгоценном лотосовом чертоге.<a href="#citation-99" id="ref-99"
                                                               class="citation-mark"><sup>99</sup></a>
                </li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Ты увидишь множество [своих] тел, восседающих на лотосах,</li>
                <li>порождённых силой твоего собственного ума,<a href="#citation-100" id="ref-100"
                                                                 class="citation-mark"><sup>100</sup></a>
                </li>
                <li>и узришь лики, взирающие друг на друга.<a href="#citation-101" id="ref-101"
                                                              class="citation-mark"><sup>101</sup></a>
                </li>
                <li>Эта сфера опыта непостижима уму:</li>
                <li>её раскрывает тот, кто пребывает на чудесной ступени,</li>
                <li>через мастерство проявления.<a href="#citation-102" id="ref-102"
                                                   class="citation-mark"><sup>102</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Благодаря мастерству в средствах ты войдёшь в эту непостижимую сферу</li>
                <li>и в многообразие форм ступени Татхагаты.<a href="#citation-103" id="ref-103"
                                                               class="citation-mark"><sup>103</sup></a>
                </li>
                <li>Ты узришь то, чего не видели ни шраваки, ни пратьекабудды, ни тиртхики,</li>
                <li>ни Брахма, ни Индра, ни Упендра.<a href="#citation-104" id="ref-104"
                                                       class="citation-mark"><sup>104</sup></a></li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 15. (Подношение перед вопрошанием)</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>И тогда Владыка Ланки, получив дозволение Благословенного,</li>
            <li>поднялся с той драгоценной вершины, сияющей чистым светом лучей, подобной лотосу.
            </li>
            <li>Окружённый свитой апсар, он осуществил бесчисленные подношения —</li>
            <li>цветы, гирлянды, благовония, курения, мази, зонты, знамёна, флаги,</li>
            <li>ожерелья, полупояса, венцы, диадемы и иные украшения, прежде невиданные и
                неслыханные.
            </li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Он проявил музыкальные инструменты, звучание которых превосходит всё,</li>
            <li>что принадлежит богам, нагам, якшам, ракшасам, гандхарвам, киннарам, махорагам и
                людям, —
            </li>
            <li>охватывая весь мир желаний, — и проявил также</li>
            <li>те особые музыкальные инструменты, которые видятся в иных землях Будд.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Окутав Благословенного и бодхисаттв ажурными накидками из драгоценностей, подняв</li>
            <li>знамёна из разноцветных тканей, он вознёсся в небо на высоту семи пальм,<a
                    href="#citation-105" id="ref-105" class="citation-mark"><sup>105</sup></a></li>
            <li>пролил на них облака великих подношений, наполнил пространство звучанием музыки и,
            </li>
            <li>спустившись с небес, воссел на второй драгоценной вершине,</li>
            <li>украшенной великим лотосом и сияющей подобно солнцу и молнии.<a href="#citation-106"
                                                                                id="ref-106"
                                                                                class="citation-mark"><sup>106</sup></a>
            </li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Воссев и получив от Благословенного знак — улыбку, предваряющую дозволение, —</li>
            <li>он обратился к Нему с двумя вопросами:</li>
        </ul>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Эти вопросы я задавал прежним Татхагатам, Архатам, Совершенно Пробуждённым, и
                    Они отвечали мне.
                </li>
                <li>Ныне я вопрошаю и Тебя, Благословенный.</li>
                <li>Все Будды излагают это — и прежние, и Ты.</li>
            </ul>
        </blockquote>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Эти два учения, о Благословенный, изрекаются явно,</li>
            <li>а не молчанием Татхагат.</li>
            <li>Ибо, о Благословенный, Татхагаты в молчании лишь раскрывают сферу блаженства
                самадхи;
            </li>
            <li>они не разделяют её различающим мышлением.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Потому, о Благословенный, Владыка всех дхарм, Татхагата, Архат, Совершенно
                Пробуждённый!
            </li>
            <li>Прошу Тебя Самого изложить эти два учения.</li>
            <li>Я и эти сыновья Победителей будем внимать.</li>
        </ul>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 16. (Вопрос о двух дхармах)</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

        <p>Благословенный сказал:</p>
        <p>— Говори, Владыка Ланки, об этой паре дхарм.<a href="#citation-107" id="ref-107"
                                                          class="citation-mark"><sup>107</sup></a>
        </p>
        <p>Повелитель ракшасов сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>О Ты, сияющий венцами, браслетами, ожерельями и алмазными нитями!</li>
                <li>Сказано: «Даже дхармы надлежит оставить — тем более не-дхармы».</li>
                <li>Но как, Благословенный, возможно это оставление пары дхарм?</li>
                <li>Что такое не-дхармы и что такое дхармы?<a href="#citation-108" id="ref-108"
                                                            class="citation-mark"><sup>108</sup></a>
                </li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Как может существовать двойственность в том, что подлежит оставлению,</li>
                <li>если всё это погружено в признаки различающего мышления,<a href="#citation-109"
                                                                               id="ref-109"
                                                                               class="citation-mark"><sup>109</sup></a>
                </li>
                <li>тогда как сама природа различения лишена собственной сущности?<a
                        href="#citation-110" id="ref-110" class="citation-mark"><sup>110</sup></a>
                </li>
                <li>Если они не являются ни материальными, ни нематериальными,<a
                        href="#citation-111" id="ref-111" class="citation-mark"><sup>111</sup></a>
                </li>
                <li>если из-за непостижения Алайя-виджняны<a href="#citation-112" id="ref-112"
                                                             class="citation-mark"><sup>112</sup></a>
                </li>
                <li>их признаки неразличимы,<a href="#citation-113" id="ref-113"
                                               class="citation-mark"><sup>113</sup></a></li>
                <li>если по своей природе они подобны видению волосков в пустоте,<a
                        href="#citation-114" id="ref-114" class="citation-mark"><sup>114</sup></a>
                </li>
                <li>если они — лишь объект познания для омрачённого, неочищенного знания<a
                        href="#citation-115" id="ref-115" class="citation-mark"><sup>115</sup></a> —
                </li>
                <li>то как возможно их оставление,</li>
                <li>если они обладают именно такой природой?<a href="#citation-116" id="ref-116"
                                                               class="citation-mark"><sup>116</sup></a>
                </li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 17. (О двух уровнях различения)</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Разве ты не видишь, Владыка Ланки, как в сфере различений невежд<a
                        href="#citation-117" id="ref-117" class="citation-mark"><sup>117</sup></a>
                </li>
                <li>происходит разделение кувшинов и прочих вещей, по природе подверженных распаду?
                    Почему же это не принять и здесь?
                </li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Различение между дхармой и не-дхармой условно существует, опираясь на различения
                    невежд,
                </li>
                <li>но не присутствует в поле благородного знания.<a href="#citation-118"
                                                                     id="ref-118"
                                                                     class="citation-mark"><sup>118</sup></a>
                </li>
                <li>Пусть пока останутся в стороне кувшины и прочие вещи,</li>
                <li>чьи признаки многообразны для невежд, но невидимы благородным.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Взгляни на огонь: он обладает единой природой,</li>
                <li>но, горя в домах, дворцах и садах,</li>
                <li>проявляет различия — длинное и короткое пламя, слабое и сильное сияние —</li>
                <li>в зависимости от топлива.<a href="#citation-119" id="ref-119"
                                                class="citation-mark"><sup>119</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Почему же это не принять и здесь?</li>
                <li>Так же и то, что рождается из одного семени:</li>
                <li>росток, стебель, узел, лист, цветок, плод, ветви —</li>
                <li>всё различно в проявлении, хотя исходит из одного.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Так и все дхармы — внешние и внутренние,</li>
                <li>порождённые неведением,</li>
                <li>входящие в <em>скандхи</em>, <em>дхату</em> и <em>аятаны</em>,</li>
                <li>возникающие в трёх мирах —</li>
                <li>имеют различия в формах и в том, как они именуются.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Даже сознания (<em>vijñāna</em>), имея единый признак — восприятие объектов,
                </li>
                <li>различаются как низшие, средние и высшие,</li>
                <li>как очищённые и неочищённые,</li>
                <li>как благие и неблагие.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>И даже у йогинов, следующих путём йоги,</li>
                <li>наблюдаются различия в признаках их личного постижения.<a href="#citation-120"
                                                                              id="ref-120"
                                                                              class="citation-mark"><sup>120</sup></a>
                </li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Тем более, пока ум вовлечён в процесс различения,<a href="#citation-121"
                                                                        id="ref-121"
                                                                        class="citation-mark"><sup>121</sup></a>
                </li>
                <li>различение между дхармой и не-дхармой условно наблюдается.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 18. (О дхармах, подлежащих оставлению)</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Владыка Ланки, различение между дхармой и не-дхармой существует,</li>
                <li>поскольку присутствует признак различения.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Что же здесь называется (благими) дхармами?</li>
                <li>Это то, что измышлено различениями тиртхиков, шраваков, пратьекабудд и невежд.
                </li>
                <li>Опираясь на представления о внешних условиях, они учат, что «дхармы, основаны на
                    причинах, качествах и субстанциях».<a href="#citation-122" id="ref-122"
                    class="citation-mark"><sup>122</sup></a></li>
                <li>Именно такие дхармы подлежат оставлению.</li>
                <li>Их не следует подвергать различающему мышлению на основе признаков.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Из-за привязанности к представлению, что то, что видится умом, есть внешняя
                    реальность,<a href="#citation-123" id="ref-123"
                                  class="citation-mark"><sup>123</sup></a></li>
                <li>невежды воображают существование кувшинов и прочих вещей.</li>
                <li>Но эти дхармы, измышленные умом невежд, не обладают собственным телом.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Для того, кто видит это таким образом, они уже отброшены.<a href="#citation-124"
                    id="ref-124" class="citation-mark"><sup>124</sup></a>
                </li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 19. (О том, что подлежит оставлению)</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Каковы же не-дхармы?</li>
            <li>Это те «дхармы», которые лишены собственной природы,<a href="#citation-125" id="ref-125" class="citation-mark"><sup>125</sup></a></li>
            <li>у которых отсутствует проявление различающих признаков,<a href="#citation-126" id="ref-126" class="citation-mark"><sup>126</sup></a></li>
            <li>и которые не имеют причины.<a href="#citation-127" id="ref-127" class="citation-mark"><sup>127</sup></a></li>
            <li>Их не-возникновение<a href="#citation-128" id="ref-128" class="citation-mark"><sup>128</sup></a> видится и как существующее, и как несуществующее (<em>bhūta-abhūtataḥ</em>).</li>
            <li>В этом и состоит оставление дхармы.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>И снова: какие ещё «дхармы» лишены собственной природы?</li>
            <li>Это — рога зайца, рога верблюда, рога лошади, сын бесплодной женщины и подобные.</li>
            <li>Поскольку они лишены собственной природы,</li>
            <li>их нельзя мыслить через признаки.<a href="#citation-129" id="ref-129" class="citation-mark"><sup>129</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Их именуют только ради условного общения,<a href="#citation-130" id="ref-130" class="citation-mark"><sup>130</sup></a></li>
            <li>без привязанности — подобно тому, как именуют кувшины.</li>
            <li>Подобно тому, как они не захватываются<a href="#citation-131" id="ref-131" class="citation-mark"><sup>131</sup></a> — поскольку сознанию не за что ухватиться, —</li>
            <li>так же и все проявления различающего мышления<a href="#citation-132" id="ref-132" class="citation-mark"><sup>132</sup></a> подлежат оставлению.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Так совершается оставление и дхарм, и не-дхарм.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>И потому, Владыка Ланки, на твой вопрос —</li>
            <li>«Как оставляются дхармы и не-дхармы?» —</li>
            <li>дан этот ответ.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 20. (Выйти за пределы)</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же касается твоих слов, Владыка Ланки:</li>
            <li>«Я спрашивал прежних Татхагат, Архатов, Совершенно Пробуждённых, и Они ответили на этот вопрос»,<a href="#citation-133" id="ref-133" class="citation-mark"><sup>133</sup></a> —</li>
            <li>знай: сам этот вопрос порождён различением.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Ибо «прошлое» мыслится как «прошлое» лишь через различение;</li>
            <li>так же и «будущее», и «настоящее».</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Татхагаты свободны от различения,</li>
            <li>они вышли за пределы всего размножествления понятий.<a href="#citation-134" id="ref-134" class="citation-mark"><sup>134</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Их нельзя помыслить как обладающих природой формы.</li>
            <li>Их проявление разворачивается лишь ради блага существ</li>
            <li>через мудрость, свободную от признаков (<em>animitta</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Татхагаты — знание,</li>
            <li>их тело — знание.</li>
            <li>Они не полагают и не полагаемы.<a href="#citation-135" id="ref-135" class="citation-mark"><sup>135</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Почему они не полагают?</li>
            <li>Потому что их манас/интеллект не принимает себя как атман, саттву, дживу или пудгалу.<a href="#citation-136" id="ref-136" class="citation-mark"><sup>136</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Почему они не полагаемы?</li>
            <li>Потому что они не являются объектами мановиджняны/различающего сознания,</li>
            <li>которая воспринимает на основе форм, признаков, очертаний и условий.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Потому тебе следует выйти за пределы и различения и его отсутствия.<a href="#citation-137" id="ref-137" class="citation-mark"><sup>137</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h3 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">
        Подглава 21. (Иллюзия, питаемая умом)</h3>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Более того, Владыка Ланки, всё движение живых существ подобно фигурам, нарисованным на стене.<a href="#citation-138" id="ref-138" class="citation-mark"><sup>138</sup></a></li>
            <li>Мироустройство, о Владыка Ланки, бездеятельно; оно лишено действия и деятеля, ибо во всех дхармах нет живого существа.</li>
            <li>Здесь нет никого, кто слышит, и нет ничего, что слышится.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Поистине, Владыка Ланки, мироустройство подобно магическому изваянию,<a href="#citation-139" id="ref-139" class="citation-mark"><sup>139</sup></a></li>
            <li>но ни тиртхики, ни незрелые йогины не постигают этого.</li>
            <li>Тот, кто видит так — видит истинно.</li>
            <li>Видящие иначе блуждают в различениях.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Плененные собственными различениями,<a href="#citation-140" id="ref-140" class="citation-mark"><sup>140</sup></a> они делят [мир] надвое.</li>
            <li>Это подобно отражению в зеркале или в воде, подобно тени тела, подобно тени в доме, освещённом луной или лампой, подобно эху.</li>
            <li>Принимая за реальность плененность своими различениями, они делят всё на дхарму и не-дхарму.</li>
            <li>Они не следуют путём оставления дхармы и не-дхармы.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Они строят различения и питают их,<a href="#citation-141" id="ref-141" class="citation-mark"><sup>141</sup></a> а потому не обретают покоя.</li>
            <li>«Покой» — это обозначение единонаправленности (<em>ekāgratā</em>).<a href="#citation-142" id="ref-142" class="citation-mark"><sup>142</sup></a></li>
            <li>Из этой единонаправленности рождается высшее самадхи — вхождение в сферу личного благородного знания, что есть Татхагатагарбха.</li>
        </ul>
        </blockquote>

            <p>«Так завершается первая глава, именуемая "Главой о просьбе Раваны"».</p>

        <p class="text-center font-bold">***</p>
    </div>










    <h4 class="text-center text-gray-800 font-bold text-xl my-4">ПРИМЕЧАНИЯ</h4>
    <hr class="my-8 border-t-4 border-gray-500">
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p></p>
        <p class="my-2" id="citation-1"><sup>1</sup> <strong>Ващита</strong> (<em>vaśitā</em>) —
            духовная власть, обретаемая бодхисаттвой на высоких ступенях пути (<em>бхуми</em>).
            Она означает непринуждённое господство над собственным умом, дхармами, кармой и
            процессом перерождений. В отличие от обычного «самообладания», ограниченного
            эмоциональным контролем, <em>ващита</em> — это способность свободно проявляться в
            сансаре без загрязнений, действовать без усилий (<em>анабхисамскара</em>) и
            спонтанно откликаться на нужды существ. Она проистекает из прямого постижения
            недвойственной природы реальности (<em>адвая-джняна</em>) и преобразования ума (<em>āśraya-parāvṛtti</em>).
            Традиционно выделяют десять видов <em>ващиты</em>: власть над жизнью
            (<em>āyur-vaśitā</em>),
            власть над умом (<em>citta-vaśitā</em>), власть над необходимыми средствами (<em>pariṣkāra-vaśitā</em>),
            власть над дхармами (<em>dharma-vaśitā</em>), власть над чудесными силами (<em>ṛddhi-vaśitā</em>),
            власть над рождением (<em>janma-vaśitā</em>), власть над устремлением (<em>adhimukti-vaśitā</em>),
            власть над обетами (<em>praṇidhāna-vaśitā</em>), власть над кармой
            (<em>karma-vaśitā</em>), власть над мудростью (<em>jñāna-vaśitā</em>). Бодхисаттва,
            обладающий совершенной <em>ващитой</em>, может по своей воле принимать рождение в
            любом мире, сохранять память о прошлых жизнях, проявлять любые формы и применять
            любые искусные средства (<em>упая</em>) ради освобождения существ. В контексте
            <strong><em>Ланкаватара-сутры</em></strong> <em>ващита</em> тесно связана с владением
            <em>самадхи</em>
            (<em>samādhi-vaśitā</em>), постижением того, что всё есть лишь только воспринимаемое собственным умом (<em>svacitta-dṛśya-gocara-parijñāna</em>)
            и игровой деятельностью (<em>vikrīḍita</em>) — ибо именно <em>ващита</em> делает
            возможной «игру» просветлённого бодхисаттвы в мире форм.<a href="#ref-1"
                                                                       class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-2"><sup>2</sup> <strong>Бала</strong> (<em>bala</em>) —
            духовная сила или непоколебимость, обретаемая бодхисаттвой благодаря прямому
            постижению природы ума. В отличие от обычной «силы воли», <em>бала</em> — это
            устойчивость, проистекающая из реализации <em>шуньяты</em>. Она делает бодхисаттву
            неуязвимым для заблуждений, страхов и власти кармы. Эта сила не является результатом
            эгоистического усилия — она возникает спонтанно из недвойственного знания (<em>адвая-джняна</em>)
            как его естественное качество. <em>Бала</em> позволяет бодхисаттве непрерывно
            действовать ради блага существ, не отклоняясь от пути даже в самых трудных
            обстоятельствах, подобно горе, неподверженной бурям. В махаянской традиции
            различают пять сил (<em>pañca balāni:</em> вера, усердие, памятование, самадхи,
            мудрость) и десять сил Будды (<em>daśa tathāgata-balāni</em>): знание возможного и
            невозможного, знание созревания кармы, знание различных склонностей существ, знание
            различных элементов (<em>дхату</em>), знание высших и низших способностей, знание
            путей, ведущих везде, знание происхождения загрязнений и их очищения, знание
            воспоминаний о прошлых жизнях, знание смерти и рождения существ, знание истощения
            <em>асрав</em> (омрачений). Бодхисаттвы на высоких ступенях пути, особенно начиная с
            восьмой бхуми (<em>Ачала</em>, «Неподвижная»), обретают зачатки этих сил. На этой
            ступени они достигают <em>анивартаны</em> (невозвратности), их деяния становятся
            <em>анабхога</em> (безусильными), а знание — <em>анабхисамскара-джняна</em>
            (недеятельным). Именно здесь <em>бала</em> расцветает как <em>акампья</em> —
            абсолютная несотрясаемость. В контексте <strong><em>Ланкаватара-сутры</em></strong>
            <em>бала</em> неотделима от <em>ващиты</em> (власти), <em>абхиджни</em>
            (сверхзнаний) и <em>викриды</em> (игровой деятельности) — ибо все они являются
            гранями единого просветлённого ума, свободно играющего в мире форм ради спасения
            существ.<a href="#ref-2" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-3"><sup>3</sup> <strong>Абхиджня</strong> (<em>abhijñā</em>)
            — высшие знания или сверхспособности, возникающие как естественные функции освобождённого
            сознания. Традиционно выделяют шесть <em>абхиджня: </em><strong>Ṛddhi</strong> —
            чудесные силы (полёт, хождение по воде, множественные эманации и т.д.), <strong>Divya-śrotra</strong>
            — божественный слух (восприятие звуков всех миров),
            <strong>Para-citta-jñāna</strong> — знание мыслей других существ, <strong>Pūrva-nivāsānusmṛti</strong>
            — память о прошлых жизнях, <strong>Divya-cakṣus</strong> — божественное око (видение
            смерти и перерождения существ в соответствии с их кармой),
            <strong>Āsrava-kṣaya-jñāna</strong>
            — знание об истощении загрязнений (<em>āsrava</em>). В отличие от магических
            навыков, приобретаемых через <em>мантры</em> или ритуалы, <em>абхиджни</em> — это
            спонтанные проявления ума, освободившегося от двойственности субъекта и объекта. В
            ранних текстах первые пять <em>абхиджня</em> доступны даже не-буддистам через
            достижение глубоких <em>дхьян</em>, но шестая <em>абхиджня</em> — знак истинного
            освобождения, недоступный тем, кто не преодолел <em>āsrava</em> (омрачения-загрязнения) или
            <em>kleśa</em> (эгоистические эмоциональные реакции). В <strong><em>Ланкаватара-сутре</em></strong>
            <em>абхиджни</em> радикально переосмыслены в духе учения <em>Читтаматры</em>
            («Только-ум»). Здесь истинная <em>абхиджня</em> — это <em>париджняна</em> (полное
            постижение) того, что область опыта (<em>gocara</em>) есть лишь воспринимаемое собственным умом
            (<em>svacitta-dṛśya-gocara</em>). Остальные способности являются отдельными сторонами
            этого фундаментального знания: если бодхисаттва постиг иллюзорность границ в сфере воспринимаемого, он естественным образом видит мысли других; если он знает, что его ум творит
            все миры, он может проявлять чудесные силы без усилий. Таким образом,
            <em>абхиджни</em> не являются целью практики, а служат искусными средствами
            (<em>упая</em>)
            для освобождения существ. У <em>махасаттв</em> они неотделимы от <em>балы</em>
            (непоколебимой силы), <em>ващиты</em> (духовной власти) и <em>викриды</em> (игровых
            проявлений), поскольку все эти качества проистекают из единой основы —
            недвойственного знания (<em>адвая-джняна</em>). Привязанность к <em>абхиджням</em>
            или гордость ими считается серьёзным препятствием на пути. Истинный бодхисаттва
            использует их исключительно ради блага существ, оставаясь внутренне свободным от
            всех проявлений. В <strong><em>Вималакирти-нирдеша-сутре</em></strong> есть замечательный
            эпизод, где Вималакирти критикует монахов, гордящихся своими <em>абхиджнями</em>,
            показывая, что истинная способность — это постижение <em>шуньяты</em>, а не
            магические силы. В <strong><em>Алмазной сутре</em></strong> также сказано: «Те, кто видит
            Меня в форме, Те, кто следует за Моим голосом, Идут ложным путём — Они не узрят
            Татхагату». Это напоминание, что <em>абхиджни</em> относятся к миру форм
            (<em>рупа-дхату</em>) и не являются конечной реализацией.<a href="#ref-3"
            class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-4"><sup>4</sup> <strong>Викрида</strong>
            (<em>vikrīḍita</em>, тиб. <em>rol pa</em>) — «свободная игра» или «игровая
            деятельность» просветлённого ума. Термин происходит от санскритского корня
            √<strong>krīḍ</strong>
            («играть») с усилительной приставкой <strong>vi-</strong>, означающей «разворачивать
            игру во всём её многообразии». Это спонтанная, непринуждённая активность бодхисаттвы
            или Будды, совершаемая: <strong>без усилия</strong> (<em>anabhisaṃskāra</em>) — без
            волевого напряжения и искусственности, <strong>без привязанности к
                результату</strong>, <strong>без разделения на субъект и объект
                действия</strong>, <strong>без накопления кармических следов</strong>. В отличие
            от обычной деятельности, порождённой желанием, страхом или долгом, <em>викрида</em>
            подобна игре ребёнка: она полна энергии и жизни, но свободна от цели и расчёта.
            Однако это не легкомыслие, а высшая форма активности — деятельность, полностью
            освобождённая от эго-центричности. В <strong><em>Ланкаватара-сутре</em></strong>
            <em>викрида</em> — естественное выражение постижения <em>читтаматры</em>
            («только-ум»): бодхисаттва знает, что весь мир есть воспринимаемое собственным умом, и потому в его
            действиях нет ни напряжения, ни следа. Он «играет» в сансаре, как актёр на сцене,
            зная иллюзорность декораций, но при этом искренне служа освобождению существ. <em>Викрида</em>
            неотделима от: <em>балы</em> (непоколебимой силы), <em>ващиты</em> (духовной
            власти), <em>абхиджни</em> (сверхзнаний). Все они — грани единой свободы,
            проявляющейся в мире форм <strong>исключительно ради блага существ</strong>.
            Истинная <em>викрида</em> возможна только при полном постижении <em>шуньяты</em> и
            недвойственности (<em>адвая</em>). Без этой реализации попытка «играть» превращается
            в обычную кармическую деятельность или, хуже того, в духовную гордыню. Как говорится
            в <strong><em>Ваджраччхедика-сутре</em></strong>: «Воистину, Субхути, нельзя называть
            бодхисаттвой того, кто держится понятия <em>атман, саттва, джива</em> или
            <em>пудгала</em>».
            Только <strong>когда нет играющего</strong>, игра становится совершенной. В <strong>индуизме</strong>:
            <em>лила</em> (<em>līlā</em>) — божественная игра Брахмана в творении мира;
            предполагается реальный играющий (Атман). В <strong>буддизме</strong>:
            <em>викрида</em> — игра без играющего (<em>найратмья</em>). В <strong>дзэн</strong>:
            <em>мусин</em> (<em>mushin</em>) — «не-ум», спонтанное действие. В <strong>тибетском
                буддизме</strong>: <em>ролпа</em> (<em>rol pa</em>) — игровое проявление
            <em>ригпа</em>
            (изначального осознавания). В <strong>тантре</strong>: <em>викрида</em> проявляется
            как игровая деятельность божеств мандалы. Из <strong><em>Аватамсака-сутры</em></strong>:
            «Подобно луне, отражающейся в тысяче озёр, — Бодхисаттва проявляется в мириадах
            форм. Но сама луна остаётся в небе, не тронутая водой». Это и есть <em>викрида</em>:
            <strong>полная вовлечённость без привязанности, деятельность без деятеля</strong>.<a
                href="#ref-4" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-5"><sup>5</sup> <strong>Абхишека</strong>
            (<em>abhiṣeka</em>) — буквально «орошение» или «освящение» (от корня
            √<strong>sic</strong> — «лить» с приставкой <strong>abhi-</strong> — «направленное
            действие»). В индийской традиции абхишека изначально — ритуал коронации царя
            (раджасуя), при котором его омывали священной водой из четырёх сосудов,
            символизирующих четыре стороны света. Этот обряд, упоминаемый уже в <strong><em>Ригведе</em></strong>, означал
            передачу кшатра-шакти — власти правителя. В <strong><em>Ланкаватара-сутре</em></strong>
            абхишека радикально переосмыслена: это не внешний ритуал, а внутреннее признание
            зрелости бодхисаттвы, достигшего глубокого постижения того, что весь мир есть
            только-ум (<em>cittamātra</em>). Выражение «посвящённые руками всех Будд» (<em>sarvabuddha-pāṇi-abhiṣekābhiṣikta</em>
            — букв. «те, кто посвящён посвящением от рук [благословения] всех Будд») означает,
            что вся совокупность просветлённой мудрости подтверждает реализацию бодхисаттвы.
            «Рука Будды» здесь — метафора сострадания (<em>karuṇā</em>) и благословляющей силы (<em>adhiṣṭhāna</em>),
            через которую происходит прямая передача ума к уму. <em>Абхишека</em>
            на десятой <em>бхуми</em> (<em>Дхармамегха</em> — «Облако Дхармы») предшествует <em>āśraya-parāvṛtti</em>
            (повороту основы сознания) — полной трансформации алайя-виджняны в
            <em>ādarśa-jñāna</em> (Зерцалоподобную мудрость), которая завершится при достижении
            буддовости. Как сказано в традиции, опирающейся на
            <strong><em>Дашабхумика-сутру</em></strong>: в этот миг Будды из десяти направлений касаются
            головы бодхисаттвы, подобно тому, как царя помазывают при коронации, и возникает
            великое сияние (<em>mahā-prabhāsa</em>), знаменующее его невозвратность
            (<em>anivartanā</em>)
            и готовность стать Буддой. «Подобно тому, как царевич, достигший совершеннолетия,
            помазывается водой четырёх океанов и становится чакравартином, так и бодхисаттва,
            достигший совершенства в мудрости и сострадании, касается головой лотосовых стоп
            всех Будд и получает великую абхишеку. С этого момента он уже не обычное существо
            (<em>pṛthagjana</em>), но и ещё не полностью Будда — он <em>вирья-ратна</em>
            (драгоценность усилия), готовая засиять». В сутрическом контексте (включая
            <strong><em>Ланкаватару</em></strong>)
            <em>абхишека</em> — следствие реализации; бодхисаттва «посвящён», потому что его ум
            уже неотличим от ума всех Будд. Это описательный термин, а не предписание. В
            тантрическом контексте <em>абхишека</em> — причина или катализатор реализации,
            формальный ритуал, необходимый для практики. Указывают четыре типа <em>абхишеки</em>
            в тантре: <em>калаша</em> (сосуд), <em>гухья</em> (тайная), <em>праджня-джняна</em>
            (мудрость-знание), <em>чатуртха</em> (четвёртая). Важно не смешивать эти два уровня:
            в <strong><em>Ланкаватаре</em></strong> абхишека остаётся прямым выражением внутренней
            свободы, а не предварительным условием практики. В контексте
            <strong><em>Ланкаватары</em></strong> <em>абхишека</em> знаменует глубокое очищение
            <em>алайя-виджняны</em>
            от <em>васан</em> (кармических отпечатков). Если ритуальная вода очищает тело, то
            лучи мудрости (<em>raśmi</em>) Будд ослабляют тончайшие препятствия к всеведению
            (<em>jñeyāvaraṇa</em>). Здесь абхишека — это граница: бодхисаттва достигает высшей
            ступени пути и становится <em>ювараджей</em> (наследным принцем Дхармы), чья
            деятельность во благо существ становится тождественной деятельности самих Будд.<a
                href="#ref-5" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-6"><sup>6</sup> <strong>Париджняна</strong>
            (<em>parijñāna</em>, тиб. <em>yongs su shes pa</em>) — исчерпывающее,
            непосредственное постижение, в котором объект раскрывается со всех сторон, полностью
            и без остатка. Термин образован от корня √<strong>jñā</strong> («знать») с
            приставкой <strong>pari-</strong>, означающей «вокруг» (всестороннее охватывание),
            «полностью» (завершённость) и «за пределы» (превосхождение обычного знания). <em>Париджняна</em>
            — не интеллектуальное знание (<em>jñāna</em>), не результат обучения
            (<em>śruta-jñāna</em>)
            или логического размышления (<em>cintā-jñāna</em>). Она является вершиной
            взращённого созерцательного опыта (<em>bhāvanā-jñāna</em>) и плодом прямого постижения. Это
            не мимолётное озарение, не экстатическое переживание единства и не трансовое
            состояние, в котором может отсутствовать мудрость. Это необратимое изменение способа
            познания. В контексте <strong><em>Ланкаватара-сутры</em></strong> центральным является
            <em>париджняна</em>
            <em>svacitta-dṛśya-gocara</em> — полное и прямое постижение того, что вся сфера опыта является воспринимаемым собственным умом (<em>читтаматра</em>), ум
            окончательно перестаёт принимать внешний мир как независимый объект,
            субъектно-объектная двойственность растворяется. В момент <em>париджняны</em>
            познание и освобождение неразделимы: постижение шуньяты освобождает от
            привязанностей, поскольку объект теряет свою «внешнюю» власть над воспринимающим.
            <em>Париджняна</em> предшествует окончательному <em>повороту основы</em> (<em>āśraya-parāvṛtti</em>),
            способствует устранению <em>познавательных препятствий к всеведению
                (jñeyāvaraṇa)</em> и является внутренним фундаментом для духовного посвящения
            (<em>абхишеки</em>). Без <em>париджняны</em> даже глубокие состояния сосредоточения
            остаются ограниченными двойственным восприятием. С <em>париджняной</em> само бытие
            постигается как Татхата (Таковость) в её недвойственной природе, а любая
            деятельность бодхисаттвы превращается в <em>викриду</em> (свободную игру) и
            <em>упаю</em> (искусное средство) для блага существ.<a href="#ref-6"
                                                                   class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-7"><sup>7</sup> <strong>Svacitta-dṛśya-gocara</strong>
            (санскр. <em>sva-citta-dṛśya-gocara</em>, тиб. <em>rang sems kyi snang yul</em>) —
            «воспринимаемое собственным умом», или, образно, «пастбище восприятий собственного
            ума». Слово <em>gocara</em> буквально означает «место, где пасутся коровы»
            (<em>go</em> — корова, <em>cara</em> — движение). В классической индийской
            эпистемологии оно обозначает сферу действия чувств: зрение «пасётся» в мире форм,
            слух — в мире звуков. В <strong><em>Ланкаватара-сутре</em></strong> этот образ получает
            глубокое переосмысление: ум сам создаёт своё пастбище. Обыденное сознание «пасётся»
            в мире, который является проекцией его собственных кармических отпечатков
            (<em>васан</em>). Здесь <em>citta</em> — фундаментальный поток сознания (<em>алайя-виджняна</em>),
            вмещающий и всё проецируемое воспринимаемое как <em>ābhāsa</em> — «кажимость» или «отражение» (подобно луне в
            воде) и «воспринимающего». То, что принимается за «внешний мир», на деле является динамикой самого ума,
            разворачивающейся в его собственной сфере (<em>gocara</em>). Учение не утверждает
            реальность «я», творящего мир. Напротив, оно постулирует, что и воспринимающий
            субъект (<em>грахака</em>), и воспринимаемый объект (<em>грахья</em>) равно лишены
            самосущности (<em>шунья</em>). Это безличный процесс возникновения иллюзии
            разделения. Мир, воспринимаемый как нечто внешнее и отдельное, — это
            <em>парикальпита</em>
            (воображаемое). Сам поток <em>svacitta-dṛśya-gocara</em>, процесс взаимозависимого
            возникновения явлений в уме, воспринимаемых как объекты,— это <em>паратантра</em> (зависимое).
            Постижение этого потока как воспринимаемого собственным умом, свободного от наслоений двойственности «я и другие», — это
            <em>паринишпанна</em> (совершенное), или <em>Татхата</em> (Таковость). Постижение
            «сферы воспринимаемого собственным умом» достигается через вопрос: «Где находится объект — внутри
            или снаружи?» Невозможность определить местоположение объекта (он не может быть ни
            внутри, ни снаружи) приводит к прямому переживанию: разделения не существует. В этот
            момент исчезает мнимая пропасть между познающим и познаваемым. Реализация <em>svacitta-dṛśya-gocara</em>
            устраняет цепляние за личность (<em>атма-граха</em>) и за независимость вещей (<em>дхарма-граха</em>).
            <a href="#ref-7" class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-8"><sup>8</sup> <strong>Рупа</strong> (<em>rūpa</em>, тиб.
            <em>gzugs</em>) — в данном контексте это не «материальная форма» (одна из пяти <em>скандх</em>).
            Здесь подразумевается способ проявления бодхисаттвы, соответствующий кармическому восприятию и
            характеру существ. Для обычного существа <em>рупа</em> — кармическая тюрьма: оно
            цепляется за тело как за «своё», страшится его утраты и страдает от иллюзии
            плотности. Но для бодхисаттвы, постигшего <em>svacitta-dṛśya-gocara</em>,
            <em>рупа</em> становится инструментом освобождения — <em>майя-рупа</em> («телом,
            подобным иллюзии»): <em>шуньевым</em> по природе, но действенным. Это не намеренное
            преображение. Ум бодхисаттвы, свободный от двойственности, естественно откликается
            на нужды существ, и форма возникает сама — как звук небесных барабанов (<em>divya-dundubhi</em>)
            или свет драгоценности, исполняющей желания (<em>cintāmaṇi</em>). Такое проявление —
            <em>анабхисамскара</em>: безусильное, непринуждённое, лишённое эгоцентрического
            намерения. Благодаря знанию чужих умов (<em>para-citta-jñāna</em>) и пониманию
            различных склонностей существ (<em>nānā-sattva-citta-carita</em>), бодхисаттва
            принимает форму как часть триады искусных средств (<em>upāya</em>):
            <em>рупа</em> — подходящее тело, <em>найя</em> — подходящий метод наставления, <em>винайя</em>
            — способ усмирения клеш. В системе трёх Тел Будды (<em>tri-kāya</em>) такие
            проявления предвосхищают Нирманакаю — Тело Проявлений. Ключевое различие в отношении
            к форме выражается через уровни реализации: Обычное существо заперто в форме;
            Бодхисаттва играет с формой (викрида); Будда являет все формы — но ни одна не
            является его сутью. Постигнув, что и «он», и «другое существо» — проявления ума,
            свободного от разделения, бодхисаттва свободно проявляется во всех мирах, оставаясь
            внутренне недвижимым. Он подобен луне, которая отражается в тысячах водоёмов, но,
            оставаясь в небе, не затронута движением воды.<a href="#ref-8"
                                                             class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-9"><sup>9</sup> <strong>Найя</strong> (<em>naya</em>, тиб.
            <em>tshul</em>), происходящая от санскритского корня √<strong>nī</strong> («вести»),
            — персонализированный метод наставления или искусный подход, подбираемый
            бодхисаттвой в строгом соответствии со склонностями, способностями и кармическим
            состоянием конкретного существа. В отличие от догматического подхода, <em>найя</em>
            является живым процессом ведения к истине, где форма учения диктуется состоянием
            слушателя. Такая гибкость становится возможной только на фундаменте <em>париджняны
                svacitta-dṛśya-gocara</em>, благодаря которой бодхисаттва непосредственно видит
            структуру чужого ума. Через <em>para-citta-jñāna</em> (знание мыслей других) он
            понимает, как ум другого существа строит свой мир, какие именно <em>васаны</em> и
            <em>клеши</em> формируют его иллюзию, и, исходя из этого видения, подбирает тот
            особый путь, который способен разрушить это конкретное заблуждение. В этом ключе
            сама доктрина трёх колесниц объявляется не конечной
            истиной, а <em>найей</em> — временным средством, приспособленным к разной глубине
            понимания существ. В неразрывной триаде <em>рупа—найя—винайя</em> именно <em>найя</em>
            занимает центральное положение, выступая мостом между проявленной формой и целью —
            освобождением от <em>клеш</em>. Если <em>рупа</em> (подходящий облик) устанавливает
            канал доверия, то <em>найя</em> передаёт смысл Дхармы в доступных категориях, а <em>винайя</em>
            закрепляет этот процесс, устраняя аффекты и приводя ум к покою. Вместе эти аспекты
            воплощают <em>упая-каушалью</em> (искусность в средствах), лишённую эгоцентрических
            намерений и проистекающую из глубокого постижения недвойственной природы
            ума.<a href="#ref-9" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-10"><sup>10</sup> <strong>Винайя</strong> (<em>vinaya</em>),
            происходящая от санскритского корня √<strong>nī</strong> («вести») с приставкой
            <strong>vi-</strong> («прочь», «врозь»), буквально означает «ведение прочь от
            заблуждений», «усмирение» или «направление в правильное русло». В контексте глубоких
            реализаций бодхисаттвы этот термин обозначает живое, обращённое к конкретному
            существу воспитательное действие, направленное на устранение его клеш. Такое воспитательное
            действие может принимать самые разные
            формы: от строгого слова, сокрушающего самодовольство, до мягкого упрёка или
            временного отстранения от практики, если она выполняется из эгоистических
            побуждений. Бодхисаттва применяет <em>винайю</em> искусно, поскольку его действия опираются на
            постижение <em>svacitta-dṛśya-gocara</em>: он видит тончайшие кармические наслоения
            (<em>васаны</em>), питающие эго другого существа, и точно знает, какая именно мера
            не вызовет бесполезного сопротивления, но разрушит сам корень заблуждения. В триаде
            <em>рупа—найя—винайя</em> именно <em>винайя</em> выступает завершающим актом
            преобразования сознания, превращая понимание в устойчивое состояние покоя. Она
            воплощает принцип, согласно которому истинное милосердие иногда требует жёсткости, а
            истинное наставление — решительного пресечения ложных путей. Таким образом,
            <em>винайя</em>
            становится проявлением искусности в средствах, где бодхисаттва действует исходя
            из глубокого видения того, что именно в данный миг необходимо
            существу для исцеления его ума.<a href="#ref-10"
                                              class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-11"><sup>11</sup> <strong>Пять дхарм</strong> (<em>pañcadharma</em>) — одна из центральных классификационных схем <strong><em>Ланкаватары</em></strong>: Имя (<em>nāma</em>), Признак (<em>nimitta</em>), Различение (<em>vikalpa</em>), Правильное знание (<em>samyagjñāna</em>) и Таковость (<em>tathatā</em>).<br>
Первые три относятся к сфере обусловленного различения. Признак — непосредственно воспринимаемый облик вещи. Имя — слово, накладываемое на признак. Различение — умственное построение, соединяющее имена и признаки в «явления» и «я». Эти три соответствуют воображаемой (<em>parikalpita</em>) и зависимой (<em>paratantra</em>) природам.<br>
Правильное знание и Таковость указывают за пределы этой схемы. Правильное знание видит имена и признаки без наложения различений. Таковость — сама природа реальности, открывающаяся в этом видении. Они соответствуют совершенной природе (<em>pariniṣpanna</em>). Подробное разъяснение этих пяти дхарм даётся в подглаве 6.2.<a href="#ref-11" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-12"><sup>12</sup> <strong>Три свабхавы</strong> (<em>tri-svabhāva</em>)
            — три уровня, на которых ум воспринимает реальность. <em>Парикальпита</em> (<em>parikalpita</em>)
            — воображаемая природа. Ум принимает свои проекции как независимую реальность: «я» и
            «мир» кажутся отдельными, имеющими неизменную сущность. Это — корень всех заблуждений.
            <em>Паратантра</em> (<em>paratantra</em>) — зависимая природа. Ум видит, что всё
            возникает взаимозависимо: мысли, образы, чувства — всё это поток причин и условий.
            Но пока ещё не свободен от привычки делить опыт на «внутреннее» и «внешнее». <em>Паринишпанна</em>
            (<em>pariniṣpanna</em>) — совершенная природа. Прямое постижение того, что <em>паратантра</em>
            изначально чиста: нет ни «я», ни «мира», только недвойственная таковость
            (<em>татхата</em>).
            Это — реализация <em>шуньяты</em> без отрицания явления. Эти три природы — три способа видеть одно и то же.
            <em>Паринишпанна</em> — это та же
            <em>паратантра</em>, но очищенная от <em>парикальпиты</em>. Обычное существо видит
            <em>парикальпиту</em>, йогин — <em>паратантру</em>, просветлённый —
            <em>паринишпанну</em>. Бодхисаттва использует это различие, чтобы точно направлять
            других.<a href="#ref-12" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-13"><sup>13</sup> <strong>Восемь виджнян</strong> (<em>aṣṭau
                vijñānāni</em>) — восемь видов сознания, описываемых в учении <em>йогачары</em>
            и центральных для <strong><em>Ланкаватара-сутры</em></strong>. 1–5. Пять чувственных
            сознаний: зрительное, слуховое, обонятельное, вкусовое, осязательное. 6. Ментальное
            сознание (<em>мано-виджняна</em>) — различает объекты, строит мысли, работает с
            памятью и логикой. 7. <em>Манас</em> (<em>kliṣṭa-manas</em>) — омрачённое
            эго-сознание. Оно постоянно цепляется за алайю, принимая её за «я», и порождает
            четыре коренных клеши: самомнение (<em>ātma-māna</em>), ложное воззрение о «я» (<em>ātma-dṛṣṭi</em>),
            привязанность к себе (<em>ātma-sneha</em>) и неведение о себе (<em>ātma-avidyā</em>).
            8. <em>Алайя-виджняна</em> (<em>ālaya-vijñāna</em>) — сознание-хранилище. В нём
            хранятся все кармические отпечатки (<em>bīja</em>, «семена»), которые созревают как
            <em>васаны</em> (привычные склонности) и проявляются в виде опыта. Это — основа всех
            остальных сознаний: они возникают из <em>алайи</em> и питают её новыми отпечатками.
            Обычный человек не замечает ничего, кроме первых шести. Бодхисаттва, углубляясь в
            медитацию, распознаёт тонкую работу <em>манаса</em> (седьмого) и <em>алайи</em>
            (восьмого). При <em>āśraya-parāvṛtti</em> (повороте основы) <em>алайя-виджняна</em>
            преображается в <em>ādarśa-jñāna</em> (Зерцалоподобную Мудрость), а манас — в <em>samatā-jñāna</em>
            (Мудрость Равностности). Остальные шесть сознаний также преображаются в
            соответствующие Мудрости. Восемь виджнян преображаются в пять Мудростей
            (<em>pañca-jñāna</em>):
            Зерцалоподобную, Равностности, Различающую, Совершающую деяния и Дхармадхату — свободные
            от кармических наслоений. Именно постижение восьми виджнян позволяет бодхисаттве
            видеть механизм возникновения иллюзии «я» и конструирования мира умом. Это —
            практическая основа для <em>āśraya-parāvṛtti</em> и освобождения.<a href="#ref-13"
                                                                                class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-14"><sup>14</sup> <strong>Пудгала-найратмья</strong> (<em>pudgala-nairātmya</em>)
            — отсутствие «я» в личности. Обычное сознание принимает поток пяти <em>скандх</em> —
            <em>рупа</em> (форма), <em>ведана</em> (чувства), <em>санджня</em> (различение),
            <em>самскара</em> (ментальные формирующие факторы) и <em>виджняна</em> (сознание) —
            за постоянное «я», обладающее опытом. Учение о <em>пудгала-найратмье</em>
            показывает, что такого независимого, неизменного «я» нет. Личность — лишь временный
            набор условий, лишённый собственной сущности. Это первая ступень освобождения:
            устранение цепляния за «я». В <strong><em>Ланкаватара-сутре</em></strong> она неразрывна со
            второй — <em>дхарма-найратмьей</em>, ибо пока есть вера в «я», будет и вера в «вещи»
            как нечто реальное.<a href="#ref-14" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-15"><sup>15</sup> <strong>Дхарма-найратмья</strong> (<em>dharma-nairātmya</em>)
            — отсутствие самости в явлениях. Если <em>пудгала-найратмья</em> отрицает «я», то
            <em>дхарма-найратмья</em> отрицает независимую реальность самих составляющих опыта —
            форм, звуков, мыслей, чувств и даже элементов пути. Ни одно явление (<em>дхарма</em>)
            не обладает независимой, устойчивой природой. Все они возникают зависимо, длятся
            мгновение и исчезают. Это более тонкое постижение, чем отсутствие личности. Оно
            разрушает последнее убежище эго — веру в то, что хотя «я» и нет, зато «мир» реален.
            В <strong><em>Ланкаватара-сутре</em></strong> полная реализация возможна только тогда, когда
            ум видит: ни «я», ни «дхармы» не имеют собственной сущности — они шунья.<a
                href="#ref-15" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-16"><sup>16</sup> <strong>Адвая-гати</strong>
            (<em>advaya-gati</em>)
            — недвойственная стезя, путь, свободный от противопоставлений. Здесь нет разделения
            на «я» и «мир», «сансару» и «нирвану», «чистое» и «нечистое», «субъект» и «объект»,
            «бытие» и «небытие». Такой путь не ведёт от чего-то к чему-то — он есть прямое
            пребывание в природе ума, как она есть.<a href="#ref-16"
                                       class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-17"><sup>17</sup> Дворец Царя Нагов символизирует
            Алайя-виджняну — глубину сознания, где Дхарма пребывает в недоступной тишине. Семь
            дней — символ завершённого постижения, пребывания в недвойственном самадхи. Выход из
            него — спонтанное проявление сострадания: Дхармакая, оставаясь неизменной, являет
            Нирманакаю ради блага живых существ.<a href="#ref-17"
                                                   class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-18"><sup>18</sup> Встреча Будды с Индрой, Брахмой и
            дочерьми царей нагов в <strong><em>Ланкаватаре</em></strong> — это символическое указание
            на внутренние уровни сознания. Индра
            олицетворяет чувственный мир (<em>kāma-dhātu</em>), Брахма — мир форм
            (<em>rūpa-dhātu</em>),
            а дочери <em>нагов</em> — глубинные слои «океана ума» (<em>citta-samudra</em>), где
            пребывают кармические семена (<em>bīja</em>) и <em>васаны</em>. Ни одно из этих
            существ не является источником Дхармы. Их присутствие лишь указывает на то, что
            учение Будды охватывает все уровни сознания — от грубых до тончайших. Однако сама
            Дхарма не принадлежит ни чувственному, ни рассудочному, ни даже глубинному
            подсознательному уровню. Когда Будда покидает дворец Царя Нагов, истина переходит из
            невыразимой тишины недвойственности в сферу выражаемого. Боги и наги здесь лишь
            подтверждают, что путь к освобождению теперь доступен для восприятия на всех уровнях
            бытия. Суть этой встречи в том, что пробуждение превосходит любые состояния сознания
            — будь то чувственные наслаждения Индры или тончайшие блаженства Брахмы. Источник
            Дхармы лежит за пределами этой структуры, в «несотворённом» (<em>asaṃskṛta</em>),
            которое Будда выносит из глубины океана для блага всех существ.<a href="#ref-18"
                                                                              class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-19"><sup>19</sup> Улыбка Будды (<em>smita</em>) — знак
            узнавания и преемственности. Взглянув на гору Малайя, Будда видит, что это место,
            где Дхарма всегда провозглашалась. Его улыбка — подтверждение, что он вступает в ту
            же стезю, что и все Татхагаты прошлого.<a href="#ref-19"
                                                      class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-20"><sup>20</sup> «<strong>Благородная мудрость</strong>» (<em>svapratyātmārya-jñāna</em>)
            — знание, постигаемое непосредственно в личном опыте, без опоры на слова, логику или
            авторитет. Оно возникает только в результате глубокого преобразования ума и
            недоступно тому, кто полагается на представления/идеи. <em>svapratyātma</em>
            подразумевает «своё собственное» знание, не заимствованное, не выведенное, раскрытое
            изнутри.<a href="#ref-20" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-21"><sup>21</sup> <strong>Тарка</strong> (<em>tarka</em>) —
            логическое рассуждение, умствование, основанное на двойственности
            «субъект–объект».<a href="#ref-21" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-22"><sup>22</sup> «<strong>Проявили […] Дхарму</strong>»
            (<em>tadbhāvito dharmo</em>) — глагол <em>deśitaḥ</em> («излагалась») определяется
            причастием <em>tadbhāvitaḥ</em> — «сделанная таковой», «доведённая до подлинного
            бытия». Это означает: Дхарма возникла из самой природы пробуждения Татхагат и была
            проявлена как живое событие.<a href="#ref-22" class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-23"><sup>23</sup> В <strong><em>Ланкаватаре</em></strong> фигуры
            Раваны и города Ланки имеют символический характер. Равана, царь ракшасов,
            представляет ум огромной силы и проницательности, способный как к глубокому
            заблуждению, так и к пониманию. Ланка на вершине горы Малайя — образ
            труднодоступного внутреннего пространства, «крепости сознания», где возможно
            преобразование. Происхождение Раваны в индийской традиции подчёркивает эту
            двойственность. Его отец, мудрец Вишрава, был сыном Пуластьи и внуком Брахмы, что
            помещает Равану в линию «рожденных из ума» божественных прародителей и объясняет его
            выдающийся интеллект и знание Вед. Его мать, Кайкеши, происходила из рода ракшасов и
            стремилась родить наследника, способного вернуть им былую силу и власть. Из этого
            союза возникает фигура, сочетающая мудрость брахмана с мощью ракшаса. История
            возвышения Раваны далее усиливает этот образ. Он не унаследовал власть:
            первоначально Ланкой правил его брат Кубера. Добившись силы благодаря суровым
            аскезам перед Брахмой и получив обещание неуязвимости от богов и асуров, Равана
            сверг Куберу и овладел Ланкой и всем его богатством. Его эпитет «Десятиглавый» (<em>Daśagriva</em>)
            символически указывает на знание четырёх Вед и шести шастр, а также на способность
            управлять всеми направлениями опыта. В шиваитской традиции он известен как великий
            бхакта Шивы и автор почитаемого гимна <strong><em>Шива-тандава-стотра</em></strong>.
            Использование Раваны как центрального собеседника в буддийской сутре — не
            случайность. Эта фигура воплощает вершину мирского могущества, магической силы и
            интеллектуальной эрудиции. То, что именно Равана приглашает Будду и склоняется перед
            ним, подчёркивает ключевой мотив <strong><em>Ланкаватара-сутры</em></strong>: даже высшая
            форма мирского знания и силы уступает прямому пониманию природы сознания. Дхарма
            превосходит и побеждает как грубые страсти, так и утончённое рассудочное знание.<a
                href="#ref-23" class="text-blue-500 hover:underline">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-24"><sup>24</sup> <strong>Сила благословения
                Татхагат</strong> (<em>tathāgatādhiṣṭhāna</em>) — милость
            Будд, без которой невозможно даже услышать Дхарму. Без неё Равана, несмотря на своё
            могущество, остался бы глух к учению.<a href="#ref-24"
                                                    class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-25"><sup>25</sup> <strong>Алайя-виджняна</strong> (<em>ālayavijñāna</em>)
            — «сознание-сокровищница», восьмое сознание в учении йогачары. В нём, как в океане,
            под действием «ветра» чувственного восприятия и <em>клеш</em> возникают «волны» —
            мысли, эмоции и кажущийся внешний мир. В этом образе внешний океан и внутренний —
            одно: всё есть лишь видимое собственным умом. <em>Алайя</em> — как океан; семь сознаний —
            как волны. Ветер неведения движет их. Когда ветер стихает и волны успокаиваются —
            сам океан преобразуется: <em>алайя-виджняна</em>, освобождаясь от <em>васан</em>,
            раскрывается как <em>ādarśa-jñāna</em> (Зерцалоподобная Мудрость).<a href="#ref-25"
                                                                                 class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-26"><sup>26</sup> <strong>Колесница Пушпака</strong> —
            «Цветочная вимана» — самодвижущаяся воздушная колесница, первоначально
            принадлежавшая Кубере, хранителю севера и сокровищ земли. Согласно «Рамаяне», её
            захватил Равана, изгнав Куберу из Ланки. В буддийских текстах Пушпака символизирует
            высокое положение.<a href="#ref-26" class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-27"><sup>27</sup> <strong>Вина</strong> (<em>vīṇā</em>) —
            один из древнейших и наиболее почитаемых музыкальных инструментов Индии. Это
            струнный щипковый инструмент с длинной шейкой и двумя резонаторами (обычно
            тыквенными или деревянными), натянутыми между ними струнами — чаще всего семью, хотя
            число могло варьироваться. В ведической и буддийской традициях <em>вина</em> — символ
            гармонии между мудростью и состраданием. Её звук
            считался способным успокоить ум, рассеять помехи и подготовить слушателя к
            восприятию Дхармы. В индуизме <em>вина</em> — атрибут <em>Сарасвати</em>, богини
            знания, речи и искусства. В буддийских текстах (особенно махаянских) она часто
            звучит при встрече с Буддой — как знак того, что пространство очищено, а собрание
            готово слушать. Когда Равана берёт вину — он совершает
            подношение через звук, превращая музыку в путь, ведущий к внутреннему постижению.
            Именно на фоне её мелодии он начинает петь <em>гатхи</em>.<a href="#ref-27"
                                           class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-28"><sup>28</sup> <strong>Индранела</strong>
            (<em>indranīla</em>) — драгоценный камень цвета неба, обычно лазурит или синий
            сапфир. В индийской традиции считается камнем Индры, царя богов.<a href="#ref-28"
                                                                               class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-29"><sup>29</sup> <strong>Вайдурья</strong>
            (<em>vaiḍūrya</em>) — драгоценный камень, упоминаемый в индийских и буддийских
            текстах как один из главных самоцветов. Его точная природа варьируется в зависимости
            от эпохи и региона: В древнеиндийских источниках (включая ранние буддийские сутры)
            <em>vaiḍūrya</em> обычно означает лазурит — глубокий сине-голубой камень с
            золотистыми прожилками, добывавшийся в Афганистане и высоко ценившийся за его
            небесный цвет. В поздних текстах (особенно в тибетской и китайской традициях) под
            <em>vaiḍūrya</em> часто подразумевают изумруд или зелёный берилл. В некоторых
            контекстах — прозрачный горный хрусталь или даже опал, если речь идёт о сиянии, а не
            цвете. В <strong><em>Ланкаватаре</em></strong> и других махаянских сутрах <em>вайдурья</em>
            символизирует чистоту, прозрачность ума и способность отражать истину без искажений.
            Этимология неясна. Согласно одной версии, название происходит от города Видура
            (Южная Индия), где добывали этот камень. Возможна также связь с греческим
            <em>beryllos</em> (берилл), хотя направление заимствования остаётся предметом дискуссий.<a
                href="#ref-29" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-30"><sup>30</sup> <strong>Приянга</strong>
            (<em>Priyaṅgu</em>, предположительно <em>Aglaia elaeagnoidea</em> или <em>Callicarpa
                macrophylla</em>) — тропическое растение, распространённое в Индии и
            Юго-Восточной Азии. Известно своими мелкими, густыми соцветиями белых или
            бледно-жёлтых цветов, которые источают нежный, сладковатый аромат. В санскритской
            поэзии и буддийских текстах цветы <em>приянги</em> — символ нежности, чистоты и
            благоухания добродетели. Их белый цвет часто сравнивают с лунным светом, снегом на
            вершинах Гималаев или чистой шёлковой тканью. Упоминание «ткани цвета
            <em>приянги</em>» — аллегория свежести, мягкости и духовной чистоты. Когда
            Равана обвивает вину такой тканью — он подготавливает пространство для восприятия Дхармы через
            образ безупречности.<a href="#ref-30" class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-31"><sup>31</sup> <strong>Музыкальное подношение
            Раваны</strong> — сложное ритуальное действие, свидетельствующее о владении
            <em>сангита-шастрой</em> — наукой о звуке. Перечисление терминов — <em>шадджа, ришабха, гандхара,
            мадхьяма, дхаивата, нишада</em> — указывает на семь основных звуков (<em>свар</em>), которые в
            индийской традиции соотносятся с <em>чакрами</em>, планетами и уровнями космоса.
            Особое внимание привлекает <em>кайшика</em> — термин, обозначающий тончайший
            микротоновый оттенок (<em>шрути</em>). В классических трактатах, таких как <strong><em>Натьяшастра</em></strong>,
            <em>кайшика</em> не является самостоятельной нотой, а указывает на утончённую
            градацию звука. Её упоминание вместо стандартной пятой ступени (<em>панчамы</em>)
            подчёркивает исключительность исполняемого лада — вероятно, редкой ритуальной
            системы, предназначенной для воздействия на тонкие уровни сознания. Эта музыка
            опирается на строгую теоретическую основу: <em>грамы</em> и <em>мурччханы</em>. <em>Грама</em>
            — базовая ладовая система; в древности их было три (<em>Ṣaḍja-grāma</em> — основная,
            <em>Madhyama-grāma</em> — вторичная, <em>Gāndhāra-grāma</em> — утрачена к
            средневековью), каждая из которых соотносилась с одним из трёх миров.
            <em>Мурччхана</em> — способ получения новых ладов путём смещения тоники, аналогичный
            античным модусам. Владение четырнадцатью <em>мурччханами</em> (по семь для каждой из
            двух сохранившихся <em>грам</em>) символически означало власть над четырнадцатью
            мирами вселенной. Сам инструмент описан как микрокосм: гриф из <em>индранелы</em>
            (синего сапфира), накладки из <em>вайдурьи</em> (берилла или лазурита), ткань цвета
            <em>приянги</em> — всё это не украшение, а символическая структура. Струны вины
            уподобляются энергетическим каналам (<em>нади</em>), её корпус — телу Вселенной.
            Таким образом, Равана предстаёт не как мифологический демонический тиран, он —
            великий аскет и мастер <strong><em>Гандхарва-веды</em></strong> — ведической науки о
            ритуальном звуке. Согласно канону, особенно <strong><em>Самаведе</em></strong>, безупречное
            исполнение такой музыки очищает пространство и «настраивает» ум слушателя. Равана
            выступает как ритуальный исполнитель, подготавливающий пространство для проповеди
            Будды через гармонию звука, формы и намерения.<a href="#ref-31"
                                                             class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-32"><sup>32</sup> <strong>Устойчивое ошибочное
                воззрение</strong> (<em>dṛṣṭi</em>) — рассудочное убеждение, принимаемое за
            окончательную истину. Оно является глубоко укоренившейся зацикленностью ума, возникающей из пристрастия к
            построению систем понятий (<em>vikalpa</em>). Такие воззрения формируют ложные
            представления о существовании «я», о сущностях, о мире и о способе их существования
            — будь то вера в вечность, уничтожение, тождество или различие, бытие или небытие. В
            канонических текстах, особенно в <strong><em>Брахмаджала-сутте</em></strong> (<em>Brahmajāla
                Sutta, Дигха-никая 1</em>), перечисляется 62 вида подобных воззрений, образующих
            «сеть» (<em>jāla</em>), в которую попадает ум, пытаясь уловить реальность через
            двойственные категории. Все они опираются на основополагающее разделение субъекта и
            объекта, порождают цепляние за «я» (<em>ātma-graha</em>) и «моё» и тем самым
            порождают, поддерживают и усиливают страдание и круг перерождений. Истинная Дхарма,
            согласно как ранним, так и махаянским источникам, не является ни философской
            позицией, ни даже «правильным» мнением. Она не утверждает ни бытия, ни небытия, не
            принимает и не отвергает сущностных утверждений и не может быть полностью выражена
            словами, логикой или понятиями. Освобождение — это постижение природы реальности в
            непосредственном опыте (<em>pratyātma-vedya</em>), за пределами всех конструкций
            ума.<a href="#ref-32" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-33"><sup>33</sup> <strong>Путь, постигаемый непосредственно
                (лично)</strong> (<em>pratyātma-vedya-gati</em>) — это путь, который невозможно
            усвоить через слушание (<em>śruta</em>), чтение, логическое умозаключение
            (<em>anumāna</em>)
            или опору на авторитет (<em>āgama</em>). Он принадлежит исключительно сфере личного,
            недвойственного опыта, свободного от посредничества слов, символов, понятий и
            рассудочного анализа. В <strong><em>Ланкаватаре</em></strong> подчёркивается:
            Дхарма — это реальность, подлежащая внутреннему видению. Поэтому Будда говорит:
            «Я не проповедую Дхарму» — ибо подлинная Дхарма не есть нечто, что можно передать.
            Она — то, что должно быть увидено каждым самостоятельно. Этот термин противопоставляется
            постижению через внешние источники — всему, что опирается на Учителя, тексты,
            рассуждение, традицию, символы, ритуалы или веру. Даже «правильные взгляды», если
            они остаются на уровне понятий, не ведут к освобождению, поскольку продолжают быть
            <em>dṛṣṭi</em> — устойчивыми ложными воззрениями, пусть и внешне корректными.
            Непосредственное постижение в <strong><em>Ланкаватаре</em></strong> — это ясное видение природы
            ума, сопровождаемое прекращением всех воззрений (<em>dṛṣṭi-nirodha</em>) и
            отсечением умственных построений (<em>vikalpa-kṣaya</em>). Освобождение не происходит
            благодаря рождению новой идеи или нового переживания, оно случается через распад всей
            структуры схватывания, в которой ум конструирует субъект, объект и их отношения.
            Именно поэтому даже Равана — владыка ракшасов — способен услышать Дхарму Татхагаты.
            Его «демоническая природа» не является препятствием: ум, готовый отпустить ложные
            воззрения, способен к непосредственному постижению, независимо от кармического
            прошлого или статуса. В <strong><em>Ланкаватаре</em></strong> важна не нравственная оценка
            персонажей, имеет значение их готовность в данный момент перестать цепляться за фиксации ума.
            Таким образом, встреча Раваны с Буддой — указание на
            внутреннюю возможность: когда ум выходит за пределы <em>vikalpa</em> и
            <em>dṛṣṭi</em>, становится возможно прямое постижение Дхармы.<a href="#ref-33"
                                                                            class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-34"><sup>34</sup> <strong>Нирмана</strong>
            (<em>nirmāṇa</em>) — «созидание-проявление», «чудесное воплощение». В махаянской
            доктрине это активное действие сострадательного созидания,
            посредством которого Будда создаёт формы — тела, голоса, миры, учения, даже
            множества «двойников» — в соответствии с потребностями существ. Отсюда Нирманакая —
            Тело Проявления, возникающее из деятельности Будды, а не из кармы. Важно различать
            <em>nirmāṇa</em> и <em>nirmita</em>. Первое — процесс, способность, акт проявления; второе —
            результат: «созданное», «проявленная форма», «чудесное творение». В
            <strong><em>Ланкаватаре</em></strong>
            эта разница подчёркнута формулой <em>nirmāṇa-nirmitapradarśanakaṃ</em> —
            «показывающий <em>nirmāṇa</em> и <em>nirmita</em>», то есть и само действие проявления, и его
            проявленные формы. Грамматически: <em>nirmāṇa</em> — отглагольное существительное от
            √<strong>mā</strong> («создавать»), обозначающее действие; <em>nirmita</em> —
            причастие прошедшего времени, означающее «сотворённое». Распространённая ошибка —
            смешивать их, переводя <em>nirmāṇa</em> как «проявленный объект». Но объект — это
            <em>nirmita</em>; <em>nirmāṇa</em> же — живая сила сострадания, выражающаяся в
            форме. Именно поэтому Будда может быть одновременно недвойственным (в Дхармакае) и
            множественным (в Нирманакае): Его сострадание не остаётся в покое и творит формы,
            чтобы достичь каждого, кто готов услышать.<a href="#ref-34"
                                                         class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-35"><sup>35</sup> <strong>«Ты пребываешь в радости, когда
                Дхарму постигают лично»</strong> — Радость Будды возникает, когда ум слушателя
            выходит за пределы всех внешних опор: Учителя, канона, ритуала, даже «правильного
            воззрения». Подлинная Дхарма — это то, что постигается непосредственно (<em>pratyātma-vedya</em>),
            а не передаётся как учение. Будда — лишь указующий палец (в примере с Луной); он
            теряет смысл, как только взгляд обращён на Луну. Поэтому говорится:
            «За сорок пять лет проповеди Будда не произнёс ни единого слова». Ибо истинная Дхарма
            раскрывается сама, когда ум
            отпускает все ложные воззрения (<em>dṛṣṭi</em>) и прекращает умственное
            конструирование (<em>vikalpa</em>).<a href="#ref-35"
                                                  class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-36"><sup>36</sup> <strong>Якши, владеющие множеством
                обликов</strong> — здесь символ подвижного,
            многоликого сознания, способного быстро менять свои состояния. В
            <strong><em>Ланкаватаре</em></strong> их «слушание» Дхармы означает, что истина доступна даже
            такому уму, который кажется нестабильным, противоречивым или слишком изменчивым для
            практики. Главное — готовность открыться. Это продолжает
            тему Раваны: даже демонический, многоглавый, страстный ум может стать сосудом для
            Дхармы.<a href="#ref-36" class="text-blue-500 hover:underline">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-37"><sup>37</sup> <strong>То́така</strong> (<em>toṭaka</em>)
            — санскритский стихотворный размер, состоящий из четырёх строк по 12 слогов. Часто
            использовался в гимнах и философских стихах. Сам Ади Шанкара писал гимны в этом
            размере. В <strong><em>Ланкаватаре</em></strong> указание на <em>то́така</em> подчёркивает, что
            речь Раваны — ритуально-поэтическое подношение, достойное Будды.<a
                href="#ref-37" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-38"><sup>38</sup> <strong>Попугаи и майны</strong> —
            символы двух типов восприятия. Попугай олицетворяет повторение без понимания: он
            может точно воспроизвести речь, но не постигает её смысла. Майна — птица, известная
            своей чуткостью к звуку, — символ внимательного, внутреннего слушания. Их совместное
            упоминание подчёркивает, что истинное постижение требует не повторения слов, а
            живого отклика ума.<a href="#ref-38" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-39"><sup>39</sup> <strong>Кумбхакарна</strong> в
            <strong><em>Рамаяне</em></strong> —
            брат Раваны, гигант, погружённый в многолетний сон, пробуждающийся лишь для еды или
            битвы. Он олицетворяет инертное, спящее сознание, скованное неведением. Однако даже
            он, пробуждаясь, способен к ясности и мудрости — он критикует Равану за беззаконие,
            хотя и остаётся верен долгу. Его упоминание здесь — знак того, что даже самое
            тяжёлое, дремлющее сознание способно пробудиться к Махаяне, если возникает контакт с
            Дхармой.<a href="#ref-39" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-40"><sup>40</sup> <strong>Апсары</strong> — небесные девы,
            символы чувственного наслаждения; рощи <strong>ашоки</strong> — «деревья без
            страдания» (<em>a-śoka</em>), чьё имя обещает утешение. Рощи ашоки символизируют состояние ума,
            свободное от волнений, вызванных ветром неведения. Принося их в дар, Равана демонстрирует
            готовность заменить сансарическое утешение (временное отсутствие боли) на нирванический покой.<a
                href="#ref-40" class="text-blue-500 hover:underline">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-41"><sup>41</sup> <strong>Явил Дхарму</strong> (<em>vibhāvayāmāsa</em>)
            — не означает словесного изложения. Глагол <em>vibhāvayati</em> (каузатив от <em>bhāvayati</em>)
            обозначает акт внутреннего проявления или «вызывания к бытию».
            Здесь Будда, приняв подношения, не произносит ещё ни слова, но своим присутствием
            раскрывает поле Дхармы, делая её внутреннюю суть ощутимой для бодхисаттв и иных
            присутствующих. Это — преддверие проповеди: истина, которая постигается только лично
            (<em>pratyātma-gati</em>), сначала проявляется в безмолвном пространстве между Учителем
            и учениками, и лишь затем облекается в форму ответов на вопросы Раваны.<a href="#ref-41"
                                                                                      class="text-blue-500 hover:underline">↩</a>
        </p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-42"><sup>42</sup> В <strong><em>Ланкаватаре</em></strong> Махамати —
            главный вопрошающий, носитель высшей йогачаринской мудрости. Его имя означает «Великий
            Ум» (<em>Mahā-mati</em>), и он символизирует ум, способный вместить недвойственное
            знание. Махамати задаёт вопросы, которые становятся основой для изложения глубокой
            Дхармы. В каждую эпоху у каждого Будды есть такой вопрошающий о <em>pratyātma-gati</em>
            — Дхарме, постигаемой лично, вне слов.<a href="#ref-42"
                                                     class="text-blue-500 hover:underline">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-43"><sup>43</sup> <strong>Сон</strong> (<em>svapna</em>) —
            опыт, обладающий реальностью лишь внутри сновидения, демонстрирует отсутствие различия
            между субъектом и объектом: и то, и другое порождены одним умом. <strong>Мираж</strong>
            (<em>mṛgatṛṣṇ</em>ā) — видимость воды в пустыне, лишённая плотности и сущности,
            символизирует влечение ума к объектам, которые не существуют вне желания. <strong>Город
                гандхарвов</strong> (<em>gandharva-nagara</em>) — небесный град, возникающий в
            воздухе, показывает, как привычные отпечатки сознания (<em>васаны</em>) создают иллюзию
            устойчивого и внешнего мира. <strong>Помутнение зрения</strong> (<em>timira</em>) —
            зрительная иллюзия (например, видение двух лун при катаракте), указывает на то, что даже
            «ясное» восприятие может быть искажено природой самого ума. <strong>Сын
                бесплодной</strong> (<em>vandhyā-putra</em>) — образ, подчёркивающий абсолютное
            отсутствие объекта; подобно тому как у бесплодной женщины нет ребёнка, так и у всех
            явлений отсутствует неизменная сущность. <strong>Огненное колесо</strong>
            (<em>alāta-cakra</em>) — иллюзия непрерывного огненного следа, возникающая от быстрого
            вращения горящей палочки, демонстрирует иллюзию непрерывности: мир состоит из мгновенных
            вспышек сознания, создающих видимость плотного, длящегося бытия.<a href="#ref-43"
            class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-44"><sup>44</sup> Видение Раваны — прямое раскрытие природы
            ума. Горы, драгоценности, множественные образы Будды и Раваны представляют собой
            проекции потока сознания, лишённого субъектно-объектной двойственности. Эта демонстрация
            лишает воспринимаемый мир внешней опоры. Сомнения Раваны — «сон? мираж? город
            гандхарвов?» — перечисляют классические примеры обманчивого восприятия, принятые в
            индийской философии для иллюстрации природы иллюзии. Такое понимание вызывает у Раваны
            внезапное прозрение (<em>avabodha</em>). Царь ракшасов осознаёт мир как порождение
            собственного ума. Происходит его преображение: Равана перестаёт воспринимать себя только
            как правителя и становится готовым принять Дхарму. Истинная природа реальности
            открывается ему в недвойственном состоянии (<em>advaya</em>), когда <em>викальпа</em>
            (конструирующая активность ума) прекращается.<a href="#ref-44"
                                                            class="text-blue-500 hover:underline">↩</a>
        </p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-45"><sup>45</sup> <strong>«Пробудился
                непосредственно»</strong> — термин указывает на
            момент прямого прозрения (<em>avabodha</em>), когда ум Раваны внезапно постигает природу
            реальности. В это мгновение он оставляет привычку воспринимать мир как внешнюю среду и
            обретает прямое видение: всё видимое представляет собой проявление ума, лишённого
            субъектно-объектной двойственности.</p>
        <p>Данный акт является глубоким сдвигом в восприятии — <em>париджняной
                svacitta-dṛśya-gocara</em> (исчерпывающим постижением того, что мир есть сфера
            проявления ума). После такого сдвига видение реальности изменяется фундаментально, хотя
            полная стабилизация требует дальнейшей практики.</p>
        <p>Подобное пробуждение описывается как личное постижение (<em>pratyātma-vedya</em>) —
            уникальный опыт, который пребывает вне сферы передачи словами, но преображает природу
            познающего. Это переход от интеллектуального анализа к непосредственному пребыванию в
            реальности «как она есть» (<em>yathābhūta</em>).</p>
        <p>Именно это прозрение делает Равану готовым услышать глубокую Дхарму о пути, постигаемом
            лично (<em>pratyātma-gati</em>), которую Будда затем излагает.<a href="#ref-45"
                                                                             class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-46"><sup>46</sup> <strong>«Когда его основа
                преобразилась»</strong>
            (<em>parāvṛttāśraye</em>) — термин, указывающий на момент прямого прозрения, когда
            структура восприятия радикально изменяется.</p>
        <p><em>Āśraya</em> («опора») — базовое сознание (<em>ālayavijñāna</em>), в котором
            накапливаются кармические отпечатки (<em>васаны</em>) и из которого возникает иллюзия
            разделения на «я» и «мир».</p>
        <p><em>Parāvṛtti</em> («поворот») — в полном смысле это необратимое преображение <em>алайя-виджняны</em>
            в <em>ādarśa-jñāna</em> (Зерцалоподобную мудрость), происходящая при достижении
            буддовости.</p>
        <p>Однако в данном контексте термин <em>parāvṛttāśraya</em> описывает начальное переживание
            этого поворота — момент, когда Равана впервые постиг (<em>adhigama</em>), что весь
            видимый мир есть лишь <em>svacitta-dṛśya-mātra</em> (проявление собственного ума). Это
            не окончательная <em>паравритти</em>, но решающий прорыв: ум временно освобождается от
            грубой двойственности и напрямую видит свою истинную природу.</p>
        <p>Будда хвалит Равану словами «<em>sādhu, sādhu</em>» («отлично, отлично») и говорит: «<em>evaṃ
                śikṣitavyaṃ yoginā</em>» («так должен учиться йогин»), указывая, что Равана испытал
            правильное постижение, открывающее путь к полной реализации, но ещё продолжает обучение.
        </p>
        <p>После этого прозрения Равана становится готовым вместилищем Дхармы, способным воспринять
            глубокое учение о <em>pratyātma-gati</em> (пути, постигаемом лично).<a href="#ref-46"
                                                                                   class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-47"><sup>47</sup> <strong>«Всё видимое — лишь проявление
                собственного ума</strong>
            (<em>svacitta-dṛśya-mātra</em>) — воспринимаемый объект не имеет
            внешней опоры: он возникает вместе с актом восприятия, как волна в океане ума.</p>
        <p><em>Svacitta</em> — «собственный ум — ум как таковой, лишённый разделения на
            «я» и «не-я».</p>
        <p><em>Mātra</em> — «лишь» — отсекает веру в реальность внешних сущностей.</p>
        <p>Таким образом, <em>svacitta-dṛśya-mātra</em> — это отрицание двойственности. Постижение
            этого видения открывает путь к <em>āśraya-parāvṛtti</em> — полному повороту основы
            сознания, который завершится при достижении буддовости.<a href="#ref-47"
                                                             class="citation-back">↩</a></p>
        <p class="my-2" id="citation-48"><sup>48</sup> <strong>«Утвердился в сфере безмолвия, где
            прекратилось движение умопостроений»</strong> (<em>avikalpa-pracāra-sthita</em>) — состояние,
            в котором ум перестаёт порождать поток понятий.</p>
        <p><em>Pracāra</em> — «движение», «циркуляция» — описывает обычное состояние сознания,
            непрерывно проецирующее субъект, объект и их отношения.</p>
        <p><em>Avikalpa</em> — «отсутствие умственного конструирования» — это не оцепенение и не
            пустое безмыслие, это ясное осознавание, свободное от сетки определений: «я / не-я», «сущее /
            несущее», «истина / ложь».</p>
        <p>Утверждение в этом состоянии означает, что Равана более не анализирует, не сравнивает, не
            интерпретирует — он пребывает в том, что есть. Именно так становится возможным непосредственное
            восприятие учения Татхагаты — вне слов и понятий, как прямое узнавание собственной природы Будды
            (<em>tathāgatagarbha</em>). Это состояние — необходимое условие перехода от
            интеллектуального понимания к непосредственному постижению.<a href="#ref-48"
                                                                          class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-49"><sup>49</sup> <strong>«Побуждаемый корнями благого,
            взращёнными в прошлом»</strong> (<em>pūrvakuśalamūlasaṃcodita</em>)
            — указывает на внутреннюю зрелость, необходимую для подлинного постижения.</p>
        <p>Корни благого (<em>kuśala-mūla</em>) — технический термин, обозначающий устойчивые
            качества ума: прежде всего отсутствие жадности (<em>alobha</em>), гнева (<em>adveṣa</em>)
            и заблуждения (<em>amoha</em>). В случае Раваны это его прошлые аскезы, преданность и
            изучение наук, которые подготовили почву для преображения.</p>
        <p>Побуждение (<em>saṃcodita</em>) — внутренний импульс, возникающий, когда внешнее условие
            (встреча с Буддой) встречается с внутренней готовностью.</p>
        <p>Эта фраза поясняет, почему Равана — владыка ракшасов — способен непосредственно войти в
            состояние <em>avikalpa</em>. Его пробуждение — естественный расцвет того, что было
            посеяно в прошлом.<a href="#ref-49" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-50"><sup>50</sup> <strong>«Сведущий во всех шастрах»</strong>
            (<em>sarva-śāstra-vidagdha</em>) — указывает на глубокое овладение каноническими
            науками: философией, логикой, грамматикой, метрикой, искусством и дхармой.</p>
        <p><em>Vidagdha</em> — «закалённый» — означает разум, прошедший через строгую дисциплину
            учения и очищенный от грубого невежества.</p>
        <p>Именно такой ум способен постичь <em>читтаматру</em> и встать на путь
            к <em>āśraya-parāvṛtti</em>: лишь тот, кто в совершенстве познал пределы понятийного
            мышления, может его отпустить.</p>
        <p>Поэтому Равана, несмотря на свою природу ракшаса, непосредственно распознаёт в явлении
            Будды то, что превосходит все шастры, — и переходит от анализа к непосредственному
            постижению.<a href="#ref-50" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-51"><sup>51</sup> <strong>«Видящий вещи такими, каковы они
                есть»</strong> (<em>yathātathya-darśana</em>)
            — прямое видение реальности, свободное от искажений желания, страха и понятийного
            мышления.</p>
        <p><em>Yathātathya</em> — «согласно их истинной природе» — означает восприятие вещей такими,
            каковы они есть: лишёнными собственной неизменной сущности (<em>niḥsvabhāva</em>), пустыми (<em>śūnya</em>)
            по природе. Это синоним <em>татхаты</em> — «таковости».</p>
        <p><em>Darśana</em> — «видение» — непосредственное прозрение умом, в
            котором объекты распознаются как проекции собственного ума (<em>svacitta-dṛśya-mātra</em>).
        </p>
        <p>Такое видение становится возможным только после прекращения <em>викальп</em> — умственных
            конструкций. Оно знаменует момент, когда постижение Раваны переходит от понятийного к
            непосредственному, делая его готовым к дальнейшему продвижению на пути.<a href="#ref-51"
                                                                                      class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-52"><sup>52</sup> <strong>«Не нуждающийся в чужом
                руководстве»</strong>
            (<em>aparapraṇeya</em>) — термин, обозначающий способность самостоятельно постигать
            Дхарму через прямой опыт. Это состояние йогина, который опирается на непосредственное
            видение реальности (<em>pratyātma-vedya</em>).</p>
        <p>После прозрения Равана различает истину и заблуждение исходя из внутреннего опыта.
            Это делает его способным воспринять глубокое учение Будды как подтверждение собственного
            постижения.<a href="#ref-52" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-53"><sup>53</sup> <strong>«Искусный в исследовании
                собственного разума»</strong> (<em>svabuddhi-vicālana-kuśala</em>)
            — указывает на способность йогина непосредственно наблюдать природу своего интеллекта.
        </p>
        <p><em>Svabuddhi</em> — «собственный разум» — здесь означает сам механизм аналитическогопознания.</p>
        <p><em>Vicālana</em> — «исследование» — активное всматривание в работу ума с целью
            распознать скрытые проекции различения.</p>
        <p><em>Kuśala</em> — «искусный» — подчёркивает, что Равана владеет самонаблюдением как
            мастерством.</p>
        <p>Именно это позволяет ему увидеть, как ум строит иллюзию субъекта и объекта, — и тем
            самым открывает путь к <em>āśraya-parāvṛtti</em>: повороту, при котором <em>алайя-виджняна</em>
            полностью освобождается от омрачений и раскрывается как <em>ādarśa-jñāna</em>
            (Зерцалоподобная мудрость).<a href="#ref-53" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-54"><sup>54</sup> <strong>«Свободный от рассудочных
                воззрений»</strong> (<em>tarka-dṛṣṭi-vyapeta</em>)
            — указывает на выход за пределы формальной логики как средства постижения истины.</p>
        <p><em>Tarka</em> — «рассуждение» — метод умозаключения, полезный на начальных этапах пути,
            но неспособный проникнуть в недвойственную природу реальности, ибо всегда опирается на
            разделение.</p>
        <p><em>Dṛṣṭi</em> — «воззрение» — здесь означает привязанность к рассудочным воззрениям
            (<em>tarka-dṛṣṭi</em>) как к окончательной истине.</p>
        <p><em>Vyapeta</em> — «ушедший за пределы» — означает, что Равана более не пытается
            «вывести» Дхарму логически, его видение (<em>darśana</em>) стало непосредственным,
            прямым.<a href="#ref-54" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-55"><sup>55</sup> <strong>«Принимающий вселенскую
                форму»</strong> (<em>mahā-viśvarūpa-dhārin</em>)
            — способность йогина проявлять бесчисленные формы без
            привязанности к какой-либо из них, постигнув их как проявления собственного
            ума.<a href="#ref-55" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-56"><sup>56</sup> <strong>«Умелый в искусных
                средствах»</strong> (<em>upāyakauśalya</em>)
            — способность йогина являть Дхарму в любой подходящейформе и там, где есть существо,
            готовое её воспринять.<a href="#ref-56" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-57"><sup>57</sup> <strong>«Искусный в последовательном
                постижении отличительных признаков
                всех ступеней»</strong> (<em>sarva-bhūmy-uttarottara-sva-lakṣaṇādhigama-kuśala</em>)
            — указывает на глубокое знание внутренней структуры пути.</p>
        <p><em>Bhūmi</em> — «земли, степени, ступени» — десять ступеней бодхисаттвы, каждая из
            которых имеет свою природу и функцию.</p>
        <p><em>Uttarottara</em> — «последовательный, один выше другого» — означает понимание того,
            как каждое состояние естественно рождает следующее.</p>
        <p><em>Svalakṣaṇa</em> — «собственные признаки» — указывает на способность непосредственно
            распознавать каждую ступень по её внутреннему качеству, а не по внешним проявлениям.</p>
        <p>Такое мастерство (<em>kuśala</em>) свидетельствует о зрелости Раваны как йогина,
            подготовленного прошлыми аскезами и накоплением корней благого. Оно позволяет ему не
            останавливаться на промежуточных состояниях, а стремиться к сфере личного постижения
            Татхагаты (<em>pratyātma-gati</em>).<a href="#ref-57" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-58"><sup>58</sup> <strong>«Радующийся различению природы
                ума, интеллекта и различающего сознания»</strong>
            (<em>cittamanomanovijñāna-svabhāva-viveka-rata</em>) — глубокое понимание
            структуры ума.</p>
        <p><em>Citta</em> — базовый ум, вместилище всех отпечатков (<em>васан</em>), тождественный
            <em>алайя-виджняне</em>.</p>
        <p><em>Manas</em> (<em>kliṣṭa-manas</em>) — интеллект, омрачённое эго-сознание,
            цепляющееся за <em>алайя-виджняну</em> как за «я», порождая двойственность.</p>
        <p><em>Manovijñāna</em> — ментальное сознание, интерпретирующее данные чувств и порождающее
            структыры понятий (<em>викальпы</em>).</p>
        <p><em>Viveka</em> — «различение» — здесь это ясное видение их
            природы: все три — взаимозависимые аспекты единого потока сознания, лишённые
            собственной сущности.</p>
        <p><em>Rata</em> — «радующийся» — означает, что для Раваны это различение стало безусильным
            естественным состоянием. В этом — подлинная радость йогина: увидеть механизмы ума и
            более не быть ими обманутым.<a href="#ref-58" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-59"><sup>59</sup> <strong>«Прекративший тройственную
                непрерывность видимого»</strong>
            (<em>trisaṃtati-vyavacchinna-darśana</em>) — разрыв с механизмами, порождающими иллюзию
            сансарического опыта.</p>
        <p><em>Trisaṃtati</em> — «три потока преемственности»: поток причин (кармические отпечатки,
            <em>васаны</em>), поток объектов (кажущаяся устойчивость внешнего мира), поток сознания
            (непрерывная цепь моментов различения). Эти три потока создают видимость времени, «я» и
            мира.</p>
        <p><em>Vyavacchinna</em> — «отсечённый» — означает, что Равана более не поддерживает эту
            преемственность своим цеплянием. Он не «останавливает» процессы, но перестаёт придавать
            им реальность.</p>
        <p>Его <em>darśana</em> — «видение» — теперь свободно от веры в непрерывность. Он видит
            явления такими, каковы они есть: мимолётными, лишёнными сущности, не связанными
            причинной цепью.</p>
        <p>Этот разрыв преображает его видение: сознание становится готовым к восприятию Дхармы,
            пребывающей вне всякой преемственности.<a href="#ref-59" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-60"><sup>60</sup> <strong>«Свободный от причинных воззрений
                тиртхиков»</strong> (<em>sarva-kāraṇa-tīrthya-vyapeta</em>)
            — указывает на отказ от поиска внешних причин мира.</p>
        <p>Тиртхики объясняют существование через первопричины, лежащие вне сознания: Бога-творца,
            первоматерию, атомы или время.</p>
        <p>С точки зрения <strong>Ланкаватары</strong>, такие воззрения — заблуждение, ибо мир не
            имеет внешней опоры: всё видимое есть лишь проявления ума (<em>citta-mātra</em>), не
            существующие независимо от сознания.</p>
        <p><em>Vyapeta</em> — «ушедший за пределы» — Равана более не цепляется за идеи
            первопричин. Он не отвергает их логически, но просто видит их ненужность. И в этом
            заключён переход от философствования к йогическому видению: вопросы о «начале» теряют
            смысл, когда ум покоится в том, что есть.<a href="#ref-60" class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-61"><sup>61</sup> <strong>«Вошедший во внутреннюю сферу
                Татхагатагарбхи»</strong> (<em>tathāgatagarbha-adhyātma-samāpanna</em>)
            — прямое постижение природы ума, в которой уже присутствует полнота качеств
            Будды.</p>
        <p><em>Tathāgatagarbha</em> — «зародыш Татхагаты» — чистая природа сознания, не затронутая
            омрачениями, хотя и скрытая ими.</p>
        <p><em>Adhyātma</em> — «внутреннее» — означает, что Равана обнаружил источник Дхармы в
            глубинной основе собственного ума.</p>
        <p><em>Buddhabhūmi</em> — «ступень Будды» — уровень, на котором эта природа проявляется без
            помех. Постижение их внутренней природы знаменует осознавание того, что разделение между
            «обычным существом» и «Буддой» — иллюзия, порождённая
            омрачениями.<a href="#ref-61" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-62"><sup>62</sup> <strong>«Утвердившийся в мудрости
                Будды»</strong> (<em>sthita-buddha-buddhi</em>)
            — разум йогина устойчиво пребывает в постижении природы мудрости Будды.</p>
        <p><em>Buddhi</em> — здесь высшая познавательная способность, свободная от сомнений,
            колебаний и понятийных искажений.</p>
        <p><em>Sthita</em> — «утвердившийся» — означает, что прозрение Раваны перестало быть
            мимолётным и стало его естественным состоянием.</p>
        <p>Это постижение того, что его собственный ум — по природе уже мудрость Будды (<em>tathāgatagarbha</em>),
            лишь временно скрытая омрачениями (вспоминаем Уттаратантру Майтреи).</p>
        <p>Так завершается подготовку Раваны: его разум устойчиво направлен на постижение той же
            таковости (<em>tathatā</em>), что полностью реализована Учителем, — и потому он готов
            воспринять Дхарму в её полной глубине.<a href="#ref-62" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-63"><sup>63</sup> <strong>«Звук, постигаемый лишь
                внутренне»</strong> (<em>adhyātma-vedya-śabda</em>)
            — наставление возникло непосредственно в сознании Раваны.</p>
        <p><em>Gagana</em> — «небо» — в буддийской символике означает природу ума, лишённую помех,
            подобно чистому пространству. Звук, «раздающийся из неба», — выражение мудрости,
            возникающей из самой чистоты ума.</p>
        <p><em>Adhyātma-vedya</em> — «постигаемое внутренне» — Равана воспринял это
            наставление как прямое узнавание истины.</p>
        <p>Этот момент знаменует переход к <em>pratyātma-vedya</em> — личному постижению.<a href="#ref-63"
                                                                               class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-64"><sup>64</sup> <strong>«Воззрение полного
                прекращения»</strong>
            (<em>uccheda-dṛṣṭi</em>) — одна из двух фундаментальных крайностей, отвергаемых Буддой;
            другая — «воззрение вечности» (<em>śāśvata-dṛṣṭi</em>).</p>
        <p><em>Uccheda</em> — «полное прекращение» — нигилистическое воззрение, согласно
            которому после разрушения формы ничто не остаётся: ни сознания, ни кармы, ни возможности
            пробуждения.</p>
        <p>Эта ошибка возникает, когда йогин, постигая <em>śūnyatā</em>, отрицает не только
            собственную неизменную сущность явлений, но и само условное проявление ума. Он принимает <em>śūnyatā</em>
            за ничто.</p>
        <p>Такое воззрение становится новой опорой (<em>āśraya</em>) для цепляния — уже не за
            «бытие» (<em>bhāva</em>), а за «небытие» (<em>abhāva</em>). Оно не ведёт к освобождению,
            но удерживает ум в сансаре под видом отречения.</p>
        <p>Истинное видение — срединный путь (<em>madhyamā-pratipad</em>): дхармы по природе не
            имеют сущности (<em>niḥsvabhāva</em>), но не лишены условного проявления (<em>saṃvṛti-satya</em>).
            Именно это видит Равана — и потому избегает обеих крайностей.<a href="#ref-64"
                                                                            class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-65"><sup>65</sup> <strong>«Оставив ум (citta), разум (manas)
                и различающее сознание
                (manovijñāna)»</strong> — указание на необходимость выйти за пределы трёх уровней
            сансарического сознания.</p>
        <p><em>Citta</em> (ум) — здесь означает <em>алайя-виджняну</em>, хранилище кармических
            отпечатков (<em>васан</em>), из которого возникает иллюзия непрерывности.</p>
        <p><em>Manas</em> (<em>манас</em>) — седьмое сознание (<em>kliṣṭa-manas</em>), цепляющееся
            за <em>алайю</em> как за «я» и порождающее двойственность.</p>
        <p><em>Manovijñāna</em> (<em>мановиджняна</em>) — шестое сознание, функция которого —
            понятийное различение (<em>vikalpa</em>): оно проецирует разделение на «субъект» и
            «объект», «внутреннее» и «внешнее».</p>
        <p>«Оставить» их — значит перестать принимать их проявления за реальность.<a href="#ref-65"
                                                                                     class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-66"><sup>66</sup> <strong>«Созерцание, падшее в сферу
                шраваков, пратьекабудд и
                тиртхиков»</strong> — состояния, в которых сохраняется тонкая
            привязанность к опорам.</p>
        <p><em>Patita</em> — «упавшее» — означает, что созерцание, несмотря на глубину,
            останавливается на промежуточном уровне и не достигает недвойственности.</p>
        <p>Шраваки и пратьекабудды стремятся к освобождению через отрицание «я», но продолжают
            принимать дхармы как реальные или стремятся к личному покою (<em>nirvāṇa</em>), а не к
            буддовости ради всех существ. Их путь — личное упокоение, а не сострадательное
            пробуждение.</p>
        <p>Тиртхики ищут истину во внешних началах — Боге, душе, материи — и потому их созерцание
            опирается на двойственность с самого начала.</p>
        <p><em>Gocara</em> — «сфера» или «область деятельности» — здесь означает "поле" или "пастбище"
            ума, где он и пасётся. Будда предостерегает, что даже глубокое самадхи
            становится «падшим», если оно не выходит за пределы всех опор.</p>
        <p>Путь махайогина — без пристанища: он не ищет покоя для себя, но остаётся в мире ради
            блага всех существ, не цепляясь ни за освобождение, ни за созерцание — это <em>apratiṣṭhita-nirvāṇa</em>
            (нирвана без опоры).<a href="#ref-66" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-67"><sup>67</sup> <strong>«Не следует быть поглощённым
                историями и преданиями»</strong> (<em>ākhyāyiketihāsa-rata</em>)
            — предостережение против привязанности к описательному эпическому знанию.</p>
        <p><em>Ākhyāyika</em> — повествования, легенды, дидактические рассказы; <em>itihāsa</em> —
            эпические сказания, представляемые как «так оно и было». Такие тексты, даже если они
            мудры, укореняют ум во времени, пространстве и личной истории — сфере <em>vikalpa</em>,
            где всё расчленено на «героя», «событие» и «смысл».</p>
        <p><em>Rata</em> — «поглощённый» — указывает на наслаждение самим процессом слушания,
            которое отвлекает от непосредственного видения.</p>
        <p>Для Раваны — существа, чья фигура уже вплетена в мифы, — это наставление особенно важно:
            истинное пробуждение требует отказа от отождествления с любой историей, включая
            собственную.</p>
        <p>Путь йогина — не в том, чтобы знать больше историй, а в том, чтобы пребывать там, где
            истории исчезают: в недвойственности (<em>advaya</em>), за пределами прошлого,
            настоящего и будущего.<a href="#ref-67" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-68"><sup>68</sup> <strong>«Не следует держаться воззрения о
            независимой собственной природе»</strong>
            (<em>svabhāva-dṛṣṭi</em>) — указание на корневое заблуждение, лежащее в основе всей
            сансары.</p>
        <p><em>Svabhāva</em> — «собственное бытие» — это убеждённость в том, что явления существуют
            сами по себе, независимо от условий и ума.</p>
        <p>С точки зрения <strong><em>Ланкаватары</em></strong>, такое воззрение — иллюзия, порождённая
            различением (<em>vikalpa</em>): ум принимает временные проявления за
            устойчивые сущности.</p>
        <p>Если дхармы обладали бы <em>svabhāva</em>, они не могли бы возникать, меняться или
            исчезать — и потому не могли бы быть проявлениями ума.</p>
        <p>Отказ от <em>svabhāva-dṛṣṭi</em> — фундамент постижения, которое постепенно углубляется
            на пути бодхисаттвы: ум перестаёт цепляться за формы и видит их такими, каковы они есть
            — лишёнными собственной сущности (<em>niḥsvabhāva</em>), но проявляющимися условно (<em>saṃvṛti-satya</em>).<a
                href="#ref-68" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-69"><sup>69</sup> <strong>«Не следует подпадать под
                опьянение властью и
                господством»</strong> (<em>rājādhipatya-mada</em>) — предостережение против цепляния
            за социальный статус как за реальность.</p>
        <p><em>Mada</em> — «опьянение» — это высокомерие, возникающее, когда ум принимает внешние
            знаки власти за подтверждение собственной значимости.</p>
        <p>Для Раваны, владыки Ланки и повелителя ракшасов, это искушение особенно велико: его
            могущество — видимое, осязаемое, воспетое в преданиях.</p>
        <p>Но с точки зрения <strong><em>Ланкаватары</em></strong>, всякая власть — условна (<em>pratītya-samutpanna</em>),
            ибо основана на двойственности: «я — правитель», «они — подданные». Такое разделение
            укрепляет <em>manas</em>, цепляющийся за «я», и разрушает состояние <em>avikalpa</em> —
            недвойственного пребывания.</p>
        <p>Истинное господство — в независимости от всех форм признания, включая царский титул.
            Отказ от <em>mada</em> — условие того, чтобы власть не порабощала того, кто ею обладает.<a
                href="#ref-69" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-70"><sup>70</sup> <strong>«Не следует ограничиваться
                медитацией шести дхьян»</strong>
            (<em>ṣaḍdhyānādidhyāyin</em>) — даже глубокие состояния
            сосредоточения не являются освобождением, если в них сохраняется разделение на
            «созерцающего» и «созерцаемое».</p>
        <p>Шесть <em>дхьян</em> — ступени умственного успокоения, общие для многих традиций, включая
            учения тиртхиков. Они приносят покой, ясность и блаженство, но не устраняют корень
            двойственности.</p>
        <p>Практикующий может принять эти состояния за <em>nirvāṇa</em>, не замечая, что «я,
            пребывающий в <em>дхьяне</em>» — всё ещё иллюзия, поддерживаемая <em>manas</em>.</p>
        <p>Такое цепляние препятствует освобождению: пока сохраняется «субъект опыта», ум остаётся в
            тонкой двойственности.</p>
        <p>Путь йогина в том, чтобы распознавать природу ума во всех состояниях — до, во время и
            после <em>дхьяны</em>.</p>
        <p>Истинная йога Махаяны — прекращение самого различения, которое создаёт и «<em>дхьяну</em>»,
            и «обычное состояние».<a href="#ref-70" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-71"><sup>71</sup> <strong>«Искусный в тончайшем повороте
                сознания»</strong> (<em>sūkṣma-abhivijñāna-parāvṛtti-kuśala</em>)
            — качество бодхисаттвы, способного распознавать и устранять тончайшие движения
            двойственности в самом акте познания.</p>
        <p><em>Sūkṣma</em> — «тонкий» — означает, что речь идёт о первичном импульсе двойственности,
            возникающем до всякой концепции, раньше грубых мыслей и эмоций.</p>
        <p><em>Abhivijñāna</em> — «различающее знание» — обозначает акт осознавания в его самом
            начале, до разделения на «познающего» и «познаваемое».</p>
        <p><em>Parāvṛtti</em> — «поворот» — это разворот ума от проекции внешнего мира к
            распознаванию своей собственной природы.</p>
        <p><em>Kuśala</em> — «искусный» — указывает на мастерство бодхисаттв в этой практике: они
            способны уловить момент возникновения двойственности и повернуть ум к его истинной
            природе до того, как <em>викальпа</em> (построение понятий) затвердеет в воззрение.</p>
        <p>Эта искусность отличается от полной <em>āśraya-parāvṛtti</em> (поворота основы), которая
            происходит при буддовости, когда восемь виджнян окончательно трансформируются в
            мудрости. Здесь речь о практике, ведущей к этой цели: бодхисаттва тренируется
            распознавать и устранять тончайшую двойственность, подготавливая ум к окончательному
            повороту.<a href="#ref-71" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-72"><sup>72</sup> <strong>«Цепляются за «я» и признаки
                видимого»</strong> (<em>ātmagrāha-dṛśya-lakṣaṇa-abhiniviṣṭa</em>)
            — принимают «я» и видимые объекты как действительно существующие и самодостаточные.<a
                href="#ref-72" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-73"><sup>73</sup> <strong>«Следуют за элементами, их
                качествами и веществами»</strong>
            (<em>bhūta-guṇa-dravya-anucārin</em>) — верят в материальные вещества и качества
            как в нечто объективно существующее.<a href="#ref-73" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-74"><sup>74</sup> <strong>«Укоренены в воззрениях,
                порождённых неведением»</strong> (<em>avidyā-pratyaya-dṛṣṭi-abhiniveśa</em>)
            — мировоззрение основано на неведении и поддерживает дальнейшие заблуждения.<a
                href="#ref-74" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-75"><sup>75</sup> <strong>«Рассеяны представлением, что
                шуньята "возникает"»</strong>
            (<em>śūnyatā-utpāda-vikṣipta</em>) — запутались в понимании возникновения из шуньяты:
            ошибочно полагают, что <em>śūnyatā</em> — это субстанция, которая возникает и исчезает,
            а не отсутствие неизменной сущности всех явлений.<a href="#ref-75" class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-76"><sup>76</sup> <strong>«Погружены в различения»</strong>
            (<em>vikalpābhiniviṣṭa</em>)
            — их мышление создаёт искусственные понятия и они принимают свои умственные построения
            за реальность.<a href="#ref-76" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-77"><sup>77</sup> <strong>«Упали в двойственность
                обозначаемого и признака»</strong>
            (<em>lakṣya-lakṣaṇa-patita</em>) — они разделяют реальность на «объект» и «его признаки»
            и принимают оба за действительно существующие, не понимая их умственной природы.<a
                href="#ref-77" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-78"><sup>78</sup> <strong>«Ведёт к обретению вселенской
                формы»</strong> (<em>viśvarūpa-gati-prāpaka</em>)
            — способность постигать все формы как проявления ума, лишённые собственной сущности и
            независимого существования.<a href="#ref-78" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-79"><sup>79</sup> <strong>«Пробуждает непосредственное
                постижение собственного
                пути»</strong> (<em>svapratyātmagati-bodhaka</em>) — прямое знание пути, а не
            принятые на веру учения или логические построения.<a href="#ref-79"
                                                                 class="citation-back">↩</a></p>
        <p class="my-2" id="citation-80"><sup>80</sup> <strong>«Ведёт к обретению высших ступеней
                (<em>bhūmi</em>)»</strong> (<em>viśeṣa-bhava-upapatti</em>)
            — здесь освоение всё более глубоких уровней реализации, соответствующих стадиям
            бодхисаттв (<em>bhūmi</em>).<a href="#ref-80" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-81"><sup>81</sup> <strong>«Прекращает волны различных
                виджнян»</strong> (<em>vividhavijñāna-taraṅga-vyāvartaka</em>)
            — устраняет волны различных <em>виджнян</em>, приводя сознание к естественной
            неподвижности, в которой прекращаются колебания восприятия, памяти, различения и
            кармических отпечатков.<a href="#ref-81" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-82"><sup>82</sup> <strong>«Кто открывает внутреннюю область
                личного постижения»</strong> (<em>pratyātma-gati-gocara-udbhāvaka</em>) — Будда
            не передаёт учение как внешний
            объект. Он раскрывает то, что уже присутствует в самом йогине.</p>
        <p><em>Pratyātma</em> — «личное», «непосредственное» — это постижение недоступно через
            логику, авторитет или заимствование.</p>
        <p><em>Gati</em> — «путь» — здесь это не движение от точки к точке, подразумевается способ
            пребывания ума в недвойственном постижении.</p>
        <p><em>Gocara</em> — «область» — поле опыта, в котором нет разделения на познающего и
            познаваемое.</p>
        <p><em>Udbhāvaka</em> — «раскрывающий» — подчёркивает, что Будда не создаёт эту сферу, Он
            устраняет завесы, мешающие её видению.</p>
        <p>Таким образом, истинная Дхарма распознаётся, а не сообщается.<a href="#ref-82"
                                                                           class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-83"><sup>83</sup> <strong>«Чьё знание свободно от
                сотворённого и чудесных
                проявлений»</strong> (<em>nairmita-nairmāṇika-vyapeta adhigama-buddhiḥ</em>) —
            указывает, что подлинное постижение не связано с созданием форм, состояний или эффектов.
        </p>
        <p><em>Nirmita</em> — «сотворённое» — всё, что искусственно сконструировано умом: понятия,
            явления, даже священные образы, принимаемые за предмет постижения.</p>
        <p><em>Nairmāṇika</em> — «чудесные проявления» — относится к магическим проявлениям, которые
            в индийской традиции часто считались признаком духовной силы.</p>
        <p><em>Vyapeta</em> — «свободный от» — подчёркивает, что знание Татхагаты не опирается ни на
            создание, ни на проявление.</p>
        <p>Это — <em>adhigama-buddhi</em>: непосредственное постижение, возникающее без опоры на
            произведённое или проявленное.</p>
        <p>Это знание достигает совершенства при <em>āśraya-parāvṛtti</em> (повороте основы сознания
            при буддовости): когда ум окончательно освобождается от привязанности к «сотворённому»,
            становится видимым то, что изначально присутствует, но не нуждается в оформлении.</p>
        <p>Пробуждение потому не принадлежит сфере чудес, даже священных и почитаемых. Это — прямое
            внутреннее знание, не требующее подтверждения через явление, действие или форму.<a
                href="#ref-83" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-84"><sup>84</sup> Термин <strong>«йогин»</strong> в
            <strong><em>Ланкаватаре</em></strong> применяется
            только к тому, кто достиг постижения (<em>adhigama</em>).</p>
        <p>Мудрость, о которой идёт речь, не передаётся заранее и не усваивается через обучение
            (<em>śruta-jñāna</em>) или размышление (<em>cintā-jñāna</em>).</p>
        <p>Она раскрывается единственно в момент непосредственного постижения, при вхождении во
            врата самадхи (<em>samādhi-mukha</em>), когда умолкает умственное различение (<em>vikalpa</em>)
            и становится доступной внутренняя область личного постижения
            (<em>pratyātma-gati</em>).<a href="#ref-84" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-85"><sup>85</sup> <strong>«Свободный от признаков
                действия»</strong> (<em>kriyā-lakṣaṇa-vinivṛtta</em>)
            означает, что Татхагата не обладает характеристиками деятеля (<em>kartṛ</em>): у него
            нет намерения, усилия, цели или идеи «я действую».</p>
        <p>Его проявление — не действие в обыденном смысле (<em>kriyā</em>), это спонтанное
            раскрытие мудрости (<em>anābhoga</em> — безусильность), не порождающее кармических
            отпечатков.<a href="#ref-85" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-86"><sup>86</sup> <strong>«Не колеблется в нерождённости
                дхарм»</strong> (<em>anutpattika-dharma-kṣānti</em>)
            — означает отсутствие внутреннего смятения, когда раскрывается: ни одна дхарма никогда
            не возникала как самостоятельная сущность.</p>
        <p><em>Kṣānti</em> здесь — не психологическая устойчивость и не усилие по удержанию
            состояния. Это — естественная невозмутимость, в которой нет страха, ожидания или
            сомнения относительно бытия дхарм.</p>
        <p>В этом распознавании нет различия между видящим и видимым и нерождённость
            (<em>anutpāda</em>) здесь — это само прекращение двойственности. Достижение <em>anutpattika-dharma-kṣānti</em>
            — признак 8-й бхуми (<em>Ачала</em>, «Недвижимая») или выше, где бодхисаттва становится
            <em>anivartanīya</em> (необратимым). Будда видит, что Равана достиг этого постижения,
            что делает его готовым к глубокой Дхарме.<a href="#ref-86" class="citation-back">↩</a>
        </p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-87"><sup>87</sup> <strong>«Взор мудрости»</strong>
            (<em>buddhi-cakṣus</em>) — видение
            без разделения на субъект и объект, в отличие от плотского ока/обычного зрения
            (<em>māṃsa-cakṣus</em>).<a href="#ref-87" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-88"><sup>88</sup> <strong>«Великий смех»</strong>
            (<em>mahāhāsa</em>) — спонтанное
            выражение недвойственной радости, в которой нет страх перед шуньятой.<a
                href="#ref-88" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-89"><sup>89</sup> <strong>«Лучи из пор тела»</strong> —
            символ всепроникающего
            присутствия мудрости, не ограниченной физической формой.<a href="#ref-89"
                                                                       class="citation-back">↩</a></p>
        <p class="my-2" id="citation-90"><sup>90</sup> <strong>«Собственное внутреннее
                благородное знание»</strong> (<em>sva-pratyātma-ārya-jñāna</em>)
            — знание, недоступное через слова, раскрывающееся только в непосредственном опыте (<em>pratyātma-vedya</em>).<a
                href="#ref-90" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-91"><sup>91</sup> <strong>«Размышлял»</strong>
            (<em>anuvicintayamāna</em>) — прямое восприятие йогического пути Раваны без посредничества
            понятий.<a href="#ref-91" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-92"><sup>92</sup> <strong>«Смятение ума»</strong>
            (<em>citta-vibhrama</em>) — состояние недоумения,
            переживание потрясения основ веры, когда внешнее проявление Будды
            (смех) противоречит представлению о Нём как о бесстрастном.<a href="#ref-92"
                                                                          class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-93"><sup>93</sup> <strong>«Цепляются за буквальный
                смысл»</strong>
            (<em>yathāruta-artha-abhiniviṣṭa</em>) —
            принимают звуки слов за истину, не видя, что слова — лишь
            указатели.<a href="#ref-93" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-94"><sup>94</sup> <em>Traikālya</em> — «трёх времён» (прошлое, настоящее, будущее); указывает, что ложные воззрения (<em>dṛṣṭi</em>) одинаковы во все эпохи, и ответ Будды актуален всегда. <em>Svaparobhayārtha</em> — «ради блага себя, других и обоих»: три мотива действия в буддийской этике — <em>svārtha</em> (ради себя), <em>parārtha</em> (ради других) и <em>ubhayārtha</em> (ради обоих). Последний — недвойственный мотив бoдхисаттвы, где разделение между «я» и «другой» преодолено, и благо себя и других нераздельно, как вода и волны единого океана.<a href="#ref-94" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-95"><sup>95</sup> <strong>«Два вопроса»</strong> —
            «Существуют ли дхармы?» и «Не существуют ли
            дхармы?» — корень всех философских заблуждений. Их отвержение —
            вход в недвойственность.<a href="#ref-95" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-96"><sup>96</sup> <strong>«Преобразивший опору различающего
                мышления»</strong>
            (<em>parāvṛtta-vikalpāśraya</em>) — состояние поворота основы
            (<em>āśraya-parāvṛtti</em>), в котором исчезает действие <em>vikalpa</em>.<a
                href="#ref-96" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-97"><sup>97</sup> <strong>«Проницательная мудрость
                различения»</strong>
            (<em>pravicaya-buddhi</em>) —
            мудрость, распознающая, что за двойственностью нет никакой сущности,
            есть только игра ума. Она ведёт к прямому видению таковости.<a href="#ref-97"
                                                                           class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-98"><sup>98</sup> <strong>«Ступени Ачала, Садхумати,
                Дхармамегха»</strong> —
            8-я, 9-я и 10-я земли/степени/ступени/бхуми бодхисаттвы, где проявляются соответственно:
            непоколебимость в недвойственности,
            совершенное мастерство в проповеди,
            излияние мудрости, как дождя, на всех существ.<a href="#ref-98"
                                                             class="citation-back">↩</a></p>
        <p class="my-2" id="citation-99"><sup>99</sup> <strong>Маха-ратна-падма-вимана</strong>
            (<em>mahā-ratna-padma-vimāna</em>) —
            «великий драгоценный чертог на лотосе» (<em>вимана</em> — также «дворец»
            или «небесная колесница»). Это высшая форма проявления пробуждённого ума.
            Описание <strong>мандалы</strong>, структуры, характерной для тантрической визуализации,
            но здесь представленной в <strong>сутрическом контексте</strong>.<a href="#ref-99"
                                                                                class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-100"><sup>100</sup> <strong>«Множество [своих] тел, явленных
                силой твоего собственного ума»</strong> —
            эта фраза имеет множество параллелей с другими текстами Махаяны:
            <em>Праджняпарамитой</em> (<strong><em>Хридая-сутра</em></strong>),
            <strong><em>Аватамсака-сутрой</em></strong>, а также с более поздними текстами тантры
            (структура мандалы, визуализация идама и его окружения).
            Если парадокс «ни единства, ни множественности» в <strong><em>Хридае</em></strong> и
            «один содержит всё, всё содержит одно, один в одном, всё во всём» в
            <strong><em>Аватамсаке</em></strong> выражается
            текстуально, то в <strong><em>Ланкаватаре</em></strong> это выражено образно-визуально:
            Равана видит это напрямую
            — множество тел, но нет "одного я"; один ум, но нет "единой субстанции". Этот парадокс
            разрешается только в прямом постижении шуньяты. Лотосы символизируют изначальную чистоту
            ума, не затронутую «грязью» измышлений (<em>vikalpa</em>): как лотос растёт из ила, но
            не загрязнён им, так и ум проявляется в сансаре, но по природе (<em>prakṛti</em>) сияюще
            чист.<a href="#ref-100" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-101"><sup>101</sup> <strong>«Узришь лики, взирающие друг на
                друга»</strong>
            (<em>anyonyavakramukhanirīkṣaṇa</em>) — если описывать в стиле тантры, то можно сказать,
            что Равана видит себя как центральное божество мандалы, окружённое множественными
            проявлениями самого себя. Это зримый символ недвойственности, где "я" растворяется в
            бесконечном взаимном созерцании; единое сознание проявляется как бесчисленные формы,
            каждая из которых одновременно субъект и объект созерцания. Предположу, что
            <strong><em>Ланкаватара</em></strong>
            — мост между сутрической философией и тантрической практикой визуализации.<a
                href="#ref-101" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-102"><sup>102</sup> Эта сфера опыта непостижима уму, который
            связан понятиями: её раскрывает тот, кто пребывает на ступени, вызывающей изумление
            свободой от кармической цепи «причина-следствие» благодаря спонтанному выражению
            сострадания, которое не имеет намерения, усилия или следа, через разнообразие форм.<a
                href="#ref-102" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-103"><sup>103</sup> <strong>«Многообразие форм ступени
                Татхагаты»</strong> — ступень Татхагаты (<em>tathāgata-bhūmi</em>) представляет
            собой состояние полного пробуждения, в котором проявление и шуньята нераздельны. Его
            сострадание естественно выражается в бесчисленных проявлениях ради блага всех существ.
            «Ступень» скорее всего, употреблена по аналогии со ступенями бодхисаттв, хотя то и
            принципиально иное бытие.<a href="#ref-103" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-104"><sup>104</sup> Брахма, Индра и Упендра (Вишну)
            символизируют три столпа сансары: творение, власть и сохранение космического порядка.
            Просветление Татхагаты превосходит их все — оно лежит вне самой структуры сансары, даже
            в её божественной форме.<a href="#ref-104" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-105"><sup>105</sup> <strong>Подъём на высоту семи
                пальм</strong> (<em>sapta tāla</em>) — возможно, символ полного превосхождения мира
            желаний (<em>kāmadhātu</em>). Подношение Раваны не ограничено ни одной сферой сансары:
            оно исходит из состояния, свободного от привязанности ко всем уровням условного
            существования.<a href="#ref-105" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-106"><sup>106</sup> <strong>Сцена подношения Раваны</strong>
            выражает его утверждённость на высших бхуми. Подъём с первой вершины, взлёт на высоту
            семи пальм и восседание на второй лотосовой вершине описывают выход за пределы мира
            желаний (<em>kāmadhātu</em>) и вхождение в сферу чистой земли (<em>buddha-kṣetra</em>),
            возникающей из преображённого ума. Подношения проявляются как естественное выражение
            ума, в котором устранено различие между дарящим, даром и получающим. Сам вопрос Раваны
            рождается из прозрения, и потому получает отклик Татхагаты в форме улыбки и
            дозволения.<a href="#ref-106" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-107"><sup>107</sup> <strong>«Пара дхарм»</strong> (<em>dharmadvayam</em>)
            — два аспекта условного опыта: дхарма («благое») и адхарма («неблагое»), которые оба
            подлежат оставлению.<a href="#ref-107" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-108"><sup>108</sup> Цитата отсылает к <strong><em>Ваджраччхедика-сутре</em></strong>:
            «Дхармы должны быть оставлены, тем более не-дхармы». Равана углубляет парадокс: если
            дхармы лишены самосущности, то что именно оставлять?<a href="#ref-108"
                                                                   class="citation-back">↩</a></p>
        <p class="my-2" id="citation-109"><sup>109</sup> <em>vikalpa-lakṣaṇa</em><a href="#ref-109"
                                                                                    class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-110"><sup>110</sup> <em>vikalpa-svabhāva-abhāva</em><a
                href="#ref-110" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-111"><sup>111</sup> <em>abhautika-bhautikā</em><a
                href="#ref-111" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-112"><sup>112</sup> <em>ālaya-vijñāna-aparijñānāt</em><a
                href="#ref-112" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-113"><sup>113</sup> <em>aviśeṣa-lakṣaṇā</em><a href="#ref-113"
                                                                                    class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-114"><sup>114</sup> <strong>«Видение волосков»</strong> (<em>keśoṇḍuka</em>)
            — классическая метафора иллюзорного восприятия: как человек с больными глазами видит в
            чистом пространстве несуществующие пятна, так и ум, не познавший <em>Алайя-виджняну</em>,
            принимает свои проекции за реальность.<a href="#ref-114" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-115"><sup>115</sup> <em>aśuddha-kṣaya-jñāna-viṣayiṇām</em><a
                href="#ref-115" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-116"><sup>116</sup> Суть вопроса: если все явления — продукт
            различающего мышления (<em>vikalpa</em>), лишённого собственной природы, то «оставление»
            не может быть актом отбрасывания объектов. Оно возможно только как узнавание того, что
            сам механизм различения изначально пуст (<em>śūnya</em>). Это не является достижением
            нового состояния, это прекращение веры в то, что дхармы существуют как объекты,
            подлежащие оставлению.<a href="#ref-116" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-117"><sup>117</sup> <strong>«Сфера различений невежд»</strong>
            (<em>bāla-vikalpa-gocara</em>) — здесь различение между дхармой и не-дхармой условно
            функционирует; кувшины, пламя, ветви воспринимаются как реально различные.<a
                href="#ref-117" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-118"><sup>118</sup> <strong>«Постижение благородного
                знания»</strong> (<em>Ārya-jñāna-adhigama</em>) — здесь различия не видны (<em>na
                darśana</em>), распознаётся единая природа всех явлений.<a href="#ref-118"
                                                                           class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-119"><sup>119</sup> Метафоры огня и семени показывают, что
            единая природа (огонь, семя) — это <strong><em>парамартха-сатья</em></strong>
            (абсолютная истина); а многообразие проявлений (пламя, ветви) — это <strong><em>самврити-сатья</em></strong>
            (условная истина), возникающее в зависимости от условий (<em>indhanavaśāt</em> — «в силу
            топлива»).<a href="#ref-119" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-120"><sup>120</sup> <em>pratyātma-gati-lakṣaṇa</em><a
                href="#ref-120" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-121"><sup>121</sup> <em>prativikalpa-pravṛtti</em><a
                href="#ref-121" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-122"><sup>122</sup> <strong>«Причины, качества и
                субстанции»</strong> (<em>kāraṇa-guṇa-dravya</em>) — категории философии <em>вайшешики</em>
            и <em>ньяи</em>, согласно которым явления реально существуют как субстанции
            (<em>dravya</em>), обладающие качествами (<em>guṇa</em>) и порождаемые причинами (<em>kāraṇa</em>).
            <strong><em>Ланкаватара</em></strong> отвергает это овеществление: дхармы — не
            субстанции, а проекции ума (<em>svacitta-dṛśya</em>), лишённые собственного тела (<em>alabdha-śarīra</em>).<a
                href="#ref-122" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-123"><sup>123</sup>
            <em>svacitta-dṛśya-dharmatā-abhiniveśāt</em><a href="#ref-123"
                                                           class="citation-back">↩</a></p>
        <p class="my-2" id="citation-124"><sup>124</sup> <strong>«Уже отброшены»</strong> —
            оставление не есть действие, а результат видения (<em>vidarśana</em>). Как только
            распознано, что кувшин — лишь проекция (<em>svacitta-dṛśya</em>), он теряет статус
            «реального объекта» и тем самым «отброшен». Итак, если всё — <em>vikalpa</em>, и <em>vikalpa</em>
            пуст, как оставить? Оставить нужно не сами <em>vikalpa</em> (различения), а веру (<em>abhiniveśa</em>)
            в то, что они — внешняя реальность (<em>dharmatā</em>) через видение (<em>vidarśana</em>),
            что они — <em>svacitta-dṛśya</em> (лишь воспринимаемое умом). Как только узнано — они уже
            отброшены (<em>prahīṇa bhavanti</em>).<a href="#ref-124" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-125"><sup>125</sup> <em>alabdha-ātmaka</em><a href="#ref-125" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-126"><sup>126</sup> <em>lakṣaṇa-vikalpa-apracāra</em><a href="#ref-126" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-127"><sup>127</sup> <em>ahetuka</em><a href="#ref-127" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-128"><sup>128</sup> <strong>«Не-возникновение»</strong> (<em>Apravṛtti</em>) — или «отсутствие проявления». Термин указывает на статус объектов, которые, подобно «рогам зайца», никогда не возникали и не имеют причин для проявления. Их не-возникновение видится парадоксально (<em>bhūta-abhūtataḥ</em>): как существующее (<em>bhūta</em>) — поскольку мы говорим о нём, мыслим его; как несуществующее (<em>abhūta</em>) — поскольку его нет реально. Этот парадокс указывает на абсурдность попыток схватить (<em>grahaṇa</em>) такие "объекты" сознанием (<em>vijñāna</em>) или мыслить их через признаки (<em>lakṣaṇa</em>). Подобно рогам зайца, все проявления различающего мышления (<em>vikalpa-bhāva</em>) лишены сущности и не могут быть схвачены.<a href="#ref-128" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-129"><sup>129</sup> <em>na lakṣaṇataḥ kalpyāḥ</em><a href="#ref-129" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-130"><sup>130</sup> <em>saṃvyavahārārtham</em><a href="#ref-130" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-131"><sup>131</sup> <em>agrahaṇataḥ vijñānena</em><a href="#ref-131" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-132"><sup>132</sup> <em>vikalpa-bhāva</em><a href="#ref-132" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-133"><sup>133</sup> <strong><em>Visarjita</em></strong> — буквально «отпущенный» или «разрешённый». В контексте: прежние Будды ответили на этот вопрос (как делает сейчас Будда Шакьямуни), но сам вопрос порождён различением (<em>vikalpa</em>), и потому ответ не может быть окончательным в рамках различающего мышления. Истинное "разрешение" — выйти за пределы самого вопроса.<a href="#ref-133" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-134"><sup>134</sup> <strong>«Размножествление понятий», «мыслительное разрастание»</strong> (<em>prapañca</em>) — самовоспроизводящийся поток ума, который, опираясь на различение (<em>vikalpa</em>), делит неделимое на противоположности — «я» и «не-я», «внутри» и «вне», «благо» и «неблаго» — и поддерживает это разделение через речь, имена и признаки. Этот поток создаёт видимость связного постигаемого мира, но при внимательном рассмотрении обнаруживает внутренние противоречия: одному и тому же объекту приписываются взаимоисключающие свойства — существующий и преходящий, единый и составной, реальный и иллюзорный. Так <em>prapañca</em> сама себя разрушает, обнажая свою безосновательность.<a href="#ref-134" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-135"><sup>135</sup> <strong>«Не полагают и не полагаемы»</strong> (<em>na kalpante na kalpyante</em>) — <em>kalpana</em> (от корня √<strong>kḷp</strong>) означает умственное действие установления чего-либо как реально существующего: например, «я» как субъект, «мир» как объект, «дхармы» как сущности. Татхагаты не осуществляют такого действия — они не принимают проекции ума за реальность, и их самих нельзя принять за объект подобного полагания, поскольку они лишены природы, доступной для различающего мышления (<em>vikalpa</em>).<a href="#ref-135" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-136"><sup>136</sup> Смотри примечание 7 в <strong><em>Ваджрачхедике</em></strong>.<a href="#ref-136" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-137"><sup>137</sup> <strong>«Вышедший за пределы различения и его отсутствия»</strong> (<em>vikalpāvikalpāgatena</em>) — имеется в виду, что освобождение не есть ни пребывание в различающем мышлении (<em>vikalpa</em>), ни фиксация/"замораживание ума" на его отсутствии (<em>avikalpa</em>). Истинное положение — вне обеих крайностей, ибо даже «отсутствие различения» становятся оковами, если ум цепляется за него как за достижение.<a href="#ref-137" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-138"><sup>138</sup> <strong>«Фигуры на стене»</strong> (<em>bhittikhacitavigraha</em>) — метафора полной неподвижности сансары: всё «движение» — лишь иллюзия, порождённая умом, который придаёт жизнь мёртвым изображениям.<a href="#ref-138" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-139"><sup>139</sup> <strong>«Магическое изваяние»</strong> (<em>nirmitapratima</em>) — указание на автоматизм сансары: мир действует, как одушевлённая кукла, но в нём нет ни деятеля, ни живой души (<em>атмана</em>).<a href="#ref-139" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-140"><sup>140</sup> <strong><em>sva-vikalpa-grahaṇa</em></strong>. Здесь <em>grahaṇa</em> — «схватывание, захватывание» от корня √<strong>grah</strong> — «хватать, брать, захватывать». Ум «хватает» различения, принимает их за реальные объекты, держится за них и пленяется ими.<a href="#ref-140" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-141"><sup>141</sup> <strong>«Питают различения»</strong> (<em>vikalpayanti puṣṇanti</em>) — ум не только создаёт различения, но и поддерживает их вниманием и верой, делая их «реальными». Оставление — прекращение этого питания.<a href="#ref-141" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-142"><sup>142</sup> <strong>«Покой»</strong> — обозначение единонаправленности (<em>ekāgratā</em>) — не концентрация на объекте, а возвращение ума к источнику, где различения затихают, и раскрывается Татхагатагарбха.<a href="#ref-142" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">


        <p class="my-2" id="citation-143"><sup>143</sup> <strong>«Цветок в небе»</strong> (<em>khapuṣpa</em>) — традиционный буддийский образ невозможного, иллюзорного, не имеющего основы в реальности. Используется для обозначения явлений, лишённых собственной природы.<a href="#ref-143" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-144"><sup>144</sup> <strong>«Майя»</strong> (<em>māyā</em>) — иллюзия, мираж; в буддийском контексте — метафора нереальности, обманчивости обычного восприятия явлений, которые кажутся существующими, но лишены устойчивой сущности.<a href="#ref-144" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-145"><sup>145</sup> <strong>«Лишены [природы] ума и сознания»</strong> (<em>cittavijñānavarjitāḥ</em>) — указание на то, что дхармы не являются ни объектами ума (<em>citta</em>), ни содержанием различающего сознания (<em>vijñāna</em>); они не подлежат двойственному постижению.<a href="#ref-145" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-146"><sup>146</sup> <strong>Употребление слова «всегда»</strong> (<em>sadā</em>) критически важно для метафизики <strong><em>Ланкаватары</em></strong>. Оно указывает на то, что призрачность и отсутствие собственной сущности — это не временное состояние мира и не субъективная ошибка отдельного человека. Это фундаментальный закон: не существует и никогда не существовало «объективного» или «реального» мира, который предшествовал бы этому «сну». Мир является проекцией сознания изначально и в каждый момент своего существования. Признание того, что природа сна присуща миру всегда, позволяет Будде проявлять Сострадание: Он входит в этот сон как активный участник, ни на мгновение не забывая о его иллюзорности.<a href="#ref-146" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-147"><sup>147</sup> Этот стих раскрывает парадокс Дхармакаи. Её природа подобна майе и сновидению, она лишена любых устойчивых признаков, потому не поддаётся описанию через утвердительные суждения. Всякое приписывание Дхармакае каких-либо характеристик ограничивает её безмерность, превращая недвойственное в объект различения. Подлинное восхваление (<em>stava</em>) Татхагаты не может быть словесным, оно необходимо становится йогическим созерцанием, вхождением в недвойственное постижение шуньяты.<br><br>
            Утверждение «не-возникновение есть истинное возникновение» (<em>anutpādaḥ sa saṃbhavaḥ</em>) выражает ключевые положения: а) дхармы лишены собственной сущности (<em>niḥsvabhāva</em>) — они не существуют независимо, а проявляются в зависимости от движения ума; б) с точки зрения высшей истины (<em>paramārtha</em>), — всё видимое (<em>dṛśya</em>) есть то, что проявляется умом-как-таковым (<em>svacitta</em>); принятие этого за реальное рождение — признак омрачения (<em>kleśa</em>); в) истинное «присутствие» дхармы — это постижение её изначального не-рождения. Так реальность видится тому, чей ум свободен от цепляния. Постижение <em>шуньяты</em> и есть высшее постижение подлинной природы.<a href="#ref-147" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-148"><sup>148</sup> <em>Pratyātmagatigocaram</em> — область личного непосредственного постижения и здесь Будда обещает не просто «рассказать факты», а указать направление, в котором Махамати должен направить свой ум, чтобы <em>увидеть</em> реальность самостоятельно.<a href="#ref-148" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-149"><sup>149</sup> <strong>«Различающее рассуждение»</strong> (<em>tarka</em>) и <strong>«заблуждение»</strong> (<em>bhrānti</em>): Махамати начинает с фундаментального вопроса о механике мысли. <em>Тарка</em> понимается как линейное логическое мышление, зуд классифицирующего ума, умствование, что само по себе является формой «заблуждения» (<em>бхранти</em>), так как делит реальность на субъект и объект.<a href="#ref-149" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-150"><sup>150</sup> <strong>«Отсутствие [ментальных] образов»</strong> (<em>nirābhāsa</em>): Высшая стадия медитации, когда ум не проецирует картинки, формы и понятия, «зеркало» ума перестает отражать что-либо, кроме своей собственной природы. Это состояние «без-отражения». Махамати спрашивает о технологии достижения состояния, где нет проекции форм.<a href="#ref-150" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-151"><sup>151</sup> <strong>«Тройственное бытие»</strong> (<em>tribhava</em>): Мир желаний (<em>кама</em>), мир форм (<em>рупа</em>) и мир без форм (<em>арупа</em>). Махамати интересуется тем, кто способен «разрушить» эту структуру сансары.<a href="#ref-151" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-152"><sup>152</sup> <strong>«Отвращение от видимого»</strong> (<em>dṛśyān nivartate</em>): Ключевой термин йогачары. Это процесс, когда сознание перестает течь «наружу» к объектам и возвращается к своей чистой основе, это поворот (<em>парāвритти</em>) потока сознания от объектов к основе. Махамати просит описать механизм этого «обратного хода».<a href="#ref-152" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-153"><sup>153</sup> <strong>«Роды и без рода»</strong> (<em>gotra-agotra</em>): Этот вопрос Махамати рассматривается как запрос о духовной предрасположенности. <em>Готра</em> — это «семья» или «генетический код» пробуждения. Махамати спрашивает, почему одни существа обладают потенциалом Будды, а другие (<em>аготра</em>) кажутся лишенными его.<a href="#ref-153" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-154"><sup>154</sup> <strong>«Мгновенность распада»</strong> (<em>kṣaṇa-bhaṅga</em>) — «мгновенный распад»; доктрина, которую <strong><em>Ланкаватара-сутра</em></strong> критикует как недостаточно глубокую. В то время как школы хинаяны (в частности, <em>вайбхашика</em>) используют идею моментального разрушения дхарм для отрицания постоянства «Я», <strong><em>Ланкаватара</em></strong> видит в этом скрытый реализм: чтобы нечто «разрушилось», оно должно сначала «возникнуть». С позиции недвойственности Будда указывает, что дхармы не «мгновенны», они изначально не рождены (<em>анутапада</em>). Если объект — лишь проекция ума (<em>svacitta-dṛśya</em>), то у него нет даже мгновения реального бытия, чтобы претерпеть распад. Таким образом, идея мгновенности отвергается ради более радикального постижения: мир не «быстро меняется», он никогда не возникал вне различающего ума.<a href="#ref-154" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-155"><sup>155</sup> <strong>Нирихика</strong> (<em>nirīhika</em>) — «безусильность» или «отсутствие воления». Термин указывает на то, что мир функционирует без внешнего творца-управителя (<em>īśvara</em>) и без внутреннего субъекта-деятеля (<em>kartṛ</em>). Космос в <strong><em>Ланкаватаре</em></strong> описывается как процесс, лишенный волевого импульса; он разворачивается спонтанно (<em>sahaja</em>), подобно магической иллюзии или отражению. Постижение мира как <em>nirīhika</em> означает осознание того, что за потоком явлений не стоит никакая основополагающая воля. Для бодхисаттвы это становится основой безусильного действия (<em>анабхисамскара</em>): когда устраняется иллюзия «деятеля», поступки перестают порождать кармическую связь, превращаясь в свободную игру мудрости.<a href="#ref-155" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-156"><sup>156</sup> <strong>«Изложение без букв»</strong> (<em>nirakṣara</em>): Прямая отсылка к знаменитому утверждению <strong><em>Ланкаватары</em></strong> о том, что истинная Дхарма не может быть передана буквами (<em>акшара</em>). Махамати просит разрешить парадокс: как Будда учит, если истина безмолвна?<a href="#ref-156" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-157"><sup>157</sup> <strong>«Два вида отсутствия "Я"»</strong> (<em>nairātmyaṃ dvidhā</em>): Махамати имеет в виду отсутствие «Я» в личности (<em>пудгала-найратмья</em>) и отсутствие «Я» дхарм (<em>дхарма-найратмья</em>).<a href="#ref-157" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-158"><sup>158</sup> <strong>«Очищение познаваемого»</strong> (<em>jñeya-viśuddhi</em>) — этот вопрос касается устранение <em>джнея-авараны</em> (<em>jñeya-āvaraṇa</em>), или «завесы познаваемого». В отличие от «завесы клеш» (<em>клеша-аварана</em>), порождающей личное страдание, завеса познаваемого — это тончайшее интеллектуальное препятствие, мешающее всеведению Будды. Она заключается в самой привычке ума разделять реальность на «познающего» и «познаваемое», наделяя объекты ложной плотностью и внешней независимостью. Фраза <em>jñeyaṃ viśudhyati</em> означает, что когда ум перестает проецировать двойственность, «объект» познания очищается от наслоений понятийной ложности. В этот момент мир перестает восприниматься как совокупность внешних явлений и раскрывается в своей истинной природе как <em>татхата</em> (таковость), что делает возможным достижение недвойственного всеведения.<a href="#ref-158" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-159"><sup>159</sup> <strong>«Лишь именование»</strong>
            (<em>prajñapti-mātra</em>) — технический термин, указывающий на условный статус всех
            явлений. Согласно <strong><em>Ланкаватаре</em></strong>, весь проявленный мир возникает, когда ум,
            движимый привычками различения, наделяет именами (<em>nāma</em>) фрагменты потока опыта. Эти имена создают видимость устойчивых, независимых объектов, хотя на самом деле за ними нет никакой, имеющей некую сущность, основы. Постичь, что всё есть «лишь именование», значит увидеть, что мы взаимодействуем не с реальными явлениями, а с проекциями собственного ума, зафиксированными в языке. Это осознание ослабляет цепляние к формам, так как йогин распознаёт, что за именами скрывается таковость (<em>tathatā</em>) — недвойственная, не имеющая границ, признаков или определений. Иными словами: мир — это игра имён, лишённая автора.<a href="#ref-159" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-160"><sup>160</sup> <strong>«Иччхантика»</strong>
            (<em>icchantika</em>) — термин, обозначающий существ, кажущихся лишёнными потенциала
            пробуждения. В <strong><em>Ланкаватаре</em></strong> этот статус рассматривается диалектически:<br>
            <em>Иччхантики по омрачению</em> — те, чьи корни благого (<em>kuśala-mūla</em>) истощены вследствие тяжких проступков против Дхармы. Их ум настолько омрачён, что они не проявляют стремления к освобождению. В относительном смысле их называют «лишёнными семени Будды» (<em>bodhīccha</em>).<br>
            <em>Иччхантики по состраданию</em> — великие бодхисаттвы, давшие обет не входить в окончательную нирвану, пока не освободится последнее существо. Поскольку круговорот бесконечен, они добровольно остаются вне угасания — не из-за кармы, а из безмерного сострадания.<br>
            Однако на абсолютном уровне никто не лишён природы Будды. Учение о «безнадёжности» — искусное средство (<em>upāya</em>), применяемое Татхагатой, чтобы пробудить страх перед омрачениями у тех, кто погружён в пороки. В свете учения о <em>Татхагатагарбхе</em> — изначальной чистоте ума — состояние <em>иччхантики</em> не является вечным. Оно длится лишь до тех пор, пока действуют механизмы различения (<em>vikalpa</em>), скрывающие подлинную природу сознания. Таким образом, стать <em>иччхантикой</em> — значит оказаться в крайности: либо в самозамкнутости омрачения, либо в самоотдаче сострадания. Но даже в этой крайности природа Будды остаётся нетронутой, подобно золоту, покрытому грязью.<a href="#ref-160" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-161"><sup>161</sup> <strong>«Знаки и признаки в уходах и рождениях»</strong> — это вопрос о механизме кармической преемственности. Под «знаком» (<em>liṅga</em>) понимается скрытая потенция — семя в <em>Алайя-виджняне</em>, определяющее направление следующего перерождения. Под «признаком» (<em>lakṣaṇa</em>) — внешние проявления: форма тела, речь, поведение, в которых отражаются прошлые склонности и закладываются условия будущего. В свете йогачары, однако, нет никакого «существа», переходящего из жизни в жизнь. Есть лишь поток отпечатков (<em>vāsanā-prabandha</em>), который, подобно магниту, притягивается к соответствующим условиям. Постичь эти «знаки» — значит увидеть, как ум связывает мгновения опыта в иллюзию непрерывного «я», хотя на самом деле между смертью и рождением нет ни субъекта, ни преемника — только движение различения (<em>vikalpa</em>), лишённое опоры.<a href="#ref-161" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-162"><sup>162</sup> <strong>Риши Диргхатапас</strong>
            (<em>Dīrghatapas/Dīrghatamas</em>) — мудрец, упоминаемый в <strong><em>Ригведе;</em></strong> его имя
            буквально означает «долгий мрак». В контексте <strong><em>Ланкаватары</em></strong> его упоминание
            поднимает вопрос: откуда берётся знание? Диргхатапас символизирует предел прозрения в рамках небуддийских путей: он, будучи слепым, «видел» истину внутренним взором и провозглашал, что «Истина едина, но мудрецы называют её разными именами». Однако Будда указывает, что даже такие озарения являются лишь проявлением собственного ума (<em>svacitta-dṛśya</em>). Даже величайший мистический опыт, если он не сопровождается поворотом основы (<em>āśraya-parāvṛtti</em>), остаётся внутри круга различения (<em>vikalpa</em>). Тот, кто принимает своё видение за окончательную истину, не выходит за пределы воображаемой природы (<em>parikalpita-svabhāva</em>).<a href="#ref-162" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-163"><sup>163</sup> <strong>Формы миров</strong> — лотос, лев, Шриватса — указывают на бесконечное разнообразие земель Будд (<em>buddhakṣetra</em>), возникающих как проявление чистого ума. Форма мира не предопределена внешней необходимостью. Она зависит от благословенной силы (<em>adhiṣṭhāna</em>) Татхагаты, пребывающего в том мире, и кармы существ, его населяющих. Лотос символизирует мир, рождённый из чистоты и потенциала пробуждения. Лев — мир, где проявляется неодолимая мощь Дхармы. Шриватса — бесконечный узел, выражающий неразрывную взаимозависимость всех дхарм.<a href="#ref-163" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-164"><sup>164</sup> <strong>Будды Мудрости Таковости</strong> (<em>tathatā-jñāna-buddha</em>) соответствуют Дхармакае. Это — сама таковость реальности, лишённая признаков и различений. Здесь нет ни личности, ни познающего — только недвойственное постижение, доступное лишь в сфере личного прозрения (<em>pratyātmagati</em>), когда исчезает разделение на «я» и «мир».<br>
            <strong>Будды созревания заслуг</strong> (<em>vipākaja-buddha</em>) соответствуют Самбхогакае — Телу Блаженства. Это — величественное проявление Татхагаты в чистых мирах, возникшее как плод (<em>vipāka</em>) бесконечного накопления мудрости и заслуг. Эта форма доступна восприятию бодхисаттв, пребывающих в глубоком самадхи.<br>
            <strong>Будды воплощения</strong> (<em>nirmāṇika-buddha</em>) соответствуют Нирманакае — Телу Проявлений. Это — исторические Будды (как Шакьямуни) или нирманы, которые Татхагата являет в мирах желаний. Они принимают облик, речь и действия, соответствующие уму существ, чтобы вести их к пробуждению.<a href="#ref-164" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-165"><sup>165</sup> <strong>Сиддханта</strong>
            (<em>siddhānta</em>) в <strong><em>Ланкаватаре</em></strong> имеет два аспекта: личное постижение
            (<em>pratyātma-siddhānta</em>) — недвойственное, невыразимое, свободное от признаков и рассудочного мышления; изложение Учения (<em>deśanā-siddhānta</em>) — словесное указание, приспособленное к слушателям. Тиртхики также выдвигают свои «сиддханты» (атомы, время и т.д.), но Будда подчёркивает: истинная <em>сиддханта</em> — там, где все воззрения прекращаются. Держаться за неё как за мнение — значит утратить её.<a href="#ref-165" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-166"><sup>166</sup> <strong>«Лес из мужчин и женщин»</strong> — здесь, вероятно, символ двойственности восприятия. В адах такой лес — ловушка для страстных: иллюзорные образы желанных тел на деревьях из листьев-лезвий ведут к мучениям. В чистых землях — знак чудесного рождения, лишённого биологической кармы. Махамати указывает в вопросе, что одна и та же форма становится адом или раем в зависимости от состояния сознания. Ни привлекательность, ни ужас не принадлежат объекту — они суть проявление собственного ума (<em>svacitta-dṛśya</em>).<a href="#ref-166" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-167"><sup>167</sup> В этом эпизоде Будда применяет особый педагогический приём — священную иронию. Махамати, выступая от лица интеллектуала, стремится охватить Дхарму рассудочным знанием: его вопросы охватывают всё — от природы Нирваны до количества атомов в горчичном зерне. Это — попытка ума построить полную систему различений, где каждому явлению дано имя, мера и место.<br>
            Ответ Будды двоякий:<br>
            <em>Доведение до абсурда (шлоки 71—80):</em> Он зеркально отражает эту страсть к детализации, предлагая вопросы ещё более мелочные и бессмысленные — сколько атомов в брови? Сколько пал весит гора Меру? Тем самым Он показывает: накопление информации не есть постижение. Ум может бесконечно дробить явления, но так и не коснётся их недвойственной природы.<br>
            <em>Смешение уровней (шлоки 81—90):</em> Будда намеренно ставит в один ряд вопросы о Таковости и о «вкусности еды», о Пустоте и о половом влечении. Это — шоковая терапия для рассудка: разрушается иерархия «духовного» и «мирского», ибо для омрачённого ума любое различение — преграда, даже то, что касается Будды.<a href="#ref-167" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-168"><sup>168</sup> <strong>Bhramarā</strong> (букв.
            «пчелы») — в контексте <strong><em>Ланкаватара-сутры</em></strong> данный термин используется
            метафорически. Он указывает на «блуждающие умы» или живых существ, чье сознание из-за беспокойства и привязанностей постоянно «перелетает» от одного чувственного объекта к другому, подобно пчелам на лугу. Корень слова <strong>bhram</strong> («блуждать», «вращаться», «ошибаться») подчеркивает сансарическую природу такого сознания, вовлеченного в круговорот перерождений и ложных различений.<a href="#ref-168" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-169"><sup>169</sup> <strong><em>svapratyātmāryajñāna</em></strong> — «самопостигаемая мудрость благородных».<a href="#ref-169" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-170"><sup>170</sup> Этот список не утверждает и не отрицает понятия. Будда показывает, что каждое из них, взятое как объект цепляния, становится преградой. Только когда ум не зацепляется ни за X, ни за не-X, раскрывается недвойственная реальность.<a href="#ref-170" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-171"><sup>171</sup> <strong>«Прекращение потока»</strong> (<em>prabandha-nirodha</em>) — прекращение непрерывной цепи сцепленных состояний, в которой один акт различения мгновенно порождает следующий под влиянием кармических отпечатков. Этот поток — инерция сансарического мышления, при которой ум функционирует как автоматический «проектор», воспроизводящий прошлые галлюцинации. При <em>prabandha-nirodha</em> прекращается не сам ум, а его автоматизм — то есть признак деятельности (<em>karma-lakṣaṇa</em>), а не признак рождения (<em>jāti-lakṣaṇa</em>).<a href="#ref-171" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-172"><sup>172</sup> <strong>«Прекращение признаков»</strong> (<em>lakṣaṇa-nirodha</em>) — прекращение привязанности к признакам (<em>lakṣaṇa</em>), через которые ум строит видимость внешнего мира. Обычное сознание воспринимает готовые объекты, «построенные» умом, а не поток различений. Эти признаки — умозрительные метки, придающие зыбким проекциям ума иллюзию плотности и самостоятельности. Освобождаясь от цепляния за признаки, ум перестаёт наделять опыт характеристиками формы, цвета или ценности. Если <em>prabandha-nirodha</em> — это остановка инерции временного потока, то <em>lakṣaṇa-nirodha</em> — растворение воображаемой плотности мира. Это состояние напрямую ведёт к Без-образности (<em>nirābhāsa</em>) — высшей мудрости, в которой сознание отражает Таковость (<em>tathatā</em>) без наслоения различений (<em>vikalpa</em>).<a href="#ref-172" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-173"><sup>173</sup> <strong>«Возникновение потока»</strong> (<em>prabandha-utpāda</em>) — непрерывное воспроизводство двойственных состояний сознания, порождающее иллюзию временной непрерывности. Это динамический процесс, в котором различающий ум (<em>mano-vijñāna</em>) беспрестанно проецирует кармические отпечатки (<em>vāsanā</em>), под воздействием «ветров» внешних объектов, превращая семена <em>Алайи-виджняны</em> в волны восприятия. Так возникает самоподдерживающаяся инерция, создающая ложное чувство длительности «я» и «мира». Для бодхисаттвы этот поток — танец различений, подлежащий осознанию и прекращению через йогу.<a href="#ref-173" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-174"><sup>174</sup> <strong>«Возникновение
                признака»</strong> (<em>lakṣaṇa-utpāda</em>) — акт умозрительного выделения,
            посредством которого ум наделяет недвойственный поток опыта конкретными свойствами —
            формой, цветом, плотностью — и закрепляет их через имена. Это — первичный механизм
            иллюзии, превращающий Таковость (<em>tathatā</em>) в мир разделённых и «плотных»
            объектов, доступных для схватывания (<em>grahaṇa</em>) как «внешних». В
            <strong><em>Ланкаватаре</em></strong> это считается основой омрачения (<em>āvaraṇa</em>): если <em>prabandha-utpāda</em> создаёт иллюзию времени, то <em>lakṣaṇa-utpāda</em> — иллюзию пространственной плотности. Этот процесс подлежит прямому постижению.<a href="#ref-174" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-175"><sup>175</sup> <strong>«Пребывание потока»</strong> (<em>prabandha-sthiti</em>) — динамическая устойчивость различающего сознания (<em>mano-vijñāna</em>), обеспечивающая непрерывность иллюзорного опыта. Это — инерция сансары, благодаря которой поток кармических проекций самоподдерживающе длится, создавая для омрачённого ума иллюзию временной непрерывности «я» и мира.<a href="#ref-175" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-176"><sup>176</sup> <strong>«Пребывание признака»</strong> (<em>lakṣaṇa-sthiti</em>) — фаза умозрительного закрепления, в которой ум наделяет мгновенные проекции статусом длительного и плотного существования. Это — умственный клей, превращающий поток «воспринимаемого собственным умом» (<em>svacitta-dṛśya</em>) в устойчивый мир объектов, что делает их доступными для схватывания (<em>grahaṇa</em>) и порождает страдание.<a href="#ref-176" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-177"><sup>177</sup> <strong>«Признак деятельности»</strong>, <strong>«признак развёртывания»</strong> (<em>pravṛtti-lakṣaṇa</em>) — характеристика активного развёртывания сознания в режиме различения. В отличие от <em>karma-lakṣaṇa</em> — накопления кармических отпечатков (<em>vāsanā</em>), <em>pravṛtti-lakṣaṇa</em> описывает сам процесс проявления различений (<em>vikalpa</em>) из скрытых семян. Это — деятельный аспект ума, который может быть прекращён (<em>nirodha</em>) без уничтожения <em>jāti-lakṣaṇa</em> — признака возникновения.<a href="#ref-177" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-178"><sup>178</sup> <strong>«Признак действия»</strong> (<em>karma-lakṣaṇa</em>) — аспект сознания, посредством которого деятельность различения превращается в новые кармические отпечатки. Это механизм накопления, создающий условия для будущих циклов развёртывания. Именно этот признак прекращается при <em>prabandha-nirodha</em> (прекращение потока), а не <em>jāti-lakṣaṇa</em> (признак рождения).<a href="#ref-178" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-179"><sup>179</sup> <strong>«Признак рождения»</strong> или <strong>«возникновения»</strong> (<em>jāti-lakṣaṇa</em>) — аспект сознания, отвечающий за проявление нового цикла опыта — как тела, так и мира, воспринимаемого умом. Этот признак завершает механизм сансарического воспроизводства, описывая, как кармические отпечатки проявляются в виде «видимого собственным умом» (<em>svacitta-dṛśya</em>). Постижение его иллюзорности и изначальной нерождённости (<em>anutpāda</em>) всех явлений устраняет этот признак при повороте основы (<em>āśraya-parāvṛtti</em>).<a href="#ref-179" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-180"><sup>180</sup> <strong>«Сознание проявления»</strong> (<em>khyāti-vijñāna</em>) — аспект сознания, мгновенно и одновременно проецирующий весь феноменальный мир. Подобно зеркалу, оно являет образы тела, объектов и вместилища из скрытых отпечатков <em>Алайи-виджняны</em>. Это — первая кажимость (<em>ābhāsa</em>), предшествующая всякому рассуждению, и создающая сцену сансарического опыта.<a href="#ref-180" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-181"><sup>181</sup> <strong>«Сознание различения объектов»</strong> (<em>vastu-prativikalpa-vijñāna</em>) — рассудочный аспект ума, который анализирует, классифицирует и наделяет именами образы, проявленные сознанием проявления (<em>khyāti-vijñāna</em>). Оно работает последовательно, превращая единый поток «видимого собственным умом» (<em>svacitta-dṛśya</em>) в мир разделённых и плотных объектов. Это сознание является главным инструментом умозрительного различения (<em>vikalpa</em>), поддерживающий иллюзию внешней плотности.<a href="#ref-181" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-182"><sup>182</sup> <strong>«Непостижимое преобразование
                отпечатков»</strong> (<em>acintya-vāsanā-pariṇāma</em>) — процесс, посредством
            которого скрытые склонности (<em>vāsanā</em>), накопленные в <em>Алайя-виджняне</em>,
            созревают (<em>pariṇāma</em>) и проявляются как мир, тело и обстоятельства. Он
            называется «непостижимым» (<em>acintya</em>), потому что не поддаётся рассудочному
            мышлению (<em>tarka</em>), протекает вне осознанного контроля, и не может быть
            воспринят как объект. В <strong><em>Ланкаватаре</em></strong> этот термин указывает, что весь проявленный мир не является внешней реальностью, это динамика самого ума, движимая безначальными привычками различения. Бодхисаттва, пребывая в йоге видимого собственным умом (<em>svacitta-dṛśya-yoga</em>), не видит «проекции», а распознаёт единый поток, в котором нет разделения на внутреннее и внешнее.<a href="#ref-182" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-183"><sup>183</sup> <strong>«Различение объектов»</strong> (<em>viṣaya-vikalpa</em>) — умозрительное разделение, посредством которого ум наделяет свои проекции статусом внешних и независимых предметов; умственное искажение, создающее иллюзию объективного мира, противопоставленного субъекту, и служащее опорой для возникновения привязанностей и омрачений. Прекращение <em>viṣaya-vikalpa</em> является необходимым условием для возвращения ума в состояние недвойственного покоя.<a href="#ref-183" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-184"><sup>184</sup> <strong>«Отпечатки безначального понятийного многообразия»</strong> (<em>anādi-prapañca-vāsanā</em>) — накопленная в сознании вязкая инерция, заставляющая ум проецировать «воспринимаемое собственным умом» в виде сложной сети имён и различений. Эта словесная раздутость (<em>prapañca</em>) создаёт ложную множественность там, где существует лишь единая Таковость (<em>tathatā</em>). Освобождение от этих отпечатков означает переход от рассудочного знания к прямому постижению «только-ума» (<em>cittamātra</em>).<a href="#ref-184" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-185"><sup>185</sup> <strong>«Ложное воображение»</strong> (<em>abhūta-parikalpa</em>) — фундаментальный механизм ума, создающий иллюзию разделения на субъект и объект. Это процесс воображения того, чего нет, который превращает недвойственную Таковость (<em>tathatā</em>) в мир множественных форм. Постижение этого процесса как лишённого собственной природы позволяет йогину остановить словесную раздутость (<em>prapañca</em>) и вернуться к прямому постижению «видимого собственным умом» (<em>svacitta-dṛśya</em>).<a href="#ref-185" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-186"><sup>186</sup> <em>lakṣaṇa-nirodha</em><a href="#ref-186" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-187"><sup>187</sup> <em>prabandha-nirodha</em><a href="#ref-187" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-188"><sup>188</sup> <strong>«Отпечатки пагубной косности безначального понятийного разрастания»</strong> (<em>anādi-prapañca-dauṣṭhulya-vāsanā</em>) — пагубная косность/порочность/тяжесть/вязкость/предрасположенность сознания, обусловленная безначальной привычкой к раздроблению «воспринимаемого собственным умом» через язык и умозрительные различения. Эта дурная предрасположенность заставляет ум воспринимать мир как вязкую сеть внешних и плотных объектов, блокируя доступ к лёгкости и ясности недвойственной мудрости.<a href="#ref-188" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-189"><sup>189</sup> <strong>«Воспринимаемое собственным умом»</strong> (<em>svacitta-dṛśya</em>) — положение, согласно которому весь проявленный мир является не чем-то «внешним», а проекцией самого ума. Постижение всего опыта как <em>svacitta-dṛśya</em> устраняет иллюзию разделённости между наблюдаемым и наблюдателем, позволяя йогину увидеть в каждом объекте лишь прозрачную игру ума, свободную от ложной плотности и независимого бытия.<a href="#ref-189" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-190"><sup>190</sup> <strong>«Сознание проявлений»</strong>, <strong>«активные сознания»</strong> (<em>pravṛtti-vijñāna</em>) — совокупность семи активных уровней сознания: пяти чувственных, ментального и сознания-<em>манас</em>, которые развёртываются из <em>Алайи-виджняны</em> под воздействием объектов, воспринимаемых как внешние. Это динамический аспект ума, ответственный за понятийное различение и создание иллюзии двойственности.<a href="#ref-190" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-191"><sup>191</sup> <em>jāti-lakṣaṇa</em><a href="#ref-191" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-192"><sup>192</sup> <strong>«Признак собственного рождения»</strong> (<em>svajāti-lakṣaṇa</em>) — характеристика, согласно которой каждое явление кажется возникающим в силу собственной природы. Если <em>jāti-lakṣaṇa</em> (признак рождения) описывает сам факт проявления мира из ума, то <em>svajāti-lakṣaṇa</em> указывает, как ум наделяет каждую проекцию иллюзией уникальности и независимости. Когда этот термин применяется к <em>Алайе-виджняне</em>, её <em>svajāti-lakṣaṇa</em> не прекращается на уровне относительной истины, пока не произойдёт <em>поворот основы</em> (<em>āśraya-parāvṛtti</em>). До этого <em>поворота</em> <em>Алайя</em> функционирует как относительно устойчивый поток на уровне условной истины (<em>saṃvṛti-satya</em>), обеспечивающий непрерывность кармических отпечатков и проявление активных сознаний. Однако её кажущаяся устойчивость — это не абсолютная реальность (<em>paramārtha</em>), а лишь тончайший уровень различений «воспринимаемого собственным умом» (<em>svacitta-dṛśya</em>), который подлежит преображению при <em>parāvṛtti</em> (повороте основы).<a href="#ref-192" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-193"><sup>193</sup> <em>karma-lakṣaṇa</em><a href="#ref-193" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-194"><sup>194</sup> <strong>«Первоматерия, Дух, Ишвара, Время, Атомы»</strong> — перечисление основных метафизических понятий небуддийских школ: <em>pradhāna</em> — санкхья, <em>puruṣa</em> — санкхья, <em>Īśvara</em> — шиваизм/веданта, <em>kāla</em> — адживика, <em>aṇu</em> — вайшешика.<a href="#ref-194" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-195"><sup>195</sup> В <strong><em>Ланкаватаре</em></strong> термин
            <em>svabhāva</em> используется двояко: первые шесть видов описывают ложные природы, приписываемые явлениям различающим умом; седьмая (<em>niṣpatti-svabhāva</em>) — истинную природу, Таковость (<em>tathatā</em>), раскрывающуюся при отсечении всех ложных проекций.<a href="#ref-195" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-196"><sup>196</sup> <em>samudaya-svabhāva</em> — «природа совокупного возникновения»; заблуждение, будто явления реально возникают как сумма своих частей или условий.<a href="#ref-196" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-197"><sup>197</sup> <em>bhāva-svabhāva</em> — «природа бытия»; ложная вера в то, что объекты обладают независимым существованием.<a href="#ref-197" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-198"><sup>198</sup> <em>lakṣaṇa-svabhāva</em> — «природа признаков»; убеждённость в том, что характеристики объектов (цвет, форма) принадлежат самим объектам, а не являются проекциями различающего ума.<a href="#ref-198" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-199"><sup>199</sup> <em>mahābhūta-svabhāva</em> — «природа первоэлементов»; вера в реальность четырёх <em>махабхути</em> (земли, воды, огня, ветра) как материального фундамента мира.<a href="#ref-199" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-200"><sup>200</sup> <em>hetu-svabhāva / pratyaya-svabhāva</em> — «природа причин и условий»; представление о том, что причинно-следственные связи — это реальные внешние законы, а не ментальные привычки упорядочивания опыта.<a href="#ref-200" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-201"><sup>201</sup> <em>niṣpatti-svabhāva</em> — «природа завершённости», «истинная природа»; Таковость (<em>tathatā</em>), раскрывающаяся как изначально присутствующая реальность, когда прекращаются все ложные проекции (<em>parikalpita-svabhāva</em>).<a href="#ref-201" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-202"><sup>202</sup> <strong>Гочары</strong> (<em>gocara</em>) — сферы опыта. Эти термины описывают сферы, в которых обитает сознание, в зависимости от уровня его чистоты.<a href="#ref-202" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-203"><sup>203</sup> <em>citta-gocara</em> — «сфера ума»; обыденный уровень восприятия, где <em>Алайя-виджняна</em> проецирует мир и сама же в нём запутывается.<a href="#ref-203" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-204"><sup>204</sup> <em>jñāna-gocara</em> — «сфера знания»; состояние, где знание сливается с объектом, и исчезает разделение на познающего и познаваемое.<a href="#ref-204" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-205"><sup>205</sup> <em>prajñā-gocara</em> — «сфера мудрости»; уровень бодхисаттвы, который использует праджню для исследования шуньяты и переосмысления признаков.<a href="#ref-205" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-206"><sup>206</sup> <em>dṛṣṭi-dvaya-gocara</em> — «сфера двойственных взглядов»; ограниченное пространство ума, зажатого между крайностями «есть» и «нет».<a href="#ref-206" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-207"><sup>207</sup> <em>dṛṣṭi-dvayātikrānta-gocara</em> — «сфера, превзошедшая двойственность»; пространство свободы, где любые умозрительные оппозиции теряют смысл и опору.<a href="#ref-207" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-208"><sup>208</sup> <em>suta-bhūmi-anukramaṇa-gocara</em> — «сфера последовательного прохождения ступеней»; путь постепенного очищения сознания через слушание Учения и прохождение по ступеням (<em>бхуми</em>) бодхисаттвы.<a href="#ref-208" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-209"><sup>209</sup> <em>tathāgatasya pratyātmagati-gocara</em> — «сфера личного постижения Татхагаты»; высшая истина, невыразимая словами и недоступная рассудку; прямой внутренний опыт (<em>pratyātma</em>), возникающий в результате поворота основы (<em>āśraya-parāvṛtti</em>), когда <em>Алайя-виджняна</em> преображается в Великую Зерцалоподобную Мудрость (<em>mahā-ādarśa-jñāna</em>).<a href="#ref-209" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-210"><sup>210</sup> <strong>«Учение об уничтожении»</strong>
            (<em>ucchedavāda</em>) — в данном контексте Будда относит к нигилизму взгляды тех,
            кто верит в реальный распад <em>скандх</em> и <em>дхату</em>. Согласно
            <strong><em>Ланкаватаре</em></strong>, признание реального (а не условного) исчезновения явлений
            ведет к нигилизму, ибо разрывает преемственность кармы. Истинный Путь основывается на постижении того, что явления никогда не рождались (<em>anutpāda</em>) как независимые сущности, а лишь казались существующими в проекциях собственного ума (<em>svacitta-dṛśya</em>). Только понимание мира как <em>майи</em> позволяет сохранить логику преемственности (<em>saṃtati</em>), не впадая при этом в веру в вечные сущности (<em>śāśvata-vāda</em>).<a href="#ref-210" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-211"><sup>211</sup> <strong>«Отсутствие видения начала»</strong> (<em>Ādyadarśanābhāvāt</em>) — неспособность увидеть, что явления безначальны (<em>anādi</em>). Те, кто ищут «первопричину» — будь то Бог, время или атомы, — совершают умственное заблуждение. Они пытаются найти начало там, где есть лишь безначальный, самоподдерживающийся поток проекций, лишённый как начала, так и конца.<a href="#ref-211" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-212"><sup>212</sup> <strong>«Непрерывный поток»</strong>
            (<em>nairantarya-pravṛtti</em>) — иллюзия связного и длящегося потока опыта. В
            <strong><em>Ланкаватаре</em></strong> подчёркивается, что у явлений мира нет собственной внутренней
            преемственности. Их кажущаяся непрерывность — лишь результат стремительного воспроизводства различающим умом (<em>mano-vijñāna</em>) сходных кармических отпечатков (<em>vāsanā</em>). Постижение отсутствия этой непрерывности позволяет йогину прервать поток сансарического опыта и обнаружить нерождённую природу (<em>anutpāda-svabhāva</em>) «воспринимаемого собственным умом» (<em>svacitta-dṛśya</em>).<a href="#ref-212" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-213"><sup>213</sup> <strong>«Тройное сочетание»</strong> (<em>trisaṃgati</em>) — техническое обозначение <em>sparśa</em>, встречи объекта, органа чувств и сознания. Оппоненты полагают, что до этой встречи сознание «нет», а после неё — «возникает». Будда показывает несостоятельность этой логики: то, чего нет в причинах, не может появиться в результате. Ошибка состоит в принятии сочетания факторов за реальную причину опыта. Если элементы лишены собственной природы (<em>svabhāva</em>), их сумма не способна породить реально существующее сознание. Для бодхисаттвы «встреча факторов» — это не механическая сборка мира из частей, а недвойственный процесс внутри «воспринимаемого собственным умом» (<em>svacitta-dṛśya</em>), подобный майе — кажущийся, но лишённый какой-либо сущностной основы.<a href="#ref-213" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-214"><sup>214</sup> <em>prajñāpāramitā-vihāra</em>.<a href="#ref-214" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-215"><sup>215</sup> <em>anābhoga-caryā</em>.<a href="#ref-215" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-216"><sup>216</sup> <em>svacitta-dṛśya-gocara</em>.<a href="#ref-216" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-217"><sup>217</sup> <em>udadhi-taraṃga-ālayavijñāna-gocara</em>.<a href="#ref-217" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-218"><sup>218</sup> <em>svacitta-dṛśya</em>.<a href="#ref-218" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-219"><sup>219</sup> <strong>«Безначальное понятийное многообразие»</strong> (<em>anādi-prapañca-dauṣṭhulya</em>) — «безначальная косность/инерционность концептуальных/ментальных наслоений/структур/привычек». Это основополагающее обыкновение ума, заставляющее его бесконечно множить иллюзорные категории/идеи и «захватывать» их как реальные. Данная «пагубная инерционность» делает сознание тяжёлым и невосприимчивым к истине, удерживая его в колее привычного различения субъекта и объекта.<a href="#ref-219" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-220"><sup>220</sup> <em>vijñāna-prakṛti-svabhāva</em>.<a href="#ref-220" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-221"><sup>221</sup> <em>vicitra-rūpa-lakṣaṇa-kautūhala</em> — жадное влечение, неутолимое любопытство к многообразию форм и признаков, психологический «зуд» сознания, которое не может оставаться в покое и постоянно ищет, за какой бы объект «зацепиться».<a href="#ref-221" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-222"><sup>222</sup> <em>pravṛtti-vijñāna-taraṃga</em>.<a href="#ref-222" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-223"><sup>223</sup> <strong>«Тело, объекты и мир-вместилище»</strong> (<em>deha-bhoga-pratiṣṭhāna</em>) — триединая структура проявления <em>Алайя-виджняны</em>. Согласно <strong><em>Ланкаватаре</em></strong>, наше физическое присутствие, предметы восприятия и окружающая среда не являются внешними, они представляют собой целостную проекцию ума. Осознание того, что эта триада лишена независимого бытия, позволяет бодхисаттве выйти из-под власти кармической обусловленности и увидеть мир как игру собственного ума.<a href="#ref-223" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-224"><sup>224</sup> <strong>«Признак без-образности»</strong> (<em>nirābhāsa-lakṣaṇa</em>) — состояние сознания, полностью очищенное от проекций идей, образов и представлений. Это переход от «восприятия признаков» (<em>lakṣaṇa-grāha</em>) к прямому постижению (<em>pratyātmāryajñāna</em>), где ум перестаёт строить мир как совокупность внешних объектов. Достижение этого «признака» означает, что завеса интеллектуальных наслоений спала, и сознание пребывает в недвойственной чистоте, не разделяя опыт на зеркало и отражение.<a href="#ref-224" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-225"><sup>225</sup> <strong>«Признак опоры на обеты и благословение всех Будд»</strong> (<em>sarvabuddha-svapraṇidhāna-adhiṣṭhāna-lakṣaṇa</em>) — духовный фактор, обеспечивающий продвижение бодхисаттвы помимо его собственных рассудочных усилий. Этот признак означает, что поток сознания бодхисаттвы входит в согласие с мудростью всех Будд, чья поддержка (<em>adhiṣṭhāna</em>) позволяет ему миновать ловушки цепляния за блаженство самадхи (<em>samādhi-sukha-ābhiniveśa</em>) и не застрять на промежуточных ступенях, достигнув окончательного поворота основы (<em>āśraya-parāvṛtti</em>).<a href="#ref-225" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-226"><sup>226</sup> <strong>«Признак личного благородного постижения»</strong> (<em>pratyātmāryajñāna-gati-lakṣaṇa</em>) — высшая характеристика реализации, при которой Истина постигается напрямую, вне всяких представлений и рассудочных построений. Мнимая граница между познающим и познаваемым растворяется и тогда Таковость (<em>tathatā</em>) неотделима от самого постижения.<a href="#ref-226" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-227"><sup>227</sup> <strong>«Хромой осёл»</strong> (<em>khañjagardabha</em>) — метафора рассудочного знания, опирающегося на умозрительные различения. Будда указывает, что бодхисаттва должен иметь мужество оставить привычную опору на логику и рассудок, как только они выполнили свою подготовительную роль. Дальнейшее продвижение в «сферу личного постижения» (<em>pratyātmagati-gocara</em>) возможно только после отказа от этого «хромого» средства передвижения в пользу спонтанной и недвойственной мудрости.<a href="#ref-227" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-228"><sup>228</sup> <strong>«Тело в самадхи, подобном майе»</strong> (<em>māyopama-samādhi-kāya</em>) — проявление бодхисаттвы, чьё присутствие в мире форм уже не обусловлено кармой, но является прямым продолжением его медитативного опыта. Это — тело-призрак, которое функционирует среди явлений как магический мираж. Оно действенно и сострадательно, но абсолютно лишено собственной природы. Обретение такого «тела» знаменует победу над иллюзией плотности мира и переход к безусильной деятельности (<em>anābhoga</em>) во благо всех существ.<a href="#ref-228" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-229"><sup>229</sup> <strong>«Исследование основы благородной мудрости»</strong> (<em>āryajñāna-vastu-pravicaya</em>) — созерцательное исследование мнимой основы (<em>vastu</em>) воспринимаемых объектов посредством благородной мудрости. В отличие от рассудочного анализа (<em>tarka-pravicaya</em>), это прямое постижение (<em>pratyakṣa-avabodha</em>) отсутствия собственной природы (<em>niḥsvabhāva</em>) всех явлений как проекций ума (<em>svacitta-dṛśya</em>). Устраняя иллюзию внешней плотности (<em>bāhya-ghanatva-vikalpa</em>), йогин лишает ум опоры для цепляния (<em>upādāna-āśraya</em>) и входит в недвойственное пространство Таковости (<em>tathatā</em>).<a href="#ref-229" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-230"><sup>230</sup> <em>parikalpita-svabhāva</em> — воображаемая природа; первая из трёх свабхав (<em>svabhāva-traya</em>). Это ложная природа, приписываемая явлениям различающим умом (<em>vikalpa</em>), который наделяет проекции ума иллюзией независимого бытия. Постижение её отсутствия (<em>abhāva</em>) — ключ к освобождению.<a href="#ref-230" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-231"><sup>231</sup> <em>pudgala-dharma-nairātmya</em> — двоякое отсутствие "я": в личности (<em>pudgala</em>) и в явлениях (<em>dharma</em>). Постижение первого освобождает от <em>клеш</em> (<em>kleśa-āvaraṇa</em>), второго — от завесы познаваемого (<em>jñeya-āvaraṇa</em>), открывая путь к всеведению (<em>sarvajñatā</em>).<a href="#ref-231" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-232"><sup>232</sup> <strong>«Небытие»</strong>,
            <strong>«отсутствие» или «отрицание существования»</strong> (<em>nāstitva</em>) — В
            <strong><em>Ланкаватаре</em></strong> это понятие рассматривается как умственная ловушка — вторая
            из «двух крайностей» (<em>anta-dvaya</em>). Вера в «небытие» — это обратная сторона веры в «бытие». Чтобы нечто «отсутствовало», оно должно было сначала «быть». Но поскольку все явления изначально не рождены (<em>anutpāda</em>) и являются лишь «воспринимаемым собственным умом» (<em>svacitta-dṛśya</em>), то и говорить об их «небытии» так же некорректно, как и об их «бытии». Взгляд «небытия» (<em>nāsti-dṛṣṭi</em>) особенно опасен, так как он может привести к отрицанию закона кармы, плода и самого Пути.<a href="#ref-232" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-233"><sup>233</sup> <strong>«Истощение причины различающего
                рассудка»</strong>, <strong>«исчерпание оснований для рассудочного вывода»</strong> (<em>vikalpa-buddhi-hetu-kṣaya</em>) — различающий рассудок (<em>vikalpa-buddhi</em>), не обнаруживая устойчивой причины (<em>hetu</em>) явлений, заключает: «раз причины нет — явление не существует». Это <em>kṣaya</em> — полное «исчерпание» реальности в умозрительном отрицании. Будда указывает, что само это отрицание — плод того же различающего ума: нигилист видит лишь отсутствие вещей, не постигая Таковость (<em>tathatā</em>). Его рассудок занят уничтожением объектов вместо того, чтобы остановиться самому.<a href="#ref-233" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-234"><sup>234</sup> <strong>Логическая ошибка нигилистов.</strong> Они говорят: «Рогов у зайца нет (это факт), значит и мир такой же несуществующий». Будда критикует их за то, что они строят свое отрицание мира на сравнении с несуществующим объектом. Но если объект (рога зайца) абсолютно невозможен, он не может служить даже примером для отрицания. Чтобы сказать «чего-то нет», нужно сначала иметь идею о том, что это «есть». Но сами "рога зайца" — это идея, заимствованная у "рогов коровы". Таким образом, отрицание паразитирует на утверждении «есть», и обе крайности остаются в ловушке различающего ума (<em>vikalpa</em>).<a href="#ref-234" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-235"><sup>235</sup> <strong>Логическая ошибка реалистов.</strong> Они говорят: «Ладно, рогов зайца нет, но рога коровы-то мы видим! Значит, мир реален». Они разделяют реальность на «абсолютно отсутствующее» и «реально присутствующее». Будда же утверждает, что и то, и другое — лишь <em>vikalpa</em> (различение). Рога коровы так же «пусты» от собственной природы, как и рога зайца. Разница лишь в устойчивости проекции.<a href="#ref-235" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-236"><sup>236</sup> <strong>«Обусловленность через взаимную зависимость»</strong> или <strong>«относительность причинности»</strong> (<em>anyonyāpekṣa-hetutva</em>) — одна идея «взирает» (<em>apekṣā</em>) на другую, чтобы обрести смысл; ключевой логический принцип, вскрывающий ловушку, в которой представления существуют лишь парами, взаимно определяя друг друга. Будда указывает, что «небытие» (<em>nāstitva</em>) всегда тайно опирается на «бытие» (<em>astitva</em>). Когда мы говорим «у зайца нет рогов», мы неявно подтверждаем, что концепция «рога» имеет смысл (заимствованный у коровы). Отрицая одну сторону, ум всё равно остаётся в плену у другой. Если при анализе «бытие» объекта (рога коровы) оказывается лишь проекцией ума, то и «небытие» (отсутствие рогов у зайца) теряет всякую почву. Нельзя построить истинное знание, опираясь на отрицание иллюзии, ибо само это отрицание — такая же умозрительная конструкция, как и утверждение. Истинная мудрость (<em>jñāna</em>) не выбирает между «есть» и «нет». Она распознаёт, что обе эти категории — лишь словесная раздутость (<em>prapañca</em>), и оставляет саму эту двойственность. Этот термин объясняет, почему Будда отвергает как реализм, так и нигилизм.<a href="#ref-236" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-237"><sup>237</sup> <strong>«Исследование вплоть до мельчайших атомов»</strong> (<em>āparamāṇu-pravicayāt</em>) — аналитический метод разрушения кажущейся плотности объектов. Он заключается в мысленном дроблении объекта на составляющие части до тех пор, пока сама идея его независимого существования не исчезнет. Обнаруживая, что при предельном разборе никакой собственной природы (<em>svabhāva</em>) не находится, бодхисаттва убеждается, что мир не имеет внешней опоры и является лишь динамической проекцией ума. Это праджня-анализ (<em>prajñā-pravicaya</em>): вера в плотность объекта доводится до самоопровержения через обнаружение отсутствия предельной частицы. Так различающий ум (<em>vikalpa</em>) лишается опоры и прекращается сам.<a href="#ref-237" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-238"><sup>238</sup> В этом вопросе Махамати проверяет Будду, пытаясь обосновать «небытие» (<em>nāstitva</em>) через факт «прекращения» (<em>apravṛtti</em>) работы ума. Это — утончённая ловушка: попытка утвердить небытие (<em>nāstitva</em>) как логический вывод из факта прекращения деятельности различения. Махамати ищет логическое обоснование для отсутствия объектов через наблюдение за прекращением самого процесса различения, не осознавая, что Таковость (<em>tathatā</em>) не нуждается в подобных соотнесениях и лежит выше любой логики «наличия» или «отсутствия».<a href="#ref-238" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-239"><sup>239</sup> <strong>«Порочность причины»</strong> (<em>viṣama-hetu</em>) — умственное заблуждение, при котором для доказательства истины используются ложные или относительные основания. Будда указывает, что нельзя утвердить «небытие» объектов, опираясь на «бытие» других, так как при тщательном анализе любая опора лишена собственной природы. Эта порочность основания делает рассудочное доказательство невозможным: истина открывается лишь тогда, когда ум оставляет саму привычку утверждать одно через соотнесение с другим.<a href="#ref-239" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-240"><sup>240</sup> В этом фрагменте Будда последовательно устраняет опоры умозрительного различения:<br>
            • Ни тождество, ни различие (<em>anyānanya-vivarjita</em>): субъект и объект различения не утверждаются ни как одно, ни как два. Тем самым снимается возможность как утверждения бытия, так и отрицания через противопоставление.<br>
            • Порочность причины (<em>viṣama-hetu</em>): отрицание одного через другое логически недопустимо, поскольку сам объект сравнения при анализе лишён устойчивой основы (<em>vastu</em>).<br>
            • Снятие различия формы и пространства (<em>ākāśameva rūpam</em>): форма не существует отдельно от пространства и не «располагается» в нём; оба — условные обозначения, возникающие в различении.<br>
            • Исчерпание признака при анализе (<em>aṇutva-lakṣaṇe nāvatiṣṭhante</em>): при аналитическом разложении объект не обнаруживает предельной частицы и утрачивает сам признак формы, переставая быть опорой мышления.<a href="#ref-240" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-241"><sup>241</sup> <em>svacitta-dṛśya-vikalpa-anugama-manasā</em><a href="#ref-241" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-242"><sup>242</sup> <em>svacitta-dṛśya-yoga</em><a href="#ref-242" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-243"><sup>243</sup> <strong>Нишьянда-будда</strong> (<em>niṣyanda-buddha</em>) — «Будда излияния»: аспект Пробуждённого, проявляющийся как спонтанное, естественное излучение (<em>niṣyanda</em>) Таковости (<em>tathatā</em>) в форму. В <strong><em>Ланкаватаре</em></strong> этот термин описывает Будду, который является «истечением» Таковости (<em>tathatā</em>) в сферу форм. Это тот образ Будды, который наставляет бодхисаттв на высоких ступенях пути, служа живым мостом между невыразимой Таковостью и миром умозрительных различений (<em>vikalpa</em>).<a href="#ref-243" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-244"><sup>244</sup> <strong>«Признаки привязанности к воображаемой природе явлений»</strong>, <strong>«признак упорной привязанности к воображаемой собственной природе явлений»</strong> (<em>bhāva-vikalpa-svabhāva-abhiniveśa-lakṣaṇa</em>) — термин описывает трёхступенчатую ловушку: различающий ум (<em>vikalpa</em>) разделяет опыт на отдельные явления (<em>bhāva</em>), наделяет их ложной собственной природой (<em>svabhāva</em>), и упорно цепляется (<em>abhiniveśa</em>) за эти проекции как за реальность. Для бодхисаттвы распознать этот признак — значит увидеть, что вся «плотность» мира держится лишь на инерции различающего ума, принимающего свои проекции за независимые сущности.<a href="#ref-244" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-245"><sup>245</sup> <em>Нила-пита-ушна-драва-чала-катхина</em> (<em>nīla-pīta-uṣṇa-drava-cala-kaṭhina</em>) — перечисление чувственных признаков, которые шраваки принимают за реальные свойства великих элементов (<em>mahābhūta</em>): <em>nīla, pīta</em> — цветовые аспекты формы (<em>rūpa</em>), <em>uṣṇa</em> — жар (огонь), <em>drava</em> — текучесть (вода), <em>cala</em> — движение (ветер), <em>kaṭhina</em> — твёрдость (земля). Хотя эти признаки введены в учении как условные обозначения для анализа опыта, шраваки, удерживаясь в рамках отсутствия «я» личности, не проникают в отсутствия «я» дхарм  и поэтому овеществляют элементы, наделяя их собственной природой. Это и есть привязанность к воображаемой природе (<em>parikalpita-svabhāva-abhiniveśa</em>) — принятие аналитических построений за реальные сущности.<a href="#ref-245" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-246"><sup>246</sup> <em>anitya-bhāva-vilakṣaṇa-hetutvāt</em> — «по причине [желания найти] иное по отношению к непостоянному бытию». Тиртхики строят свою «<strong>Вечность</strong>» на отталкивании от изменчивости мира. Но если ваша вечность зависит от непостоянства (как его противоположность), она не абсолютна.<a href="#ref-246" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-247"><sup>247</sup> <em>na svakṛta-hetu-lakṣaṇa-prabhāvitā</em> — буквально: «[состояние], не явленное/не порождённое через признаки своих собственных причин».<a href="#ref-247" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-248"><sup>248</sup> <em>vāg-vikalpa-mātra</em> — «словесная раздутость», когда ум плодит определения, не имея под ними живого опыта.<a href="#ref-248" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-249"><sup>249</sup> <em>pratyātmāryādhigama-lakṣaṇa</em><a href="#ref-249" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-250"><sup>250</sup> <em>kṛtaka-bhāva-abhāva-varjita.</em> Тиртхики видят мир как «сотворённый» и потому разрушимый, а свою вечность — как нечто «несотворённое». Будда же «свободен» (<em>varjita</em>) от самой этой пары. Его состояние не является ни «сотворённым», ни «несотворённым», так как оно лежит за пределами логики возникновения. Это радикальное «ни то, ни другое», которое оставляет логиков в тупике.<a href="#ref-250" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-251"><sup>251</sup> <strong>«Рассудочное умозаключение на основе
                внешнего»</strong> (<em>bāhya-bhāva-anitya-anumāna</em>). Тиртхики смотрят на внешний
            мир (<em>bāhya-bhāva</em>), видят, что он распадается (<em>anitya</em>), и логически
            делают вывод: «значит, должно быть что-то вечное». Будда называет это «гаданием по
            признакам». Ошибка здесь в том, что они принимают «внешний мир» за реальную точку отсчёта
            . Для <strong><em>Ланкаватары</em></strong> внешний мир — это галлюцинация ума, поэтому строить на
            его «непостоянстве» выводы о Вечности — всё равно что изучать законы оптики по отражению в кривом зеркале.<a href="#ref-251" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-252"><sup>252</sup> <em>svacitta-dṛśya-gocara</em><a href="#ref-252" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-253"><sup>253</sup> <em>bāhya-citta-dṛśya-gocara</em> —
            буквально "сфера видимого вне ума", то есть они принимают объекты за независимо существующие (<em>bāhya</em>), не понимая, что эти объекты — проекции самого ума (<em>citta-dṛśya</em>).<a href="#ref-253" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-254"><sup>254</sup> <em>pañcābhisamaya-gotrāṇi</em><a href="#ref-254" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-255"><sup>255</sup> <em>śrāvakayānābhisamaya-gotra</em><a href="#ref-255" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-256"><sup>256</sup> <em>pratyekabuddhayānābhisamaya-gotra</em><a href="#ref-256" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-257"><sup>257</sup> <em>tathāgatayānābhisamaya-gotra</em><a href="#ref-257" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-258"><sup>258</sup> <em>aniyata-ekatara-gotra</em><a href="#ref-258" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-259"><sup>259</sup> <em>agotra</em><a href="#ref-259" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-260"><sup>260</sup> <em>ṣaṭ-pañcamyāṃ bhūmau</em> — «на пятой или шестой ступени». Хотя шраваки не проходят «ступени» (<em>bhūmi</em>) бодхисаттв, здесь Будда использует терминологию <em>бхуми</em> условно, указывая, что даже на уровне духовного развития, сопоставимом с пятой-шестой ступенью бодхисаттвы, шравак, не постигший <em>dharma-nairātmya</em>, остаётся связан отпечатками клеш (<em>kleśa-vāsanā</em>).<a href="#ref-260" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-261"><sup>261</sup> <em>ātma-sattva-jīva-poṣa-puruṣa-pudgala-sattva-avabodhāt</em> — Данный перечень представляет собой своего рода «каталог заблуждений» относительно природы личности, последовательно разоблачающий все основные способы, которыми индийская мысль пыталась наделить индивидуальное существование некой реальностью. Включение в один ряд <em>Атмана</em>, <em>Пуруши</em>, <em>Дживы</em> и <em>Пудгалы</em> призвано показать, что при всем различии терминов за ними стоит одна и та же ошибка познания — попытка найти неизменного «хозяина» внутри изменчивого потока опыта.<br><br>Исторически этот список направлен против главных философских оппонентов Будды того времени. Отрицая <em>Атмана</em>, сутра бьет по брахманистскому учению о вечной душе; отвергая <em>Пурушу</em>, она разрушает двойственность школы Санкхья, видевшей в нем чистого, отделенного от материи свидетеля; отрицание <em>Дживы</em> направлено против джайнов с их представлением о живой сущности как носителя жизненной силы. Особое значение имеет включение в список <em>Пудгалы</em> — «личности», которую пытались утвердить некоторые ранние буддийские школы (<em>пудгалавадины</em>) как реального носителя кармического груза. <strong><em>Ланкаватара</em></strong> определяет <em>пудгалу</em> как еще одну форму «словесной раздутости», скрывающую отсутствие «Я». Все эти категории рассматриваются не как реальные сущности, а как номинальные обозначения, не имеющие под собой объективной основы. Постижение их ложности (<em>avabodhāt</em>) освобождает ум от точки привязанности — «схватывающего» субъекта. Только когда ум распознает, что ни один из этих терминов не описывает реального «Я», он перестает проецировать «владельца» опыта и совершает окончательный поворот основы, раскрываясь как недвойственная мудрость, где нет места ни душе, ни индивиду.<a href="#ref-261" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-262"><sup>262</sup> <em>aniryāṇa-niryāṇa-buddhiḥ</em> — «разум, различающий "выход" и "не-выход"». Будда критикует интеллектуальную установку, при которой освобождение воспринимается как реальный переход из «плена» сансары в «свободу» нирваны. Такая позиция остается двойственной и опирающейся на понятия. Для бодхисаттвы истинное освобождение заключается в распознавании того, что и «плен», и «выход» — лишь проекции ума, не имеющие собственной основы. Оставить этот «разум выхода» — значит постичь исконное тождество сансары и нирваны (<em>saṃsāra-nirvāṇa-samatā</em>) — поскольку ничто никогда не было связано и не нуждается в освобождении.<a href="#ref-262" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-263"><sup>263</sup> <em>svabhāva-niḥsvabhāva-dharma-abhisamaya-gotra.</em> Этот род постижения основан на основополагающем парадоксе махаяны: единственная подлинная «природа» (<em>svabhāva</em>) любого явления заключается в том, что у него полностью отсутствует какая-либо неизменная, независимая сущность (<em>niḥsvabhāva</em>). Бодхисаттва, принадлежащий к этому «роду», не просто верит в шуньяту, он видит мир как совершенно пластичный поток причин и условий. Это прозрение лишает сознание ложных опор в «плотных» объектах, подготавливая его к пониманию реальности как <em>воспринимаемой собственным умом</em>.<a href="#ref-263" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-264"><sup>264</sup> <em>adhigama-sva-pratyātmārya-abhisamaya-gotra.</em> Слово <em>adhigama</em> (достижение/прибытие) указывает на то, что истина не заимствуется извне (из книг или слов), а открывается как глубоко личный, недвойственный опыт (<em>sva-pratyātma</em>). Принадлежность к этой готре означает, что мудрость бодхисаттвы больше не нуждается во внешних доказательствах, так как <em>таковость</em> сияет в нем как его собственная проживаемая данность.<a href="#ref-264" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-265"><sup>265</sup> <em>bāhya-buddhakṣetra-udārya-abhisamaya-gotra.</em> Хотя йогачара учит, что всё есть ум, «внешние» (<em>bāhya</em>) земли Будд рассматриваются здесь как бесконечные горизонты проявления сострадания. Постигая их «величия» (<em>udārya</em>), бодхисаттва выходит за пределы личного спасения и обретает способность беспрепятственно проявляться в любых мирах ради блага других существ. Это вхождение в сферу искусных средств (<em>упая</em>), где «внешняя» реальность распознается как столь же прозрачная и податливая мудрости, как и сам ум.<a href="#ref-265" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-266"><sup>266</sup> <strong>«Благословение Татхагат»</strong>, <strong>«сила удержания»</strong> (<em>tathāgatādhiṣṭhāna</em>) — проявление изначального единства бодхисаттвы и Татхагат: их природа одна — Таковость (<em>tathatā</em>). Будды «не оставляют» ни одного существа, их <em>adhiṣṭhāna</em> действует как естественное движение сострадания.<a href="#ref-266" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-267"><sup>267</sup> Бодхисаттва реализует «непребывающую нирвану» (<em>apratiṣṭhita-nirvāṇa</em>), которая не является ни сансарой, ни статичным покоем.<a href="#ref-267" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-268"><sup>268</sup> <strong>«Три признака собственных природ»</strong> (<em>svabhāva-lakṣaṇa-traya</em>) — воображаемая природа (<em>parikalpita</em>) (мир двойственности и имен), зависимая природа (<em>paratantra</em>) (поток причин и условий) и совершенная природа (<em>pariniṣpanna</em>) (Таковость). При этом важно понимать, что <em>parikalpita</em> — единственная полностью иллюзорная природа; <em>paratantra</em> — условно реальна (поток причин существует, но лишён собственной природы); <em>pariniṣpanna</em> — абсолютно реальна, ибо есть сама Таковость.<a href="#ref-268" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-269"><sup>269</sup> <strong>Нимитта</strong> (<em>nimitta</em>) — метка качества-характеристики, которую наш ум накладывает на поток опыта. В системе пяти <em>дхарм нимитта</em> — первая: за ней следуют <em>имя</em> (<em>nāma</em>), <em>различение</em> (<em>vikalpa</em>), <em>правильное знание</em> (<em>samyag-jñāna</em>) и Таковость (<em>tathatā</em>). Первые три принадлежат сфере ложного воображения; последние два — сфере освобождения. Если «имя» (<em>nāma</em>) — это ярлык в языке, то «признак» — это то, что мы «видим» как плотную характеристику вещи: её цвет, форму, твердость или протяженность. Ум выхватывает из безбрежного океана <em>Алайи</em> отдельные качества и «замораживает» их, создавая иллюзию устойчивого объекта. Без признака ум не мог бы «схватить» реальность. Мы привязываемся не к вещам, а к их признакам (приятное, постоянное, «мое»). Именно <em>нимитта</em> делает возможной двойственность «субъекта» и «объекта», создавая поле для работы различающего сознания (<em>викальпы</em>). Практика бодхисаттвы направлена на <em>анимитту</em> — «беспризнаковость».<a href="#ref-269" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-270"><sup>270</sup> <strong>«Основа, признак, характеристика и внешняя форма»</strong> (<em>vastu-nimitta-lakṣaṇa-ākāra</em>) — В <strong><em>Ланкаватаре</em></strong> эта цепочка раскрывает механику ложного воображения (<em>abhūta-parikalpa</em>). Будда показывает, как ум строит иллюзию, последовательно наделяя её деталями: <em>Васту</em> (<em>vastu</em>) — «Основа» или «точка фиксации», первичное выделение в океане <em>Алайи</em>. Ум «выхватывает» некое ментальное пятно, принимая его за независимую «вещь». <em>Нимитта</em> (<em>nimitta</em>) — «Признак» или «образ». На выбранную основу ум накладывает общую метку (например, «зримое» или «твёрдое»). Это — первый импульс выделения объекта из фона. <em>Лакшана</em> (<em>lakṣaṇa</em>) — «Характеристика» или «специфический признак». Здесь объект обретает детальные качества: цвет, размер, плотность. Это этап «раскрашивания» ментального образа, придающий ему уникальность. <em>Акара</em> (<em>ākāra</em>) — «Внешняя форма» или «вид». Финальная стадия, на которой объект предстаёт перед сознанием как завершённая, оформленная и «внешняя» фигура. Именно здесь возникает окончательная вера в то, что мир существует «снаружи».<a href="#ref-270" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-271"><sup>271</sup> <strong>«Признак привязанности к именам»</strong> (<em>nāma-abhiniveśa-lakṣaṇa</em>) — он описывает лингвистический плен сознания. Слово «имя» (<em>nāma</em>) здесь означает не только названия предметов, но и все понятия, которыми мы пользуемся. Ум обладает безначальной привычкой (<em>vāsanā</em>) наделять слова статусом реальности, значимости. Как только мы даем явлению имя, мы мгновенно приписываем этому слову плотную, неизменную суть. Термин <em>абхинивеша</em> (упорствование, вязкая привязанность) указывает на то, что сознание «прикипает» к именам и начинаем взаимодействовать с миром «ярлыков». Но имена — это лишь условные соглашения (<em>saṃketa</em>), не имеющие под собой никакой основы (<em>vastu</em>).<a href="#ref-271" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-272"><sup>272</sup> <strong>«Признак привязанности к объектам через их наименования»</strong> (<em>nāma-vastu-nimitta-abhiniveśa-lakṣaṇa</em>) — финальный этап цепи ложного воображения: ум склеивает имя (<em>nāma</em>, например, «кувшин») с чувственными признаками (<em>nimitta</em> — форма, цвет, твёрдость) и рождает иллюзию самостоятельного объекта (<em>vastu</em>). Эта «склейка» создаёт веру в существование внешнего мира, обладающего собственной сутью, тогда как на деле за именами и формами — лишь поток опыта, лишённый основы. Распознав этот механизм, бодхисаттва видит мир как прозрачную игру ума — «словесную конструкцию», в которой нет ни «вещей», ни «схватывающего».<a href="#ref-272" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-273"><sup>273</sup> <strong>«Внутренние и внешние дхармы»</strong> (<em>adhyātma-bāhya-dharma</em>) — привязанность к объектам не ограничивается внешним миром Ум «овеществляет» даже психические состояния — мысли, ощущения, самоощущение — наделяя их ложной плотностью и превращая в объекты обладания.<a href="#ref-273" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-274"><sup>274</sup> <strong>«Ложное понимание собственных и общих признаков»</strong> (<em>sva-sāmānya-lakṣaṇa-parijñāna-avabodha</em>) — Будда указывает на два типа признаков, за которые цепляется ум:<br>— собственные признаки (<em>sva-lakṣaṇa</em>) — качества, кажущиеся «уникальными»: твёрдость земли, текучесть воды, черты лица. Они принимаются как внутренние свойства вещей, наделяя их некой сущностью (<em>svabhāva</em>);<br>— общие признаки (<em>sāmānya-lakṣaṇa</em>) — универсальные категории: «все кувшины», «все люди», «всё непостоянное». Это уровень абстрактного, обобщающего мышления, где ум группирует опыт по схемам, категориям, группам.<br>Здесь <em>parijñāna</em> и <em>avabodha</em> используются иронически — это не истинное постижение, а самоуверенное «знание» различающего ума, принимающего свои классификации за реальность.<a href="#ref-274" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-275"><sup>275</sup> Процесс построения «плотной реальности» разворачивается в строгой последовательности. Всё начинается с внутреннего «зуда» неведения (<em>ajñāna</em>) — основополагающей слепоты познания, неспособности распознать в текущем опыте его истинную, пустотную природу (<em>шуньяту</em>). Это неведение направляется кармой — накопленной инерцией прошлых привычек — и подпитывается жаждой (<em>tṛṣṇā</em>). Жажда заставляет сознание «выбрасываться» вовне в поисках опоры, превращая покой океана <em>Алайи</em> в движение активных сознаний. Когда органы чувств встречаются с потоком данных, происходит мгновенное «слипание» (<em>abhiniveśa</em>). Ум не просто отражает форму, он «хватается» за неё (<em>grahaṇa</em>), наделяя её статусом независимого объекта. В этот момент возникает разделение на «воспринимающего» и «воспринимаемое». Именно процесс захвата признака «овеществляет» пустотный опыт, придавая ему видимую плотность и внешнее положение. В ответ на акт захвата сознание-хранилище (<em>Алайя-виджняна</em>) мгновенно развёртывает целостную галлюцинацию:<br>— Обитель (<em>bhājana</em>) — пространство/ мир-вместилище (сцена действия);<br>— Тело (<em>deha</em>) — совокупность процессов (актёр);<br>— Объекты/ предметы наслаждения (<em>bhoga</em>) — объекты восприятия (реквизит).<br><br>Важнейшее утверждение <strong><em>Ланкаватары</em></strong> состоит в том, что тело не находится в мире, а мир не находится вне тела. Оба — равноправные проекции одного ума (<em>svacitta-dṛśya</em>). Это единое явление, которое ошибочно разделяется на «внутреннее» и «внешнее».<br><br>Итогом становится «воображение различениями собственного ума». Использование двойного корня «викальп» в оригинале указывает на взаимообращающийся, самоподдерживающийся характер иллюзии. Ум не просто выдумывает мир; он структурирует его через бесконечные разделения (субъект/объект, приятное/болезненное, я/другой). Эти различения (<em>vikalpa</em>) наслаиваются друг на друга, создавая вязкую сеть понятий, в которой ум запутывается, как в паутине, принимая плоды собственного воображения за независимую и твердую реальность.<a href="#ref-275" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-276"><sup>276</sup> Постижение отсутствия «я» в личности (<em>pudgala-nairātmya</em>) раскрывается через ряд точных метафор, обнажающих кажущуюся устойчивость существования. Иллюзия «дления» личности во времени объясняется через образы реки, ростка, светильника, ветра и облака. Подобно реке, которая кажется неизменной, хотя в каждый миг в ней течет новая вода, или ростку, который видится единым процессом, являясь лишь непрерывной сменой состояний, — так и совокупность <em>скандх</em> есть лишь мгновенная преемственность (<em>kṣaṇa-paramparā</em>). Как пламя светильника создаёт видимость одного огня через череду сгорающих частиц масла, или как ветер и облако постоянно меняют форму, не имея какого-либо центра, так и личность распадается и пересобирается в каждое мгновение.<br><br>Ум, подобно обезьяне, не может остановиться ни на секунду, вечно прыгая по веткам объектов, а суетливость сознания, инстинктивно ищущего, к чему бы «прилипнуть» в поисках удовольствия, уподоблена мухе. Сами же стремления ненасытны, словно бушующий огонь: чем больше «дров» в виде впечатлений в него бросаем, тем сильнее разгорается жажда, поддерживая горение этой иллюзии.<br><br>Цикличность и автоматизм нашего существования уподоблены колодезному колесу (<em>araghaṭṭa</em>) с прикрепленными к нему кувшинами. Как колесо принудительно вращается, то опуская кувшины в мутную глубину, то поднимая их к поверхности, так и личность вращается в круговороте сансары. Это движение не управляется волей «Я», оно движимо лишь тяжестью накопленных отпечатков безначального многообразия (<em>anādi-prapañca -vāsanā</em>).<br><br>В конечном итоге Будда лишает личность самой «живости», уподобляя её механической кукле (янтра) или магической иллюзии. Внутри этого аппарата нет души; «кукла» движется лишь потому, что натянуты нити кармы и дуют ветры прошлых привычек. Это «оживленный труп». Знание, прозревающее эти признаки, именуется знанием об отсутствии «я» в личности. Оно превращает «хозяина жизни» в прозрачный, закономерный и никем не управляемый поток элементов, окончательно лишая его ложной плотности и власти эго.<a href="#ref-276" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-277"><sup>277</sup> Будда здесь совершает двойное отрицание, ведущее к полному растворению иллюзии плотности <em>скандх</em>. Первый уровень — <em>pudgala-nairātmya</em>: <em>скандхи</em> лишены «я» — нет хозяина потока, есть лишь совокупность факторов, движимых причиной, кармой и жаждой. Второй уровень — <em>dharma-nairātmya:</em> сами <em>скандхи</em> лишены собственных (<em>sva-lakṣaṇa</em>) и общих признаков (<em>sāmānya-lakṣaṇa</em>). Их «твёрдость», «форма», «непостоянство» — проекции различающего ума. Термин — <em>abhūta-parikalpa</em> («ложное воображение несуществующего») указывает, что <em>скандхи</em> хотя и пусты, но воображаются как плотные.<a href="#ref-277" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-278"><sup>278</sup> Отрицание возникновения в данном фрагменте строится на разрушении идеи причинности: дхармы не возникают «сами по себе» (<em>svataḥ</em>), так как это предполагало бы наличие изначальной сущности, и не возникают «извне» (<em>parataḥ</em>), так как в высшем смысле нет объектов, отделенных от ума. Упоминание «состояния взаимного схождения условий» (<em>saṃghātāvasthā</em>) указывает на то, что любая «вещь» — это лишь временное сочетание факторов (<em>скандх</em> и элементов). Поскольку эти условия сами лишены основы, их совокупность не порождает новой реальности. Довод об отсутствии «непрерывной цепи» (<em>prabandha-abhāva</em>) подчеркивает теорию мгновенности (<em>kṣaṇika-vāda</em>): поток опыта состоит из отдельных вспышек, между которыми нет связующего «клея». Таким образом, «изменчивость» явлений — это иллюзия познания, возникающая при наложении идеи длительности на «выделяемые» моменты ума.<a href="#ref-278" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-279"><sup>279</sup> Принцип недвойственности здесь раскрывается через относительность понятий: «свет» и «тень» не являются отдельными сущностями — они возникают как парные проекции различения. Будда применяет это и к паре «сансара и нирвана». Их недвойственность/тождественность не означает, что они идентичны или смешаны — ни одна из них не обладает самостоятельным бытием. В опыте они исключают друг друга: нельзя одновременно пребывать в заблуждении и в ясном видении. Но на глубинном уровне они — два способа восприятия потока, лишённого сущности. Разделение между миром страданий и освобождением существует только в языке и различении ума. За пределами этих «ярлыков» нет ни единства, ни частей, есть лишь недвойственное видение, свободное от всех умопостроений.<a href="#ref-279" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-280"><sup>280</sup> Здесь звучит предостережение от двух крайностей: нигилизма («ничто не имеет значения») и догматизма («Нирвана — вечная реальность»). Хотя и утверждается, что сансара подобна сну — но пока ум не пробуждён, инерция кармы продолжает формировать его события. С другой стороны Нирвана — не «вечное прибежище», не объект, который «есть», и не пустота, которой «нет». Для Благородных — это свобода от необходимости приписывать реальности ярлыки «существует» или «не существует». Называть её «несотворённой» (<em>akṛtaka</em>) — лишь педагогический приём, а не описание сущности.<a href="#ref-280" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-281"><sup>281</sup> Вопрос Махамати касается ловушки причинно-условной модели. В индийской философии дебаты велись вокруг того, возникают ли вещи последовательно (<em>anukrama</em>) или одновременно (<em>yugapad</em>). Однако с позиции «только-ума» оба эти представления ошибочны, так как предполагают, что «нечто» реально переходит из состояния небытия в состояние бытия. Махамати просит разъяснить «признак причинно-условной природы» именно для того, чтобы распознать в ней плод ложного воображения. Постижение <em>hetu-pratyaya</em> ведёт к осознанию того, что ни один объект не имеет собственной природы (<em>niḥsvabhāva</em>), а значит, ничто никогда не возникало — ни мгновенно, ни постепенно.<a href="#ref-281" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-282"><sup>282</sup> Внешнее зависимое возникновение (<em>bāhya-pratītyasamutpāda</em>) рассматривается здесь через призму условий (<em>pratyaya</em>): материального основания (глины) и сопутствующих факторов (гончарного круга, усилий человека и т.д.). Перечисляя эти примеры, Будда подводит Махамати к пониманию того, что ни один внешний объект не появляется из ниоткуда и не существует сам по себе. Фраза «каждое последующее обусловлено предшествующим» (<em>pūrvottarottara</em>) обнажает механизм формирования понятия времени: наш ум связывает разрозненные моменты опыта в линейную цепь, создавая иллюзию стабильного процесса возникновения кувшина или ростка, тогда как на самом деле это лишь поток мгновений, лишённых собственной природы.<a href="#ref-282" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-283"><sup>283</sup> Внутреннее зависимое возникновение (<em>ādhyātmika-pratītyasamutpāda</em>) описывает умозрительную обусловленность опыта. Будда указывает, что такие базовые элементы нашего существования, как тело, органы чувств и объекты восприятия (<em>скандхи, дхату, аятаны</em>), не являются самодостаточными сущностями. Они — лишь результат работы неведения, жажды и кармы. Ключевое утверждение о том, что эти процессы «неотличимы» (<em>aviśiṣṭāḥ</em>), разрушает иллюзию двойственности субъект-объект. С точки зрения «только-ума», внутренние омрачения и внешние формы — это единый поток воспринимаемого собственным умом. Только незрелый ум (<em>bāla</em>) воображает между ними качественную разницу, разделяя единый поток различений на «внутреннее Я» и «внешний мир».<a href="#ref-283" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-284"><sup>284</sup> То, что мы принимаем за «объективные законы мира», является набором функций различающего ума (<em>vikalpa</em>). Первые пять причин описывают механизм умозрительного построения и поддержания иллюзии сансары: от скрытого потенциала семян (<em>bhaviṣyad</em>) до их высвечивания в восприятии (<em>vyañjana</em>). Шестая причина — нейтральности (<em>upekṣā-hetu</em>) описывает момент затухания умопостроений. Когда ум перестаёт вовлекаться в процесс различения, инерция потока (<em>prabandha</em>) пресекается, что ведёт к реализации состояния <em>avikalpa</em> — непосредственного видения, не разделённого на субъект и объект.<a href="#ref-284" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-285"><sup>285</sup> Учение о четырёх видах речи в <strong><em>Ланкаватаре</em></strong> вскрывает механизмы, посредством которых язык подменяет реальность.<br><br>
            • Речь признаков фиксирует мир как набор устойчивых объектов.<br>
            • Речь сновидений показывает, что язык может оперировать объектами, которых нет «здесь и сейчас», создавая воображаемые миры.<br>
            • Речь косных различений (<em>dauṣṭhulya</em>) обнажает эмоциональную определённость языка: мы говорим, исходя из прошлых конфликтов и эмоций.<br>
            • Речь безначальных различений — это самый глубокий уровень, обусловленный <em>прапанчей</em> (умозрительным множащимся многословием), накопленным в <em>Алая-виджняне</em>.<br><br>
            Бодхисаттва должен осознать, что между «выражением» (<em>abhilāpa</em>) и «выражаемым» (<em>abhilāpya</em>) нет реальной связи; это разделение — лишь работа различающего ума, создающая иллюзию объективной реальности.<a href="#ref-285" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-286"><sup>286</sup> Здесь разбирается механизм речи, вычленяя грубый физический механизм артикуляции (<em>samavāya</em>) и тонкий процесс умственного различения (<em>vikalpa</em>). Ответ на вопрос о тождестве речи и мысли опирается на принцип зависимого возникновения: речь не является чем-то самостоятельным (она обусловлена мыслью), но и не растворяется в мысли полностью, так как обладает определённой функцией «проявления смысла» (<em>arthābhivyaktitvāt</em>) во внешнем мире. Привязанность к словам возникает именно тогда, когда ум принимает выражение (<em>abhilāpa</em>) за само выражаемое (<em>abhilāpya</em>), порождая иллюзию объективной реальности.<a href="#ref-286" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-287"><sup>287</sup> Здесь проводится граница между познанием посредством умозрительного построения сети различений (<em>vikalpa</em>) и благородным постижением (<em>āryajñāna</em>). Высший смысл (<em>paramārtha</em>) определяется как недвойственный опыт, принципиально невыразимый в словах. Будда подчёркивает, что любая словесное построение «мимолётно» (<em>capala</em>) и обусловлено, тогда как истина самодостоверна. Пример царя и глиняных игрушек объясняет назначение учения: все термины — включая «шуньята», «признаки» и «дхармы» — искусные средства (<em>упайя</em>), имеющие лишь воспитательную ценность и не являются «истинными зверями», они подготавливают ум к восприятию «предела истинности» (<em>bhūtakoṭi</em>), который лежит за пределами любого описания.<a href="#ref-287" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-288"><sup>288</sup> В данном фрагменте Будда использует три уровня разрушения иллюзии реальности. Метафора миража показывает, как <em>клеши</em> (страсть и гнев) заставляют нас бежать за несуществующим. Метафора города гандхарвов объясняет механизм проекции: мы видим мир лишь потому, что наш ум полон «семян-категорий/понятий/представлений». Наконец, метафора сна обнажает природу памяти и рождения образов-понятий: даже когда объект исчезает, мы продолжаем приписывать ему реальность. Главный посыл здесь — <em>svacittadṛśyamātrānavabodha</em> (непонимание того, что всё есть лишь воспринимаемое собственным умом). Именно это неведение превращает пустое пространство в тюрьму двойственности: «бытия» и «небытия», «единства» и «различия».<a href="#ref-288" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-289"><sup>289</sup> Этот ряд примеров (картина, волоски, огненное колесо, пузыри) служит для описания «бытия» явлений в системе Йогачары. Они не являются ни абсолютно реальными (<em>sat</em>), ни абсолютно отсутствующими (<em>asat</em>). Как пузырь кажется жемчугом лишь в силу ошибки зрения, так и мир кажется состоящим из внешних объектов лишь в силу «отпечатков» (<em>vāsanā</em>). Привязанность к двойственности «есть/нет» ведёт к потере понимания Срединного пути, превращая практикующего либо в фаталиста, либо в материалиста. Подлинное видение — это понимание всего происходящего как динамического потока восприятия (<em>svacittadṛśya</em>), лишённого какой-либо неизменной сущности, подобно огненному колесу, возникающему от вращения горящей палочки в темноте.<a href="#ref-289" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-290"><sup>290</sup> Использование цепочки метафор (мираж, волоски, огненное колесо, отражение, механическая кукла, призрак, сын бесплодной женщины) указывает и на иллюзорность мира, и на метод освобождения. Ключевым является принцип «клин клином вышибают»: хотя употребляемые слова и понятия сами по себе не являются истиной, они служат инструментами для удаления грубых заблуждений. Когда цепляние за «бытие» и «небытие» устранено, инструмент должен быть оставлен, что ведёт к состоянию, в котором мудрец «не берёт на себя никаких утверждений» (<em>na kiṃcit pratijānate</em>), оставив все воззрения на бытие и небытие.<a href="#ref-290" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
    </div>

@endsection
